@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";
@import "leaflet/dist/leaflet.css";

@custom-variant dark (&:is(.dark *));

.member-mining {
  --mining-gold: oklch(.84 .12 85);
  --mining-edge: color-mix(in oklch,var(--mining-gold) 65%,var(--border));
  --mining-glass: color-mix(in oklch,var(--foreground) 5%,transparent);
  --mining-reflection: color-mix(in oklch,var(--foreground) 9%,transparent);
  --mining-shadow: 0 6px 24px color-mix(in oklch,var(--background) 30%,transparent);
  max-width:680px; margin-inline:auto; padding:20px;
  background:transparent; font-family:'DM Sans',sans-serif; letter-spacing:0;
}
.mining-heading { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:12px; }
.mining-heading h2 { font-family:'Space Grotesk',sans-serif; font-size:22px; font-weight:700; }
.mining-heading > span { display:flex; align-items:center; gap:6px; font-size:11px; }
.mining-verified { color:var(--chart-2); }
.mining-unverified { color:var(--muted-foreground); }
.mining-engine { position:relative; width:100%; height:260px; margin:16px auto; }
.mining-engine video { width:auto; max-width:100%; height:100%; margin-inline:auto; display:block; object-fit:contain; mask-image:radial-gradient(ellipse at center,var(--foreground) 58%,transparent 100%); }
.mining-video-control { position:absolute; right:0; bottom:0; border-color:var(--mining-edge); color:var(--mining-gold); background:var(--mining-glass); }
.mining-figures { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
.mining-figures > div { min-width:0; padding:12px 10px; text-align:center; }
.mining-figures > div:nth-child(odd) { border-right:1px solid var(--border); }
.mining-figures > div:nth-child(n+3) { border-top:1px solid var(--border); }
.mining-figures dt { color:var(--muted-foreground); font-size:12px; }
.mining-figures dd { margin-top:5px; font-family:'Space Grotesk',sans-serif; font-size:22px; font-variant-numeric:tabular-nums lining-nums; }
.mining-figures dd small { font-size:14px; }
.mining-figures dd.mining-pending { font-size:13px; line-height:22px; color:var(--muted-foreground); }
.mining-availability { display:flex; align-items:center; justify-content:center; gap:6px; margin:12px 0; font-size:10px; color:var(--muted-foreground); }
.mining-start { width:100%; height:46px; border-color:var(--mining-edge); color:var(--mining-gold); background:linear-gradient(120deg,var(--mining-reflection),transparent),var(--mining-glass); box-shadow:var(--mining-shadow); }
.mining-start:disabled { opacity:.8; }
.mining-state { margin:12px 0; text-align:center; font-size:11px; line-height:1.6; color:var(--muted-foreground); }
.mining-disclosures { padding-top:12px; border-top:1px solid var(--border); text-align:center; font-size:10px; line-height:1.8; color:var(--muted-foreground); }
.mining-disclosures strong { font-weight:500; color:var(--mining-gold); font-variant-numeric:tabular-nums; }
html[data-color-mode="light"] .member-mining { --mining-gold:oklch(.5 .1 85); }
@media(max-width:480px) { .member-mining { padding:16px 12px; } .mining-engine { height:220px; } .mining-heading h2 { font-size:20px; } }

.landing-tokenomics {
  --token-cyan: oklch(0.78 0.14 210);
  --token-emerald: oklch(0.76 0.18 160);
  --token-violet: oklch(0.68 0.2 300);
  --token-magenta: oklch(0.69 0.21 335);
  --token-gold: oklch(0.83 0.17 85);
  --token-coral: oklch(0.72 0.17 30);
  --token-glass: color-mix(in oklch, var(--foreground) 4%, var(--background));
  --token-edge: color-mix(in oklch, var(--token-cyan) 24%, var(--border));
  background: var(--background); letter-spacing: 0;
}
.tokenomics-heading { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:16px; }
.tokenomics-heading h2 span { color:var(--token-cyan); }
.site-shell .member-tokenomics { font-family:'DM Sans',sans-serif; letter-spacing:0; }
.site-shell .member-tokenomics :is(h2,h3,.font-display,.tokenomics-supply strong,.tokenomics-donut strong,.tokenomics-allocation-head strong,.tokenomics-allocation-amount,.tokenomics-number) { font-family:'Space Grotesk',sans-serif; letter-spacing:0; }
.member-tokenomics :is(.tokenomics-supply strong,.tokenomics-donut strong,.tokenomics-allocation-head strong,.tokenomics-allocation-amount,.tokenomics-number) { font-variant-numeric:tabular-nums lining-nums; }
.member-tokenomics .tokenomics-allocation-head { align-items:start; }
.member-tokenomics .tokenomics-allocation h3 { min-height:39px; font-weight:700; }
.member-tokenomics .tokenomics-allocation-amount { font-size:14px; line-height:1.5; white-space:nowrap; }
.member-tokenomics .tokenomics-allocation p { font-size:12px; line-height:1.65; }
.tokenomics-status { color:var(--muted-foreground); font-size:10px; border:1px solid var(--token-edge); padding:7px 10px; border-radius:4px; }
.tokenomics-main { display:grid; grid-template-columns:minmax(0,.85fr) minmax(0,1.5fr); gap:40px; margin-top:36px; align-items:start; }
.tokenomics-supply { margin:0; padding:24px 0; }
.tokenomics-supply figcaption { text-align:center; }
.tokenomics-supply figcaption small { display:block; font-size:10px; color:var(--muted-foreground); }
.tokenomics-supply figcaption strong { display:block; font-size:30px; color:var(--token-gold); margin-top:8px; font-variant-numeric:tabular-nums; }
.tokenomics-supply figcaption strong span { font-size:16px; }
.tokenomics-donut { width:280px; max-width:100%; aspect-ratio:1; border-radius:50%; margin:28px auto 0; padding:38px; background:conic-gradient(var(--token-cyan) 0% 50%,var(--token-emerald) 50% 65%,var(--token-violet) 65% 75%,var(--token-magenta) 75% 85%,var(--token-gold) 85% 95%,var(--token-coral) 95% 100%); box-shadow:0 0 30px color-mix(in oklch,var(--token-cyan) 12%,transparent); }
.tokenomics-donut > div { width:100%; height:100%; border-radius:50%; display:flex; align-items:center; justify-content:center; flex-direction:column; background:var(--background); border:1px solid var(--token-edge); }
.tokenomics-donut strong { font-size:44px; font-weight:800; color:var(--foreground); }
.tokenomics-donut span { font-size:13px; color:var(--muted-foreground); }
.tokenomics-donut small { font-size:7px; margin-top:10px; color:var(--muted-foreground); }
.tokenomics-allocations { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.tokenomics-category-0 { --allocation:var(--token-cyan); }
.tokenomics-category-1 { --allocation:var(--token-emerald); }
.tokenomics-category-2 { --allocation:var(--token-violet); }
.tokenomics-category-3 { --allocation:var(--token-magenta); }
.tokenomics-category-4 { --allocation:var(--token-gold); }
.tokenomics-category-5 { --allocation:var(--token-coral); }
.tokenomics-allocation { min-width:0; border:1px solid var(--token-edge); border-top:2px solid var(--allocation); padding:16px; border-radius:8px; background:linear-gradient(125deg,color-mix(in oklch,var(--allocation) 7%,var(--token-glass)),var(--token-glass)); backdrop-filter:blur(12px); }
.tokenomics-allocation-head { display:grid; grid-template-columns:20px minmax(0,1fr) auto; align-items:start; gap:8px; }
.tokenomics-number { font-size:10px; padding-top:3px; color:var(--muted-foreground); }
.tokenomics-allocation h3 { font-size:13px; line-height:1.5; font-weight:700; }
.tokenomics-allocation-head strong { font-size:20px; line-height:1.2; color:var(--allocation); }
.tokenomics-allocation-amount { margin:10px 0; font-size:14px; font-weight:700; font-variant-numeric:tabular-nums; }
.tokenomics-allocation p { font-size:11px; line-height:1.7; color:var(--muted-foreground); }
.tokenomics-schedule { display:block; margin-top:12px; border-top:1px solid var(--border); padding-top:10px; font-size:10px; line-height:1.6; color:var(--muted-foreground); }
.tokenomics-purpose { display:grid; grid-template-columns:1fr 1fr; gap:18px; margin-top:36px; }
.tokenomics-purpose > div { position:relative; overflow:hidden; padding:24px; border-radius:18px; border:1px solid color-mix(in oklab, #E7C77A 22%, transparent); background:linear-gradient(145deg, color-mix(in oklab, #E7C77A 10%, transparent), color-mix(in oklab, var(--background) 72%, transparent) 55%); backdrop-filter:blur(16px); box-shadow:inset 0 1px 0 color-mix(in oklab, #fff 10%, transparent), 0 18px 40px -24px color-mix(in oklab, #E7C77A 35%, transparent); }
.tokenomics-purpose > div::after { content:""; position:absolute; right:-24px; bottom:-24px; width:130px; height:130px; background:url('/favicon.png') center/contain no-repeat; opacity:.06; pointer-events:none; }
.tokenomics-purpose h3 { display:flex; align-items:center; gap:10px; color:#E7C77A; font-weight:700; font-size:15px; letter-spacing:.18em; }
.tokenomics-purpose p,.tokenomics-purpose ol { position:relative; margin-top:16px; font-size:13px; line-height:1.8; color:var(--muted-foreground); }
.tokenomics-purpose li { display:flex; gap:12px; margin-top:10px; align-items:flex-start; }
.tokenomics-purpose li span { flex-shrink:0; display:grid; place-items:center; width:30px; height:24px; border-radius:6px; border:1px solid color-mix(in oklab, #E7C77A 45%, transparent); background:color-mix(in oklab, #E7C77A 12%, transparent); color:#E7C77A; font-size:10px; font-weight:700; font-family:ui-monospace,monospace; box-shadow:0 0 12px -4px #E7C77A; }
.tokenomics-poster-band { display:grid; grid-template-columns:160px minmax(0,1fr); align-items:center; gap:28px; padding:28px 0; }
.tokenomics-poster-band img { width:160px; height:auto; border:1px solid var(--token-edge); border-radius:4px; }
.tokenomics-disclosure { display:flex; align-items:flex-start; gap:10px; padding-top:20px; border-top:1px solid var(--border); font-size:11px; line-height:1.8; color:var(--muted-foreground); }
.tokenomics-disclosure svg { flex-shrink:0; margin-top:3px; }
html[data-color-mode="light"] .landing-tokenomics { --token-cyan:oklch(.48 .1 210); --token-emerald:oklch(.48 .13 160); --token-violet:oklch(.5 .2 300); --token-magenta:oklch(.48 .19 335); --token-gold:oklch(.52 .11 85); --token-coral:oklch(.5 .16 30); }
@media(max-width:767px) {
  .tokenomics-main { grid-template-columns:minmax(0,1fr); gap:16px; margin-top:20px; }
  .tokenomics-supply { padding:12px 0; }
  .tokenomics-donut { width:240px; padding:32px; }
  .tokenomics-purpose { grid-template-columns:minmax(0,1fr); gap:14px; }
  .tokenomics-allocations { gap:10px; }
  .tokenomics-allocation { padding:12px; }
  .tokenomics-allocation-head { grid-template-columns:minmax(0,1fr) auto; gap:6px; }
  .tokenomics-number { display:none; }
  .tokenomics-allocation h3 { font-size:11px; }
  .tokenomics-allocation-head strong { font-size:17px; }
  .tokenomics-allocation-amount { font-size:12px; }
  .tokenomics-poster-band { grid-template-columns:100px minmax(0,1fr); gap:16px; }
  .tokenomics-poster-band img { width:100px; }
}
@media(prefers-reduced-motion:no-preference) { .tokenomics-donut { animation:tokenomics-reveal .65s ease-out both; } }
@keyframes tokenomics-reveal { from { opacity:0; transform:translateY(8px); } to { opacity:1; transform:translateY(0); } }

:root {
  --reactor-stage: oklch(0.14 0.025 260);
  --reactor-glass: oklch(0.98 0 0 / 7%);
  --reactor-edge: oklch(0.98 0 0 / 24%);
  --reactor-ink: oklch(0.97 0.01 90);
  --reactor-gold: oklch(0.84 0.15 85);
  --reactor-shadow: 0 12px 40px oklch(0.05 0 0 / 24%);
}
.reactor-glass-stage { position: relative; isolation: isolate; width: 100%; max-width: 680px; aspect-ratio: 720 / 544; margin: 32px auto 20px; background: transparent; border-radius: 8px; }
.reactor-glass-stage::after { content: none; }
.reactor-glass-video { width: 100%; height: 100%; display: block; object-fit: contain; border-radius: inherit; mask-image: radial-gradient(ellipse at center, var(--reactor-ink) 58%, transparent 100%); }
.reactor-glass-lens { position: absolute; top: -18px; right: 8px; width: 100px; height: 100px; border: 1px solid var(--reactor-edge); border-radius: 50%; background: var(--reactor-glass); backdrop-filter: blur(14px); color: var(--reactor-ink); display: flex; flex-direction: column; align-items: center; justify-content: center; box-shadow: var(--reactor-shadow); }
.reactor-glass-lens span { font-size: 8px; font-weight: 800; }
.reactor-glass-lens small { font-size: 7px; margin-top: 3px; }
.reactor-glass-lens strong { font-size: 26px; line-height: 1.1; color: var(--reactor-gold); }
.reactor-video-control { position: absolute; left: 12px; bottom: 12px; z-index: 2; color: var(--reactor-ink); border-color: var(--reactor-edge); background: var(--reactor-glass); backdrop-filter: blur(10px); }
.reactor-landing .hero-section { background: var(--background); }
.reactor-landing .hero-section > div { max-width: 800px; padding-top: 28px; padding-bottom: 32px; }
.reactor-landing .hero-section h1 { font-size: 60px; letter-spacing: 0; }
.reactor-landing .reactor-glass-stage { max-width: 560px; }
.reactor-landing .hero-section .grid > div { border-radius: 8px; background: color-mix(in oklch,var(--foreground) 4%,var(--background)); backdrop-filter: blur(10px); }
@media(min-width:768px) { .reactor-landing .hero-section h1 { font-size: 88px; } }

/*
 * Design system definition.
 *
 * The @theme inline block maps CSS custom properties to Tailwind utility
 * classes (e.g. --color-primary -> bg-primary, text-primary).
 *
 * The :root and .dark blocks define the actual color values using oklch.
 * All colors MUST use oklch format.
 *
 * To add a new semantic color:
 * 1. Add the variable to :root (light value) and .dark (dark value)
 * 2. Register it in @theme inline as --color-<name>: var(--<name>)
 */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

:root {
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.129 0.042 264.695);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.129 0.042 264.695);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.129 0.042 264.695);
  --primary: oklch(0.208 0.042 265.755);
  --primary-foreground: oklch(0.984 0.003 247.858);
  --secondary: oklch(0.968 0.007 247.896);
  --secondary-foreground: oklch(0.208 0.042 265.755);
  --muted: oklch(0.968 0.007 247.896);
  --muted-foreground: oklch(0.554 0.046 257.417);
  --accent: oklch(0.968 0.007 247.896);
  --accent-foreground: oklch(0.208 0.042 265.755);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.984 0.003 247.858);
  --border: oklch(0.929 0.013 255.508);
  --input: oklch(0.929 0.013 255.508);
  --ring: oklch(0.704 0.04 256.788);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.984 0.003 247.858);
  --sidebar-foreground: oklch(0.129 0.042 264.695);
  --sidebar-primary: oklch(0.208 0.042 265.755);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.968 0.007 247.896);
  --sidebar-accent-foreground: oklch(0.208 0.042 265.755);
  --sidebar-border: oklch(0.929 0.013 255.508);
  --sidebar-ring: oklch(0.704 0.04 256.788);
}

.dark {
  --background: oklch(0.129 0.042 264.695);
  --foreground: oklch(0.984 0.003 247.858);
  --card: oklch(0.208 0.042 265.755);
  --card-foreground: oklch(0.984 0.003 247.858);
  --popover: oklch(0.208 0.042 265.755);
  --popover-foreground: oklch(0.984 0.003 247.858);
  --primary: oklch(0.929 0.013 255.508);
  --primary-foreground: oklch(0.208 0.042 265.755);
  --secondary: oklch(0.279 0.041 260.031);
  --secondary-foreground: oklch(0.984 0.003 247.858);
  --muted: oklch(0.279 0.041 260.031);
  --muted-foreground: oklch(0.704 0.04 256.788);
  --accent: oklch(0.279 0.041 260.031);
  --accent-foreground: oklch(0.984 0.003 247.858);
  --destructive: oklch(0.704 0.191 22.216);
