  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.551 0.027 264.364);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
  }
}

/* BIXLINK visual system — Imperial Obsidian & Champagne Gold */
:root {
  --radius: 1.25rem;
  --background: oklch(0.145 0.018 275);
  --foreground: oklch(0.96 0.012 95);
  --card: oklch(0.205 0.022 278);
  --card-foreground: oklch(0.96 0.012 95);
  --popover: oklch(0.205 0.022 278);
  --popover-foreground: oklch(0.96 0.012 95);
  --primary: oklch(0.84 0.105 92);
  --primary-foreground: oklch(0.16 0.03 280);
  --secondary: oklch(0.24 0.02 278);
  --secondary-foreground: oklch(0.96 0.012 95);
  --muted: oklch(0.24 0.02 278);
  --muted-foreground: oklch(0.72 0.02 90);
  --accent: oklch(0.28 0.035 90);
  --accent-foreground: oklch(0.94 0.06 95);
  --border: oklch(0.45 0.045 90 / 42%);
  --input: oklch(0.45 0.045 90 / 42%);
  --ring: oklch(0.84 0.105 92);
  --chart-1: oklch(0.84 0.105 92);
  --chart-2: oklch(0.78 0.12 160);
  --chart-3: oklch(0.87 0.13 95);
  --destructive: oklch(0.65 0.23 25);
  --destructive-foreground: oklch(0.97 0.01 280);
}
@theme inline { --font-display: 'Sora', sans-serif; --font-sans: 'Manrope', sans-serif; }
html { scroll-behavior: smooth; }
body { font-family: var(--font-sans); }
.site-shell { background-image: radial-gradient(ellipse at 52% 8%, oklch(0.4 0.08 92 / 18%), transparent 37%); }
.site-header { position: sticky; top: 0; z-index: 40; border-bottom: 1px solid var(--border); background: oklch(0.145 0.018 275 / 90%); backdrop-filter: blur(18px); }
.brand-mark, .brand-hero { color: var(--chart-3); text-shadow: 0 0 32px oklch(0.88 0.19 95 / 35%); }
.header-brand { display: flex; min-width: 122px; align-items: center; gap: 8px; }
.header-brand img { width: 40px; height: 40px; }
.brand-mark { display: inline-flex; color: var(--chart-3); font-family: var(--font-display); font-size: 1.15rem; font-style: normal; font-weight: 900; line-height: 1; letter-spacing: 0; text-shadow: 0 0 16px color-mix(in oklab, var(--chart-3) 32%, transparent); }
.brand-mark i { font-style: normal; }
.brand-mark i { color: inherit; }
.brand-hero { line-height: 0.98; }
.nav-link { display: inline-flex; align-items: center; gap: 6px; padding: 10px 9px; color: var(--muted-foreground); font-size: 12px; font-weight: 700; border-radius: 999px; }
