.owner-vault__balance strong { display: block; margin-block: 6px; color: var(--chart-3); font-size: clamp(1.7rem, 5vw, 2.5rem); overflow-wrap: anywhere; }
@media (max-width: 700px) { .booster-member-status { grid-template-columns: repeat(2, minmax(0, 1fr)); } .booster-steps { grid-template-columns: 1fr; } }

/* Selected Cyber pulse v4: isolated gold tokens preserve the member theme. */
.app-splash { --splash-background: #020203; --splash-gold: #EAB308; --splash-highlight: #FFFDF2; --splash-deep-gold: #856404; --splash-mid-gold: #A17900; --splash-track-highlight: #FEF08A; --splash-foreground: #FAFAFA; position: fixed; inset: 0; z-index: 100; overflow: hidden; display: grid; place-items: center; background: var(--splash-background); color: var(--splash-foreground); opacity: 1; transition: opacity 180ms var(--ease); }
