.app-splash__topline { flex-shrink: 0; padding: 8px 20px; border: 1px solid color-mix(in srgb, var(--splash-gold) 20%, transparent); border-radius: 999px; background: color-mix(in srgb, var(--splash-gold) 5%, transparent); color: var(--splash-gold); font-family: var(--font-display); font-size: 9px; font-weight: 800; text-transform: uppercase; letter-spacing: 0; }
