.app-splash__coin { position: relative; width: min(256px, 70%, 36dvh); height: auto; aspect-ratio: 1; border-radius: 50%; object-fit: cover; border: 2px solid color-mix(in srgb, var(--splash-gold) 20%, transparent); box-shadow: 0 0 50px color-mix(in srgb, var(--splash-gold) 15%, transparent); }
.app-splash__content { position: relative; flex-shrink: 0; width: 100%; text-align: center; }
