.app-splash__track i { display: block; width: 100%; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--splash-mid-gold), var(--splash-gold), var(--splash-track-highlight)); transform-origin: left; animation: splash-progress 720ms ease-out both; }
.app-splash__skip { margin-top: 28px; min-height: 44px; color: color-mix(in srgb, var(--splash-foreground) 55%, var(--splash-background)); font-size: 9px; font-weight: 700; letter-spacing: 0; text-transform: uppercase; }
.app-splash__skip:hover, .app-splash__skip:focus-visible { color: var(--splash-gold); background: transparent; }
