@media (min-width: 768px) { .trust-panel { grid-template-columns: repeat(3, 1fr); } }

/* Paket hemat 3: premium market + booster polish */
.market-panel { position: relative; overflow: hidden; background: linear-gradient(160deg, oklch(0.3 0.05 92 / 35%), var(--card) 45%); box-shadow: 0 20px 50px -30px oklch(0.84 0.105 92 / 60%); transition: transform .3s ease, box-shadow .3s ease; }
.market-panel::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 2px; background: linear-gradient(90deg, var(--primary), var(--chart-3), var(--chart-2)); }
.market-panel:hover { transform: translateY(-4px); box-shadow: 0 24px 60px -28px oklch(0.85 0.17 90 / 45%); }
.market-panel .grid.border-b { border-radius: 12px; padding-left: 8px; padding-right: 8px; transition: background .2s ease; }
.market-panel .grid.border-b:hover { background: oklch(0.84 0.105 92 / 10%); }
.apy-meter { height: 6px; border-radius: 999px; background: var(--border); overflow: hidden; }
.apy-meter > i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--primary), var(--chart-3), var(--chart-2)); box-shadow: 0 0 12px var(--chart-2); }
.robot-stage::after { content: ""; position: absolute; bottom: 30px; width: 60%; height: 24px; border-radius: 50%; background: radial-gradient(ellipse, oklch(0.85 0.17 90 / 45%), transparent 70%); filter: blur(6px); animation: core-pulse 2.8s ease-in-out infinite; }

/* Paket 4: unified design system — radius, border, shadow, type, numerals */
:root { --r-control: 14px; --r-card: 20px; --line: oklch(0.42 0.08 290 / 45%);
  --sh-1: 0 2px 10px oklch(0.05 0.02 280 / 35%); --sh-2: 0 10px 30px oklch(0.05 0.02 280 / 45%); --sh-3: 0 22px 70px oklch(0.05 0.02 280 / 60%);
  --ease: cubic-bezier(.2,.8,.2,1); }
@layer base { body { font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1, "zero" 1; } }
.form-input { border-radius: var(--r-control); }
.form-input { border-color: var(--line); transition: border-color 150ms var(--ease), box-shadow 150ms var(--ease); }
.form-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px oklch(0.84 0.105 92 / 22%); }
.trust-strip div, .trust-panel > div, .market-panel .grid.border-b { border-radius: var(--r-control); }
.package-card, .metric-panel, .stat-card, .roadmap-item, .market-panel, .modal-panel { border-radius: var(--r-card); border-color: var(--line); box-shadow: var(--sh-1); transition: transform 250ms var(--ease), box-shadow 250ms var(--ease), border-color 250ms var(--ease); }
.modal-panel { box-shadow: var(--sh-3); }
.package-card:hover, .metric-panel:hover, .stat-card:hover { box-shadow: var(--sh-2), 0 0 26px oklch(0.84 0.105 92 / 22%); }
@layer base {
h1, h2, h3 { font-family: "Space Grotesk", sans-serif; letter-spacing: -0.015em; line-height: 1.1; text-wrap: balance; }
h1 { font-size: clamp(2rem, 5vw, 4rem); } h2 { font-size: clamp(1.5rem, 3.2vw, 2.5rem); } h3 { font-size: clamp(1.1rem, 1.8vw, 1.5rem); }
body { font-size: 15px; line-height: 1.6; }
.eyebrow, label { letter-spacing: .12em; }
label { font-size: 11px; text-transform: uppercase; font-weight: 700; }
}

/* Paket 6: slashed-zero numerals and premium stake hierarchy */
.numeric, [data-numeric], input[type="number"], table { font-family: "JetBrains Mono", monospace; font-variant-numeric: tabular-nums slashed-zero; font-feature-settings: "tnum" 1, "zero" 1; letter-spacing: 0; }
.package-card { position: relative; overflow: hidden; }
.package-card::before { content: ""; position: absolute; inset: 0 0 auto; height: 2px; background: linear-gradient(90deg, var(--primary), var(--chart-3), var(--chart-2)); opacity: .55; }
.package-card-featured { border-color: var(--chart-3); box-shadow: var(--sh-2), 0 0 26px oklch(0.88 0.19 95 / 16%); }
.package-label { display: inline-flex; align-items: center; gap: 5px; border: 1px solid var(--line); border-radius: 999px; padding: 4px 8px; background: var(--secondary); font-size: 9px; line-height: 1; font-weight: 800; color: var(--muted-foreground); text-transform: uppercase; letter-spacing: .08em; }
.package-label-gold { border-color: oklch(0.88 0.19 95 / 45%); color: var(--chart-3); }
.stake-request { border: 1px solid var(--line); border-radius: var(--r-control); background: linear-gradient(150deg, oklch(0.24 0.08 290 / 70%), var(--card)); box-shadow: var(--sh-1); }
.stake-progress { height: 5px; overflow: hidden; border-radius: 999px; background: var(--border); }
.stake-progress > i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, var(--primary), var(--chart-3), var(--chart-2)); }

/* NETWORK premium readability + compact header language control */
.language-control { position: relative; }
.language-trigger { width: 50px; height: 36px; gap: 5px; border: 1px solid var(--line); border-radius: 999px; background: var(--secondary); padding: 0 7px; }
