.language-menu { position: absolute; top: calc(100% + 10px); right: 0; z-index: 50; display: grid; width: 118px; grid-template-columns: repeat(2, 1fr); gap: 4px; border: 1px solid var(--border); border-radius: 12px; padding: 7px; background: var(--popover); box-shadow: 0 12px 32px color-mix(in oklab, var(--background) 60%, transparent); }
.language-menu button { height: 38px; border-radius: 8px; padding: 0; }
.language-menu button.is-active { background: color-mix(in oklab, var(--primary) 20%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 45%, transparent); }
.flag-symbol { position: relative; display: inline-block; width: 24px; height: 16px; flex: 0 0 auto; overflow: hidden; border: 1px solid color-mix(in oklab, var(--foreground) 22%, transparent); border-radius: 2px; background: var(--foreground); box-shadow: 0 2px 5px color-mix(in oklab, var(--background) 55%, transparent); }
.flag-gb { background: linear-gradient(27deg, transparent 43%, var(--destructive) 43% 48%, var(--foreground) 48% 52%, var(--destructive) 52% 57%, transparent 57%), linear-gradient(153deg, transparent 43%, var(--destructive) 43% 48%, var(--foreground) 48% 52%, var(--destructive) 52% 57%, transparent 57%), linear-gradient(90deg, transparent 38%, var(--foreground) 38% 44%, var(--destructive) 44% 56%, var(--foreground) 56% 62%, transparent 62%), linear-gradient(transparent 31%, var(--foreground) 31% 40%, var(--destructive) 40% 60%, var(--foreground) 60% 69%, transparent 69%), oklch(0.34 0.16 264); }
.flag-id { background: linear-gradient(var(--destructive) 0 50%, var(--foreground) 50%); }
.flag-my { background: repeating-linear-gradient(var(--destructive) 0 2px, var(--foreground) 2px 4px); }
.flag-my::before { content: ""; position: absolute; inset: 0 auto auto 0; width: 12px; height: 9px; background: oklch(0.34 0.16 264); }
