  --register-background: var(--background); --register-surface: var(--card); --register-foreground: var(--foreground); --register-muted: var(--muted-foreground); --register-border: var(--border); --register-gold: var(--chart-3); --register-gold-light: var(--chart-3); --register-gold-deep: var(--primary); --register-submit-shadow: var(--sh-1); font-family: 'Manrope', sans-serif;
