.theme-option { height: auto; min-width: 0; display: flex; flex-direction: column; align-items: stretch; gap: 15px; padding: 14px; border-radius: 8px; white-space: normal; }
.theme-option[aria-pressed="true"] { border-color: var(--ring); box-shadow: inset 0 0 0 1px var(--ring); }
.theme-miniature { display: block; width: 100%; aspect-ratio: 1.7; overflow: hidden; border: 1px solid var(--border); border-radius: 6px; padding: 12px; background: var(--background); color: var(--foreground); }
.theme-miniature[data-presentation-theme="original"] { --background: oklch(0.13 0.05 285); --card: oklch(0.21 0.07 282); --foreground: oklch(0.97 0.01 280); --primary: oklch(0.84 0.105 92); --chart-2: oklch(0.78 0.12 160); --chart-3: oklch(0.88 0.19 95); --border: oklch(0.39 0.08 285 / 55%); }
