:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) main .grid>section { min-width: 0; }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) :is(.stake-lux-btn,.stake-lux-card--pop .stake-lux-btn) { background: var(--primary); color: var(--primary-foreground); box-shadow: var(--sh-1); }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) .stake-pool { background: linear-gradient(90deg, color-mix(in oklab, var(--chart-3) 12%, transparent), transparent 72%); }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) .stake-pool-ico { background: color-mix(in oklab, var(--chart-3) 12%, transparent); }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) :is(.stake-lux-title span,.brand-mark) { text-shadow: none; }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) :is(.stake-lux-notch,.stake-lux-notch--gold) { color: var(--background); box-shadow: none; }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) :is(.profile-code,.profile-personal-link,.ref-tree-metrics b) { background: var(--background); border-color: var(--border); }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) .profile-referral::after { display: none; }
:is([data-presentation-theme="emerald"], [data-presentation-theme="graphite"], [data-presentation-theme="royal"], [data-presentation-theme="matcha"]) .profile-action-icon { background: color-mix(in oklab, var(--primary) 12%, transparent); }

/* NETWORK — selected premium glass explorer, using the shared theme roles. */
.network-explorer { --nx-surface: color-mix(in oklab, var(--card) 80%, var(--background)); --nx-glass: color-mix(in oklab, var(--foreground) 3%, transparent); --nx-gold-line: color-mix(in oklab, var(--chart-3) 40%, transparent); --nx-shadow: 0 14px 35px color-mix(in oklab, var(--background) 70%, transparent); letter-spacing: 0; }
.nx-header { display:flex;align-items:center;justify-content:space-between;gap:24px;padding-bottom:24px;border-bottom:1px solid var(--border); }
.nx-search { display:flex;align-items:center;gap:12px;border:1px solid var(--border);border-radius:8px;padding:10px 14px;background:var(--nx-glass);color:var(--chart-3);width:320px;max-width:100%; }
.nx-search input { width:100%;min-width:0;background:transparent;outline:0;color:var(--foreground);font-size:13px; }
.nx-root { display:flex;flex-direction:column;align-items:center;padding:32px 0; }
.nx-root-avatar { width:80px;height:80px;border:2px solid var(--nx-gold-line);border-radius:20px;display:grid;place-items:center;color:var(--chart-3);background:var(--nx-surface);position:relative;box-shadow:var(--nx-shadow); }
.nx-root-avatar span { position:absolute;bottom:-9px;right:-9px;padding:4px 8px;background:var(--chart-3);color:var(--background);font-size:10px;font-weight:800;border-radius:6px; }
.nx-root h2 { margin-top:24px;font-size:28px;font-weight:800;font-family:var(--font-display);overflow-wrap:anywhere;text-align:center; }
.nx-root-status { display:flex;align-items:center;flex-wrap:wrap;justify-content:center;gap:8px;font-size:12px;color:var(--muted-foreground);margin-top:8px; }
.nx-totals { width:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:28px 0;gap:20px; }
.nx-totals>div { text-align:center;min-width:0; }
.nx-totals dt { font-size:11px;color:var(--muted-foreground); }
.nx-totals dd { font-size:20px;font-weight:700;margin-top:6px;overflow-wrap:anywhere; }
.nx-milestone-heading,.nx-matrix-heading { display:flex;justify-content:space-between;align-items:center;gap:12px;width:100%;font-size:12px;color:var(--muted-foreground); }
.nx-milestone-heading h3,.nx-matrix-heading h2 { font-weight:700;color:var(--foreground); }
.nx-levels { display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;width:100%;margin-top:14px; }
.nx-level { position:relative;text-align:center;display:flex;flex-direction:column;gap:6px;padding:16px 6px;border-radius:8px;background:var(--nx-glass);border:1px solid var(--border);color:var(--muted-foreground); }
.nx-level span { font-size:10px;font-weight:700; }.nx-level strong { font-size:20px; }.nx-level small { font-size:11px; }.nx-level svg { position:absolute;right:7px;top:7px; }.nx-level-active { border-color:var(--nx-gold-line);background:color-mix(in oklab,var(--chart-3) 6%,transparent);color:var(--chart-3); }
.nx-matrix { border-top:1px solid var(--border);padding-top:24px; }.nx-matrix-heading h2 { font-size:16px; }.nx-breadcrumb { display:flex;align-items:center;flex-wrap:wrap;gap:2px;margin:14px 0; }.nx-breadcrumb>span { display:flex;align-items:center;min-width:0; }.nx-breadcrumb button { font-size:11px;max-width:170px;overflow:hidden;text-overflow:ellipsis; }
.nx-focus { display:flex;align-items:center;gap:12px;padding:16px;border-left:2px solid var(--chart-3);background:var(--nx-glass);margin-bottom:20px; }.nx-focus p { font-size:11px;color:var(--muted-foreground); }.nx-focus>div { min-width:0;overflow-wrap:anywhere; }
.nx-grid { display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px; }.nx-member { min-width:0;border-radius:8px;border:1px solid var(--border);border-top:3px solid var(--border);background:var(--nx-surface);padding:16px;box-shadow:var(--nx-shadow);transition:border-color .2s; }.nx-member-active { border-top-color:var(--chart-2); }.nx-member:hover { border-color:var(--nx-gold-line); }
.nx-member-top { display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:14px; }.nx-package-avatar { display:grid;place-items:center;width:32px;height:32px;flex-shrink:0;border-radius:8px;background:var(--nx-glass);color:var(--chart-3);font-size:12px;font-weight:800; }.nx-package { font-size:9px;font-weight:700;color:var(--muted-foreground); }.nx-member-code { font-size:10px;color:var(--muted-foreground);overflow-wrap:anywhere; }.nx-member h3 { margin:4px 0 14px;font-size:14px;font-weight:800;overflow-wrap:anywhere; }.nx-member dl { display:grid;grid-template-columns:1fr 1fr;gap:14px 8px; }.nx-member dt { font-size:10px;color:var(--muted-foreground); }.nx-member dd { font-size:12px;font-weight:700;margin-top:3px;overflow-wrap:anywhere; }.nx-member-bonus { margin-top:16px;padding-top:10px;border-top:1px solid var(--border);display:flex;flex-direction:column;gap:4px; }.nx-member-bonus span,.nx-member-bonus small { font-size:10px;color:var(--muted-foreground); }.nx-member-bonus b { font-size:13px;color:var(--chart-3); }.nx-branch-button { display:flex;justify-content:space-between;width:100%;height:36px;padding:0;margin-top:12px;border-top:1px solid var(--border);border-radius:0;font-size:11px;color:var(--muted-foreground); }
.nx-controls { display:flex;justify-content:space-between;align-items:center;gap:16px;padding:20px 0;border-bottom:1px solid var(--border); }.nx-controls select { width:140px;font-size:12px; }.nx-plan { display:grid;grid-template-columns:1fr 1fr;gap:40px;padding:28px 0;border-bottom:1px solid var(--border); }
@media(max-width:1000px) { .nx-grid { grid-template-columns:repeat(3,minmax(0,1fr)); } }
@media(max-width:700px) { .nx-header { align-items:stretch;flex-direction:column;gap:16px; }.nx-search { width:100%; }.nx-root h2 { font-size:24px; }.nx-totals { grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 12px; }.nx-totals dd { font-size:18px; }.nx-levels { gap:6px; }.nx-level { padding:24px 4px 12px; }.nx-level strong { font-size:17px; }.nx-level small { font-size:9px; }.nx-grid { grid-template-columns:repeat(2,minmax(0,1fr));gap:10px; }.nx-member { padding:12px; }.nx-member dl { grid-template-columns:1fr;gap:10px; }.nx-member h3 { font-size:13px; }.nx-package { font-size:8px; }.nx-plan { grid-template-columns:1fr;gap:24px; }.nx-controls { flex-wrap:wrap; }.nx-focus { flex-wrap:wrap; }.nx-matrix-heading h2 { font-size:14px; } }
@media(prefers-reduced-motion:reduce) { .nx-member { transition:none; } }

/* Royal Gold & Jade: reference-inspired light surfaces, no new animation. */
[data-presentation-theme="royal"] {
  --background: oklch(0.978 0.003 160);
  --foreground: oklch(0.25 0.014 160);
  --card: oklch(1 0 0);
  --primary: oklch(0.49 0.103 166);
  --primary-foreground: oklch(1 0 0);
  --chart-2: oklch(0.49 0.103 166);
  --chart-3: oklch(0.49 0.095 85);
  --chart-1: oklch(0.52 0.18 301);
  --chart-4: var(--chart-1);
  --chart-5: var(--chart-3);
  --secondary: oklch(0.95 0.013 160);
  --muted: var(--secondary);
  --muted-foreground: oklch(0.47 0.018 160);
  --border: oklch(0.87 0.016 160);
  --input: var(--border);
  --destructive: oklch(0.52 0.18 25);
  --destructive-foreground: oklch(1 0 0);
  --royal-jade: oklch(0.53 0.106 166);
  --royal-gold: oklch(0.65 0.12 85);
  --royal-violet: oklch(0.52 0.18 301);
  --royal-on-color: oklch(1 0 0);
  --royal-shadow: oklch(0.25 0.014 160 / 8%);
  --sh-1: 0 3px 12px var(--royal-shadow);
  --sh-2: 0 8px 24px var(--royal-shadow);
  --sh-3: 0 16px 40px var(--royal-shadow);
  --theme-glass: var(--card);
  --theme-inset: inset 0 1px 0 var(--card);
}
[data-presentation-theme="royal"] :is(.terminal-balance,.wallet-summary) { background: var(--royal-jade); color: var(--royal-on-color); }
[data-presentation-theme="royal"] :is(.terminal-balance,.wallet-summary) :is(h1,h2,h3,b,strong,.text-foreground,.text-muted-foreground,.wallet-balance) { color: var(--royal-on-color); }
[data-presentation-theme="royal"] .wallet-summary button { background: var(--card); color: var(--foreground); border-color: var(--card); }
[data-presentation-theme="royal"] .wallet-summary button:last-child { background: var(--royal-violet); color: var(--royal-on-color); border-color: var(--royal-violet); }
[data-presentation-theme="royal"] .wallet-summary button:hover { opacity: 0.9; }
[data-presentation-theme="royal"] .terminal-balance :is(button,a) { color: var(--foreground); background: var(--card); border-color: var(--border); }
[data-presentation-theme="royal"] .terminal-balance :is(button,a):hover { background: var(--secondary); }
[data-presentation-theme="royal"] :is(.boost-split-bar,.vip-progress-track) { background: var(--secondary); }
[data-presentation-theme="royal"] :is(.stake-lux-notch,.stake-lux-notch--gold) { color: var(--royal-on-color); }
[data-presentation-theme="royal"] .profile-avatar { background: var(--card); }
[data-presentation-theme="royal"] .network-explorer { --nx-shadow: var(--sh-2); }
[data-presentation-theme="royal"] :is(.metric-panel,.stat-card,.roadmap-item,.market-panel,.package-card,.terminal-kpi,.boost-tier,.stake-lux-card,.nx-member,.ecosystem-column) { border-top-color: var(--chart-1); }
[data-presentation-theme="royal"] :is(.metric-panel,.stat-card,.roadmap-item,.market-panel,.package-card,.terminal-kpi,.boost-tier,.stake-lux-card,.nx-member,.ecosystem-column):nth-child(3n+2) { border-top-color: var(--royal-jade); }
[data-presentation-theme="royal"] :is(.metric-panel,.stat-card,.roadmap-item,.market-panel,.package-card,.terminal-kpi,.boost-tier,.stake-lux-card,.nx-member,.ecosystem-column):nth-child(3n) { border-top-color: var(--royal-gold); }
[data-presentation-theme="royal"] .theme-miniature-panels>span:first-child { background:color-mix(in oklab,var(--royal-jade) 16%,var(--card)); }
[data-presentation-theme="royal"] .theme-miniature-panels>span:last-child { background:color-mix(in oklab,var(--royal-violet) 11%,var(--card)); }
.wallet-fx-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;overflow:hidden;border:1px solid color-mix(in oklab,var(--foreground) 18%,transparent);border-radius:8px;background:color-mix(in oklab,var(--foreground) 18%,transparent); }
.wallet-fx-grid>div { min-width:0;padding:8px 10px;background:color-mix(in oklab,var(--background) 16%,transparent); }.wallet-fx-grid span { display:block;font-size:9px;color:color-mix(in oklab,var(--foreground) 72%,transparent); }.wallet-fx-grid b { display:block;margin-top:2px;font-size:11px;overflow-wrap:anywhere;color:var(--foreground); }
@media(min-width:640px){.wallet-fx-grid{grid-template-columns:repeat(4,minmax(0,1fr));}}
.header-reviewer { flex-shrink: 0; gap: 6px; }
@media (max-width: 480px) { .header-reviewer { width: 34px; height: 34px; padding: 0; } .header-reviewer span { display: none; } }
.tx-result { width:min(92vw,380px);border-radius:24px;padding:28px 22px;text-align:center;background:var(--card);border:1px solid var(--border); }
.tx-result.is-ok { border-color:var(--chart-2);box-shadow:0 0 50px color-mix(in oklab,var(--chart-2) 28%,transparent); }
.tx-result.is-fail { border-color:var(--destructive);box-shadow:0 0 50px color-mix(in oklab,var(--destructive) 28%,transparent); }
.tx-result-ring { margin:0 auto;display:grid;place-items:center;width:92px;height:92px;border-radius:999px; }
.tx-result.is-ok .tx-result-ring,.tx-result.is-ok .eyebrow { color:var(--chart-2); }
.tx-result.is-ok .tx-result-ring { background:color-mix(in oklab,var(--chart-2) 14%,transparent);border:2px solid var(--chart-2); }
.tx-result.is-fail .tx-result-ring,.tx-result.is-fail .eyebrow { color:var(--destructive); }
.tx-result.is-fail .tx-result-ring { background:color-mix(in oklab,var(--destructive) 14%,transparent);border:2px solid var(--destructive); }
.tx-result.is-ok .tx-result-btn { background:var(--chart-2);color:var(--background); }
.tx-result.is-fail .tx-result-btn { background:var(--destructive);color:var(--destructive-foreground); }
/* Day / night mode (member toggle) */
html[data-color-mode="light"], html[data-color-mode="light"] [data-presentation-theme] {
  --background: oklch(0.975 0.008 280); --foreground: oklch(0.2 0.04 280);
  --card: oklch(1 0 0); --card-foreground: oklch(0.2 0.04 280);
  --popover: oklch(1 0 0); --popover-foreground: oklch(0.2 0.04 280);
  --secondary: oklch(0.94 0.015 280); --secondary-foreground: oklch(0.2 0.04 280);
  --muted: oklch(0.94 0.015 280); --muted-foreground: oklch(0.45 0.03 280);
  --accent: oklch(0.93 0.03 300); --accent-foreground: oklch(0.2 0.04 280);
  --border: oklch(0.86 0.02 280); --input: oklch(0.86 0.02 280);
  --primary: oklch(0.52 0.22 305); --primary-foreground: oklch(0.99 0 0);
  --chart-1: oklch(0.52 0.22 305); --chart-2: oklch(0.55 0.17 150); --chart-3: oklch(0.62 0.14 75);
  --theme-glass: oklch(1 0 0);
  color-scheme: light;
}
html[data-color-mode="light"] .site-shell { background-image: none; }
html[data-color-mode="light"] .site-header { background: color-mix(in oklab, var(--background) 92%, transparent); }
.mode-toggle { border-radius: 999px; color: var(--chart-3); }

/* Duration packages: Presisi Ringkas v5, scoped to package surfaces. */
:root {
  --package-surface: #161E31;
  --package-ink: oklch(0.98 0 0);
  --package-muted: oklch(0.74 0.025 260);
  --package-control: oklch(0.27 0.035 260);
  --package-border: oklch(0.4 0.035 260);
  --package-emerald: oklch(0.57 0.15 160);
  --package-cyan: oklch(0.57 0.12 220);
  --package-blue: oklch(0.5 0.19 260);
  --package-indigo: oklch(0.49 0.2 285);
  --package-violet: oklch(0.5 0.21 305);
  --package-fuchsia: oklch(0.52 0.2 330);
  --package-rose: oklch(0.53 0.2 15);
  --package-gold: oklch(0.8 0.15 80);
  --package-gold-ink: oklch(0.2 0.025 80);
  --package-shadow: 0 8px 24px oklch(0.05 0.02 260 / 12%);
}
.duration-package { --tier-color: var(--package-emerald); --tier-ink: var(--package-ink); min-width:0; overflow:hidden; border:1px solid var(--package-border); border-radius:8px; background:var(--package-surface); color:var(--package-ink); box-shadow:var(--package-shadow); font-family:'DM Sans',sans-serif; letter-spacing:0; }
.tier-tone-1 { --tier-color:var(--package-cyan); }
.tier-tone-2 { --tier-color:var(--package-blue); }
.tier-tone-3 { --tier-color:var(--package-indigo); }
.tier-tone-4 { --tier-color:var(--package-violet); }
.tier-tone-5 { --tier-color:var(--package-fuchsia); }
.tier-tone-6 { --tier-color:var(--package-rose); }
.tier-tone-7 { --tier-color:var(--package-gold); --tier-ink:var(--package-gold-ink); }
.duration-package-head { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:20px; background:var(--tier-color); color:var(--tier-ink); }
.duration-package h3,.duration-price,.duration-apy { font-family:'Space Grotesk',sans-serif; letter-spacing:0; }
.duration-package h3 { overflow-wrap:anywhere; }
.duration-price { flex-shrink:0; max-width:52%; padding:7px 9px; border:1px solid color-mix(in oklab,var(--tier-ink) 20%,transparent); border-radius:8px; background:color-mix(in oklab,var(--tier-ink) 12%,transparent); font-size:13px; overflow-wrap:anywhere; }
.duration-package-body { padding:20px; }
.duration-label { color:var(--package-muted); font-size:10px; font-weight:700; text-transform:uppercase; }
.duration-options { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:5px; margin-top:10px; }
.duration-package .duration-option { width:100%; min-width:0; height:38px; padding:0; border-radius:6px; background:var(--package-control); border-color:var(--package-border); color:var(--package-muted); font-size:11px; font-weight:700; }
.duration-package .duration-option[aria-pressed="true"] { background:var(--tier-color); border-color:var(--tier-color); color:var(--tier-ink); }
.duration-package .duration-option:hover { border-color:var(--tier-color); }
.duration-package-action { display:grid; grid-template-columns:minmax(0,1fr); gap:8px; margin-top:16px; }
.duration-yield { display:grid; grid-template-columns:minmax(0,1.2fr) minmax(0,1fr); gap:12px; margin-top:14px; padding-block:12px; border-block:1px solid var(--package-border); }
.duration-yield > div { min-width:0; }
.duration-yield dt { color:var(--package-muted); font-size:10px; }
.duration-yield dd { margin-top:5px; font-size:13px; font-weight:700; overflow-wrap:anywhere; }
.duration-yield > div:last-child dd { color:color-mix(in oklab,var(--chart-3) 65%,var(--package-ink)); }
.duration-risk { text-align:center; color:var(--package-muted); font-size:10px; line-height:1.6; }
.duration-package :is(.pass-mini,.nft-mini) { height:auto; white-space:normal; border-radius:8px; box-shadow:none; }
.duration-package .pass-mini { padding:8px 0; border:0; background:transparent; }
.duration-apy { display:block; margin-top:3px; font-size:26px; font-weight:700; color:color-mix(in oklab,var(--tier-color) 64%,var(--package-ink)); }
.duration-apy small { font-size:10px; }
.duration-package .duration-stake { width:100%; min-width:0; flex-shrink:0; height:46px; border-radius:8px; background:var(--tier-color); color:var(--tier-ink); padding-inline:18px; font-size:13px; }
.duration-package .duration-stake:hover { filter:brightness(1.08); }
.duration-package .form-input { background:var(--package-control); color:var(--package-ink); border-color:var(--package-border); border-radius:6px; font-family:'DM Sans',sans-serif; }
html[data-color-mode="light"] .duration-package { --package-surface:var(--card); --package-ink:var(--foreground); --package-muted:var(--muted-foreground); --package-control:var(--secondary); --package-border:var(--border); --tier-ink:oklch(0.99 0 0); }
html[data-color-mode="light"] .duration-apy { color:var(--tier-color); }
html[data-color-mode="light"] .tier-tone-7 { --tier-ink:var(--package-gold-ink); }

/* Compact profit overview: preserve complete ledger precision. */
.profit-summary .profit-metric { position: relative; padding: 12px; border-radius: 8px; }
.profit-summary .profit-metric > svg { position: absolute; top: 12px; right: 12px; width: 15px; height: 15px; }
.profit-summary .profit-metric > span { margin-top: 0; padding-right: 20px; font-size: 10px; }
.profit-summary .profit-metric > strong { margin-top: 7px; font-size: 14px; line-height: 1.5; }
.profit-summary .profit-metric > small { margin-top: 4px; font-size: 9px; }
.profit-summary .profit-metric--total { grid-column: span 2; }
.profit-summary .profit-metric--total > strong { font-size: 26px; }
.profit-summary .profit-metric--daily { grid-column: span 2; display: flex; align-items: center; flex-wrap: wrap; gap: 6px 12px; }
.profit-summary .profit-metric--daily > svg { position: static; flex-shrink: 0; }
.profit-summary .profit-metric--daily > :is(span,strong,small) { margin: 0; padding: 0; }
.profit-page .profit-position { padding: 12px; border-radius: 8px; min-width: 0; }
.profit-page .profit-position .numeric { overflow-wrap: anywhere; }
.profit-page .profit-position > div:last-child { gap: 8px; margin-top: 10px; padding-top: 10px; font-size: 10px; }
.profit-page .section-title { font-size: 28px; letter-spacing: 0; }
@media(min-width:1024px) {
  .profit-summary .profit-metric--total, .profit-summary .profit-metric--daily { grid-column: auto; }
  .profit-summary .profit-metric--daily { display: block; }
  .profit-summary .profit-metric--daily > svg { position: absolute; }
