  --secondary: oklch(0.26 0.016 164);
  --secondary-foreground: var(--foreground);
  --muted: var(--secondary);
  --muted-foreground: oklch(0.707 0.022 261);
  --accent: var(--secondary);
  --accent-foreground: var(--foreground);
  --border: oklch(1 0 0 / 14%);
  --input: oklch(1 0 0 / 20%);
  --ring: var(--primary);
  --chart-1: oklch(0.707 0.165 255);
  --chart-2: var(--primary);
  --chart-3: oklch(0.795 0.184 86);
  --chart-4: oklch(0.702 0.183 294);
  --chart-5: oklch(0.718 0.202 350);
  --glass-clear: oklch(1 0 0 / 5%);
  --glass-edge: oklch(1 0 0 / 20%);
  --glass-sheen: oklch(1 0 0 / 13%);
  --glass-shadow: 0 8px 24px oklch(0.05 0 0 / 24%);
  --glass-inset: inset 0 1px 0 var(--glass-edge);
  --glass-surface: linear-gradient(135deg, var(--glass-sheen), var(--glass-clear) 45%, var(--glass-clear));
  --package-emerald: oklch(0.765 0.177 163);
  --package-cyan: oklch(0.789 0.154 211);
  --package-blue: oklch(0.707 0.165 255);
  --package-indigo: oklch(0.702 0.183 294);
