  --package-fuchsia: oklch(0.704 0.191 22);
  --package-rose: oklch(0.828 0.189 84);
  --package-gold: oklch(0.841 0.238 129);
  --package-ink: var(--foreground);
  --package-muted: var(--muted-foreground);
  --package-surface: var(--glass-clear);
  --package-control: var(--glass-clear);
  --package-border: var(--glass-edge);
  --package-shadow: var(--glass-shadow);
}
