.auth-vault { position: relative; border-radius: 24px; padding: 28px 22px; border: 1px solid hsl(var(--chart-3) / .25); background: linear-gradient(160deg, hsl(var(--card) / .7), hsl(var(--background) / .5)); backdrop-filter: blur(20px); box-shadow: inset 0 1px 0 hsl(var(--foreground) / .07), 0 24px 60px -30px hsl(var(--ruby) / .45); overflow: hidden; }
.auth-vault::before { content: ''; position: absolute; inset: 0 0 auto; height: 2px; background: linear-gradient(90deg, transparent, hsl(var(--ruby) / .8), hsl(var(--chart-3) / .8), transparent); }
