/* Vault flourish: stardust, aura logo, secure node, shimmer */
.auth-vault-page,.register-numbered{position:relative;isolation:isolate}
.vault-stardust{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:-1}
