/* Reactor NFT cards */
.nft-card { --nft:var(--muted-foreground); position:relative; margin:0; overflow:hidden; border-radius:8px; border:1px solid color-mix(in oklab,var(--nft) 55%,transparent); background:var(--card); box-shadow:0 0 22px color-mix(in oklab,var(--nft) 30%,transparent); }
.nft-rare { --nft:#3b82f6; } .nft-epic { --nft:#A855F7; } .nft-legendary { --nft:#FFD700; } .nft-mythic { --nft:#39FF14; }
