.nft-card-foot b { color:var(--nft); font-size:12px; } .nft-card-foot span { color:var(--muted-foreground); } .nft-card-foot strong { font-size:15px; }
.nft-compact .nft-card-foot strong { font-size:13px; }
.nft-pop { position:fixed; inset:0; z-index:80; display:grid; place-content:center; gap:10px; padding:24px; background:color-mix(in oklab,var(--background) 70%,transparent); backdrop-filter:blur(6px); }
