/* Adaptive auric marketplace; no independent page background. */
:root { --shop-gold:oklch(.82 .11 85); --shop-line:oklch(.82 .11 85 / 38%); --shop-photo:oklch(.9 .005 240); --shop-photo-ink:oklch(.27 .035 80); --shop-shadow:0 10px 30px oklch(.05 0 0 / 13%); }
