.shop-tabs button { border-radius:0; padding:12px 18px; height:auto; color:var(--muted-foreground); border-bottom:2px solid transparent; }
.shop-tabs button[aria-selected="true"] { border-color:var(--shop-gold); color:var(--shop-gold); background:transparent; }
.shop-toolbar { display:flex; flex-wrap:wrap; justify-content:space-between; gap:14px; padding:22px 0; }
.shop-search { display:flex; align-items:center; gap:10px; border-bottom:1px solid var(--border); padding:8px 0; min-width:220px; flex:1; max-width:340px; color:var(--muted-foreground); }.shop-search input { outline:none; background:transparent; color:var(--foreground); width:100%; font-size:13px; }
