.shop-section { padding:20px 0 36px; }
.shop-section-title { display:flex; justify-content:space-between; align-items:end; gap:12px; margin-bottom:22px; color:var(--shop-gold); }.shop-section-title h2 { font-size:23px; font-family:var(--font-display); margin-top:6px; }.shop-section-title>span { font-size:11px; color:var(--muted-foreground); }
