.shop-item { min-width:0; overflow:hidden; border:1px solid var(--shop-line); border-radius:6px; background:color-mix(in oklab,var(--card) 75%,transparent); box-shadow:var(--shop-shadow); transition:transform .2s; }.shop-item:hover { transform:translateY(-3px); }
.shop-image-stage { position:relative; overflow:hidden; background:var(--shop-photo); aspect-ratio:3/4; }
.shop-product-image { display:block; width:100%; aspect-ratio:3/4; object-fit:contain; background:var(--shop-photo); }
.shop-image-tag { position:absolute; left:10px; top:10px; padding:4px 7px; font-size:8px; font-weight:800; border:1px solid var(--shop-line); border-radius:3px; color:var(--shop-photo-ink); background:color-mix(in oklab,var(--shop-photo) 90%,transparent); }
.shop-item-meta { padding:15px; }.shop-item-meta>p { font-size:8px; color:var(--muted-foreground); }.shop-item-meta h3 { font-size:15px; line-height:1.4; margin:6px 0; font-family:var(--font-display); color:var(--shop-gold); overflow-wrap:anywhere; }
.lux-shop .shop-detail { display:flex; width:100%; justify-content:space-between; height:36px; padding:0; border-top:1px solid var(--shop-line); margin-top:12px; border-radius:0; color:var(--foreground); font-size:11px; }
.shop-placeholder { position:absolute; width:48px; height:48px; top:calc(50% - 24px); left:calc(50% - 24px); color:var(--shop-photo-ink); }
.shop-disclosure { padding:24px 0 0; border-top:1px solid var(--border); font-size:11px; line-height:1.8; color:var(--muted-foreground); }
.shop-dialog { position:relative; max-width:440px; max-height:85vh; overflow-y:auto; border:1px solid var(--shop-line); border-radius:8px; background:var(--popover); backdrop-filter:blur(24px); }
.shop-dialog-close { position:absolute; right:12px; top:12px; z-index:1; }.shop-dialog-image { width:100%; max-height:40vh; object-fit:contain; background:var(--shop-photo); border-radius:4px; }
.nft-card-art { object-fit:contain; background:var(--shop-photo); }.nft-card-top { position:relative; background:var(--card); }.nft-card { box-shadow:var(--shop-shadow); }
@media(max-width:1000px){.shop-grid{grid-template-columns:repeat(3,minmax(0,1fr));}}
@media(max-width:640px){.shop-heading{align-items:start;flex-direction:column;gap:16px;}.shop-heading h1{font-size:27px;}.shop-intro{align-items:start;flex-direction:column;gap:8px;}.shop-tabs{gap:0;}.shop-tabs button{font-size:11px;padding:10px 9px;}.shop-grid,.shop-grid-merch{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}.shop-item-meta{padding:10px;}.shop-item-meta h3{font-size:13px;}.shop-toolbar select{max-width:148px;}.shop-section-title h2{font-size:20px;}}
@media(prefers-reduced-motion:reduce){.shop-item{transition:none;}.shop-item:hover{transform:none;}}

