/* Wallet balance color skins (owner-rotated daily) */
.wallet-summary[data-wallet-skin="auric"], .wallet-swatch[data-skin="auric"] { --skin-a: oklch(0.86 0.17 85); --skin-b: oklch(0.68 0.16 60); }
