.wallet-summary[data-wallet-skin="emerald"], .wallet-swatch[data-skin="emerald"] { --skin-a: oklch(0.7 0.19 150); --skin-b: oklch(0.52 0.16 150); }
.wallet-summary[data-wallet-skin="sapphire"], .wallet-swatch[data-skin="sapphire"] { --skin-a: oklch(0.66 0.17 245); --skin-b: oklch(0.5 0.16 250); }
.wallet-summary[data-wallet-skin="ruby"], .wallet-swatch[data-skin="ruby"] { --skin-a: oklch(0.7 0.2 40); --skin-b: oklch(0.6 0.22 30); }
