/* Scoped financial motion and purchase presentation. */
:root { --finance-gold:oklch(.83 .13 85); --finance-edge:color-mix(in oklch,var(--finance-gold) 45%,var(--border)); --finance-shadow:0 6px 16px color-mix(in oklch,var(--background) 28%,transparent); }
