@keyframes finance-bars { 0%,100% { transform:scaleY(.5); } 50% { transform:scaleY(1); } }
.presale-purchase-dialog { width:calc(100% - 32px); max-width:420px; max-height:90dvh; overflow-y:auto; padding:0; gap:0; border-radius:8px; border-color:var(--finance-edge); background:var(--card); box-shadow:var(--finance-shadow); }
