@media(prefers-reduced-motion:reduce) { .finance-coins span,.finance-network svg,.finance-chart span { animation:none; } }

/* Batch polish: clean light wallet, compact dialog, clean presale cards, slim powered-by */
html[data-color-mode="light"] .wallet-summary[data-wallet-skin] { box-shadow: 0 1px 3px color-mix(in oklab, var(--foreground) 8%, transparent) !important; border-color: color-mix(in oklab, var(--foreground) 10%, transparent) !important; background: linear-gradient(135deg, var(--skin-a), var(--skin-b)) !important; animation: none !important; }
