.presale-purchase-dialog .purchase-art { height: 64px; }
.presale-purchase-dialog .purchase-details { padding: 14px 16px 16px; }
.presale-purchase-dialog .purchase-details strong.text-3xl { font-size: 1.6rem; margin-top: .6rem; }
.presale-purchase-dialog dl { margin-top: .6rem; }
.presale-purchase-dialog dl > div { padding-top: .35rem; padding-bottom: .35rem; }
.presale-lux-card { background: linear-gradient(160deg, color-mix(in oklab, var(--card) 92%, var(--chart-3)), var(--card)) !important; }
.presale-lux-card::before { display: none; }
.presale-lux-inner { padding: 18px !important; }
.nft-preview-chip { display: inline-flex; align-items: center; gap: 4px; padding: 3px 8px; border-radius: 999px; font-size: 10px; font-weight: 800; color: var(--chart-3); border: 1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); background: color-mix(in oklab, var(--chart-3) 8%, transparent); }
.nft-preview-dialog { width: calc(100% - 40px); max-width: 300px; padding: 0; gap: 0; overflow: hidden; border-radius: 12px; background: var(--card); }
.nft-preview-dialog img { display: block; width: 100%; aspect-ratio: 3/4; object-fit: cover; }
.powered-by--slim { padding-top: 1.25rem; padding-bottom: 1.25rem; }
.powered-by--slim .powered-row { display: flex; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; gap: 6px; margin-top: 10px; }
.powered-by--slim .powered-row::-webkit-scrollbar { display: none; }
.powered-by--slim .powered-badge { flex: 0 0 auto; padding: 5px 10px; font-size: 10px; white-space: nowrap; }

/* Wallet: clean luxury card (no glow), bright skins, futuristic tiles, slim powered strip */
.wallet-summary[data-wallet-skin="auric"], .wallet-swatch[data-skin="auric"] { --skin-a: oklch(0.88 0.15 88); --skin-b: oklch(0.66 0.15 65); }
.wallet-summary[data-wallet-skin="violet"], .wallet-swatch[data-skin="violet"] { --skin-a: oklch(0.68 0.2 305); --skin-b: oklch(0.48 0.2 285); }
.wallet-summary[data-wallet-skin="emerald"], .wallet-swatch[data-skin="emerald"] { --skin-a: oklch(0.78 0.17 160); --skin-b: oklch(0.55 0.14 175); }
.wallet-summary[data-wallet-skin="sapphire"], .wallet-swatch[data-skin="sapphire"] { --skin-a: oklch(0.74 0.15 230); --skin-b: oklch(0.52 0.18 260); }
.wallet-summary[data-wallet-skin="ruby"], .wallet-swatch[data-skin="ruby"] { --skin-a: oklch(0.78 0.17 55); --skin-b: oklch(0.6 0.21 25); }
.site-shell .wallet-summary, .site-shell .wallet-vault, html .wallet-summary[data-wallet-skin] { box-shadow: inset 0 1px 0 oklch(1 0 0 / 22%), 0 1px 2px oklch(0 0 0 / 12%) !important; border: 1px solid oklch(1 0 0 / 16%) !important; animation: none !important; }
.wallet-summary[data-wallet-skin] { background: linear-gradient(120deg, oklch(1 0 0 / 16%) 0%, transparent 38%), linear-gradient(135deg, var(--skin-a), var(--skin-b)) !important; }
.wallet-summary[data-wallet-skin] strong, html .wallet-summary strong { text-shadow: none !important; }
.wallet-summary::before { content:""; position:absolute; inset:0; pointer-events:none; z-index:0; background-image: linear-gradient(oklch(1 0 0 / 5%) 1px, transparent 1px), linear-gradient(90deg, oklch(1 0 0 / 5%) 1px, transparent 1px); background-size: 28px 28px; mask-image: linear-gradient(135deg, transparent 40%, black); }
html[data-color-mode="light"] .site-shell .wallet-summary { border-color: color-mix(in oklab, var(--foreground) 10%, transparent) !important; box-shadow: 0 1px 2px color-mix(in oklab, var(--foreground) 8%, transparent) !important; }

.wallet-tile { position: relative; overflow: hidden; display: flex; flex-direction: column; gap: 14px; padding: 14px; border-radius: 16px; border: 1px solid color-mix(in oklab, var(--tile) 35%, var(--border)); background: linear-gradient(150deg, color-mix(in oklab, var(--tile) 12%, var(--card)), var(--card) 65%); transition: border-color .2s, transform .2s; }
.wallet-tile::after { content:""; position:absolute; top:0; left:14px; right:14px; height:1px; background: linear-gradient(90deg, transparent, var(--tile), transparent); opacity:.7; }
.wallet-tile:hover { border-color: var(--tile); transform: translateY(-1px); }
.wallet-tile--pay { --tile: var(--chart-2); }
.wallet-tile--transfer { --tile: var(--chart-3); }
.wallet-tile-top { display:flex; align-items:center; justify-content:space-between; }
.wallet-tile-icon { display:grid; place-items:center; width:38px; height:38px; border-radius:11px; color: var(--tile); border: 1px solid color-mix(in oklab, var(--tile) 45%, transparent); background: color-mix(in oklab, var(--tile) 10%, transparent); }
.wallet-tile-status { display:inline-flex; align-items:center; gap:5px; font-family: ui-monospace, monospace; font-size:9px; font-weight:700; letter-spacing:.14em; color: var(--muted-foreground); }
.wallet-tile-status i { width:6px; height:6px; border-radius:50%; background: var(--muted-foreground); }
.wallet-tile-status.is-open { color: var(--tile); }
.wallet-tile-status.is-open i { background: var(--tile); animation: tile-dot 1.8s ease-in-out infinite; }
@keyframes tile-dot { 50% { opacity: .35; } }
.wallet-tile-title { display:block; font-family: var(--font-display, inherit); font-weight:900; letter-spacing:.08em; }
.wallet-tile-sub { font-size:11px; line-height:1rem; color: var(--muted-foreground); }

.powered-strip { margin: 24px auto 0; max-width: 64rem; padding: 0 20px; }
.powered-strip-row { display:flex; align-items:center; gap:6px; overflow-x:auto; scrollbar-width:none; }
.powered-strip-row::-webkit-scrollbar { display:none; }
.powered-strip-label { flex:0 0 auto; font-size:9px; font-weight:800; letter-spacing:.16em; color: var(--muted-foreground); margin-right:4px; }
.powered-strip-chip { flex:0 0 auto; display:inline-flex; align-items:center; gap:4px; padding:3px 8px; border-radius:999px; border:1px solid var(--border); font-size:10px; font-weight:700; }
.powered-strip-note { margin-top:6px; font-size:9px; color: var(--muted-foreground); }
@media(prefers-reduced-motion:reduce) { .wallet-tile-status.is-open i { animation:none; } }

.wallet-quick-actions { position:fixed; bottom:calc(84px + env(safe-area-inset-bottom)); left:50%; transform:translateX(-50%); z-index:30; display:flex; align-items:center; border:1px solid var(--border); border-radius:8px; padding:4px; background:var(--card); box-shadow:var(--shadow-sm); white-space:nowrap; }
.allocation-progress { appearance:none; width:100%; height:5px; border:0; background:var(--muted); color:var(--chart-3); }
.allocation-progress::-webkit-progress-bar { background:var(--muted); }
.allocation-progress::-webkit-progress-value { background:var(--chart-3); }
.allocation-progress::-moz-progress-bar { background:var(--chart-3); }
@media(min-width:768px) { .wallet-quick-actions { bottom:20px; } }

/* Shared phone polish: measured spacing, stable controls and contained dialogs. */
.site-shell main { min-width:0; }
.site-shell main :is(h1,h2,h3,p,dd) { overflow-wrap:anywhere; }
.section-title { letter-spacing:0; }
.wallet-tile-sub { display:block; min-height:32px; }
.modal-panel { max-height:calc(100dvh - 32px); overflow-y:auto; overscroll-behavior:contain; }
.glass-dock { bottom:calc(12px + env(safe-area-inset-bottom)); padding-bottom:0; }
.glass-dock .mobile-nav-on { color:var(--chart-3) !important; text-shadow:none; }
.wallet-quick-actions { max-width:calc(100% - 32px); }
@media (min-width:768px) and (max-width:1279px) { .wallet-quick-actions { bottom:calc(84px + env(safe-area-inset-bottom)); } }
@media (max-width:767px) {
  .site-shell main { padding-left:16px; padding-right:16px; padding-top:24px; padding-bottom:120px; }
