  .site-header .header-island { padding:1px; box-shadow:none; }
  .site-header .header-island .mode-toggle { width:28px; }
  .site-header .header-island .language-trigger { width:30px; }
  .site-header .header-reviewer { width:28px; padding:0; }
  .site-header .header-reviewer span { display:none; }
  .site-header .header-signin { font-size:10px; }
  .notification-menu { max-width:calc(100vw - 24px); }
  .site-shell .wallet-summary, .site-shell .vault-swap { padding:18px; border-radius:8px; }
  .wallet-summary .vault-pill { font-size:8px; padding:4px 7px; }
  .vault-swap > div:first-child { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; }
  .vault-swap > div:first-child .vault-pill { font-size:10px; }
  .wallet-tile { border-radius:8px; gap:10px; padding:12px; }
