  .settings-console a { overflow-wrap:anywhere; }
  .settings-console .settings-row { min-width:0; }
  .settings-rail nav { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .settings-rail nav a { min-width:0; padding:10px 6px; gap:6px; font-size:10px; }
  .settings-rail nav svg { flex-shrink:0; }
  .admin-navigation + [role="status"] { overflow-wrap:anywhere; }
}
@media (max-width:359px) {
  .site-header .header-tools { gap:0 !important; }
  .site-header .header-brand img { width:28px; height:28px; }
  .site-header .brand-mark { font-size:12px; }
  .site-header > div { padding-inline:8px; gap:4px; }
  .site-header .header-icon { width:25px; }
  .glass-dock a { font-size:9px; }
}

/* Centered compact dialogs (presale + announcement pop-ups): flex-free centering that survives zoom animation on mobile */
.site-popup { position:fixed !important; top:50% !important; left:50% !important; right:auto !important; bottom:auto !important; margin:0 !important; transform:translate(-50%, -50%) !important; translate:none !important; scale:none; width:min(360px, calc(100vw - 32px)) !important; max-width:none !important; height:auto !important; max-height:calc(100dvh - 40px) !important; overflow-y:auto; overscroll-behavior:contain; }
.site-popup[data-state] { animation:popup-in .22s ease-out !important; }
@keyframes popup-in { from { opacity:0; } to { opacity:1; } }
@keyframes sheet-up { from { transform:translateY(100%); } to { transform:translateY(0); } }

/* Luxury editorial boutique */
.boutique-card { position:relative; overflow:hidden; border-radius:16px; border:1px solid var(--border); background:var(--card); transition:transform .25s var(--ease), border-color .25s var(--ease); }
.boutique-card:hover { transform:translateY(-2px); border-color:color-mix(in oklab, var(--chart-3) 55%, var(--border)); }
.boutique-art { position:relative; aspect-ratio:3/4; }
.boutique-card--editorial .boutique-art { aspect-ratio:16/10; }
.boutique-lot { position:absolute; top:8px; left:8px; border-radius:999px; padding:2px 8px; font:700 9px/1.6 "JetBrains Mono", monospace; letter-spacing:.1em; color:var(--chart-3); background:color-mix(in oklab, var(--background) 75%, transparent); border:1px solid color-mix(in oklab, var(--chart-3) 40%, transparent); }
.boutique-body { padding:12px; font-size:12px; }
.boutique-badge { display:inline-flex; flex-shrink:0; align-items:center; gap:3px; font-size:9px; font-weight:800; letter-spacing:.08em; text-transform:uppercase; color:var(--chart-3); }
.boutique-cta { margin-top:8px; display:block; border-radius:999px; border:1px solid var(--chart-3); padding:5px; text-align:center; font-size:11px; font-weight:800; color:var(--chart-3); }
.boutique-toggle { margin-top:16px; display:inline-flex; gap:2px; border:1px solid var(--border); border-radius:999px; padding:2px; }
.boutique-toggle button { border-radius:999px; padding:4px 12px; font-size:11px; font-weight:700; color:var(--muted-foreground); }
.boutique-toggle button[aria-pressed=true] { background:var(--chart-3); color:var(--background); }

/* Specular metal sheen on premium presale cards */
.presale-lux-card { position:relative; overflow:hidden; }
.presale-lux-card::after { content:""; position:absolute; inset:0; pointer-events:none; background:linear-gradient(115deg, transparent 35%, color-mix(in oklab, var(--chart-3) 18%, transparent) 50%, transparent 65%); transform:translateX(-120%); animation:lux-sheen 6s ease-in-out infinite; }
@keyframes lux-sheen { 0%,60% { transform:translateX(-120%); } 100% { transform:translateX(120%); } }
@media (prefers-reduced-motion:reduce) { .presale-lux-card::after { animation:none; display:none; } }
.numeric, .font-mono { font-variant-numeric: tabular-nums; }
.site-popup { padding:0; gap:0; border-radius:14px; border-color:color-mix(in oklab, var(--chart-3) 45%, var(--border)); background:linear-gradient(165deg, color-mix(in oklab, var(--card) 94%, var(--chart-3)), var(--card)); box-shadow:var(--sh-3); }
.site-popup > button { background:color-mix(in oklab, var(--card) 80%, transparent); border-radius:999px; padding:5px; z-index:2; }
.site-popup__art { aspect-ratio:16/10; overflow:hidden; background:var(--background); }
.site-popup__img { display:block; width:100%; height:100%; object-fit:cover; }
.site-popup__body { padding:16px 18px 18px; }
.site-popup__eyebrow { display:block; margin-bottom:6px; font-size:9px; font-weight:800; letter-spacing:.12em; color:var(--chart-3); }

/* BIX PAY receive card */
.pay-qr-card { position:relative; margin-inline:auto; width:min(100%, 300px); border-radius:22px; padding:18px; border:1px solid color-mix(in oklab, var(--chart-3) 50%, var(--border)); background:linear-gradient(160deg, color-mix(in oklab, var(--card) 88%, var(--chart-3)), var(--card)); box-shadow:var(--sh-2); }
.pay-qr-card__head { display:flex; align-items:center; justify-content:space-between; gap:8px; font-size:10px; font-weight:800; letter-spacing:.1em; color:var(--chart-3); }
.pay-qr-plate { position:relative; margin-top:14px; border-radius:16px; padding:14px; background:oklch(0.99 0 0); }
.pay-qr-plate svg { display:block; width:100%; height:auto; }
.pay-qr-plate::before, .pay-qr-plate::after { content:""; position:absolute; width:22px; height:22px; border:2px solid var(--chart-3); }
.pay-qr-plate::before { top:-6px; left:-6px; border-right:0; border-bottom:0; border-top-left-radius:10px; }
.pay-qr-plate::after { bottom:-6px; right:-6px; border-left:0; border-top:0; border-bottom-right-radius:10px; }
.pay-qr-code { margin-top:14px; display:flex; align-items:center; justify-content:center; gap:8px; border-radius:999px; border:1px dashed color-mix(in oklab, var(--chart-3) 50%, transparent); padding:8px 12px; font-weight:800; }
.tx-hint { margin-top:6px; font-size:10.5px; line-height:1.5; color:var(--muted-foreground); text-align:center; }

/* Presale purchase: flex frame centers the sheet without transforms */
.pp-frame { position:fixed; inset:0; z-index:51; display:flex; align-items:center; justify-content:center; padding:16px; pointer-events:none; }
.pp-sheet { position:relative; pointer-events:auto; width:100%; max-width:380px; max-height:calc(100dvh - 32px); overflow-y:auto; overscroll-behavior:contain; border:1px solid var(--finance-edge, var(--border)); border-radius:16px; background:var(--card); box-shadow:var(--sh-3); animation:popup-in .22s ease-out; }
.pp-sheet .purchase-art { position:relative; height:64px; overflow:hidden; }
.pp-sheet .purchase-art img { width:100%; height:100%; object-fit:cover; }
.pp-sheet .purchase-art span { position:absolute; left:12px; bottom:8px; display:inline-flex; gap:5px; align-items:center; font-size:9px; font-weight:800; letter-spacing:.12em; color:var(--chart-3); }
.pp-sheet .purchase-details { padding:14px 16px 16px; }
.pp-close { position:absolute; top:10px; right:10px; display:grid; place-items:center; width:30px; height:30px; border-radius:999px; background:color-mix(in oklab, var(--card) 80%, transparent); color:var(--foreground); }
@media (max-width:640px) {
  .pp-frame { align-items:flex-end; padding:0; }
  .pp-sheet { max-width:none; max-height:90dvh; border-radius:20px 20px 0 0; border-bottom:0; padding-bottom:env(safe-area-inset-bottom); animation:sheet-up .26s cubic-bezier(.2,.8,.2,1); }
}
/* Zen / Pro view switch */
html[data-view="zen"] .pro-only { display:none !important; }
.view-switch { height:32px; padding:0 8px; border-radius:999px; font:800 9px/1 "JetBrains Mono", monospace; letter-spacing:.1em; color:var(--chart-3); border:1px solid color-mix(in oklab, var(--chart-3) 40%, var(--border)); }

/* Hero presale ribbon */
.hero-ribbon { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:10px; padding:8px 8px 8px 14px; border-radius:999px; border:1px solid color-mix(in oklab,var(--chart-3) 45%,transparent); background:color-mix(in oklab,var(--card) 70%,transparent); backdrop-filter:blur(14px); text-align:left; }
.hero-ribbon-live { display:flex; align-items:center; gap:7px; font-size:9px; font-weight:800; letter-spacing:.14em; color:var(--chart-2); white-space:nowrap; }
.hero-ribbon-live i { width:7px; height:7px; border-radius:50%; background:var(--chart-2); animation:pulse 1.6s infinite; }
.hero-ribbon-live b { color:var(--foreground); font-size:12px; letter-spacing:.04em; }
.hero-ribbon-path { display:flex; justify-content:center; gap:6px; font-size:11px; color:var(--muted-foreground); }
.hero-ribbon-path .is-on { color:var(--chart-3); font-weight:800; }
.hero-ribbon-path em { font-style:normal; margin-right:6px; opacity:.5; }
.hero-ribbon-cta { border-radius:999px; padding:7px 14px; font-size:11px; font-weight:800; white-space:nowrap; background:linear-gradient(135deg,var(--chart-3),color-mix(in oklab,var(--chart-3) 60%,var(--primary))); color:var(--primary-foreground); }
.hero-ribbon-note { grid-column:1/-1; font-size:9px; color:var(--muted-foreground); text-align:center; }
@media (max-width:640px){ .hero-ribbon { grid-template-columns:1fr auto; border-radius:18px; } .hero-ribbon-path { grid-column:1/-1; grid-row:2; } }

/* Member header: swipeable tools rail */
.header-brand { flex-shrink:0; padding-right:10px; margin-right:4px; border-right:1px solid color-mix(in oklab,var(--border) 70%,transparent); }
@media (max-width:767px){
  .site-header .header-tools { min-width:0; overflow-x:auto; overscroll-behavior-x:contain; scroll-snap-type:x proximity; scrollbar-width:none; -webkit-overflow-scrolling:touch; padding:2px 2px; mask-image:none; }
  .site-header .header-tools::-webkit-scrollbar { display:none; }
  .site-header .header-tools > * { flex-shrink:0; scroll-snap-align:start; }
  .site-header .language-menu, .site-header .notification-menu { position:fixed !important; top:58px; right:10px; z-index:60; }
}

/* Marketplace atelier */
.atelier-head { position:relative; display:grid; gap:10px; padding-bottom:22px; text-align:left; }
.atelier-kicker { font-size:10px; letter-spacing:.32em; color:var(--muted-foreground); }
.atelier-head h1 { font-family:var(--font-display); font-weight:900; font-size:clamp(2rem,6vw,3.8rem); line-height:.95; background:linear-gradient(180deg,var(--foreground),color-mix(in oklab,var(--foreground) 45%,var(--background))); -webkit-background-clip:text; background-clip:text; color:transparent; }
.atelier-head h1 span { background:linear-gradient(100deg,#FFD700,#ffb347 45%,#A855F7); -webkit-background-clip:text; background-clip:text; color:transparent; }
.atelier-line { height:1px; background:linear-gradient(90deg,#FFD700,#A855F7 50%,transparent); }
.atelier-head .shop-outline { justify-self:start; }
.atelier-info { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:10px; margin:6px 0 18px; }
@media (max-width:640px){ .atelier-info { grid-template-columns:repeat(2,minmax(0,1fr)); } }
.atelier-box { --tone:#FFD700; text-align:left; padding:14px; border-radius:16px; border:1px solid color-mix(in oklab,var(--tone) 55%,transparent); background:linear-gradient(150deg,color-mix(in oklab,var(--tone) 18%,var(--card)),var(--card)); transition:transform .2s; }
.atelier-box:hover { transform:translateY(-2px); }
