.atelier-box--violet { --tone:#A855F7; } .atelier-box--gold { --tone:#FFD700; } .atelier-box--emerald { --tone:#39FF14; } .atelier-box--cyan { --tone:#00F0FF; }
.atelier-tabs [aria-selected="true"] { border-color:#FFD700 !important; color:#FFD700 !important; box-shadow:0 0 14px color-mix(in oklab,#FFD700 35%,transparent); }

/* Marketplace atelier v2 (reference layout) */
.atelier-head { justify-items:center; text-align:center; }
.atelier-emblem { width:min(220px,58vw); aspect-ratio:800/870; object-fit:cover; border-radius:24px; mask-image:radial-gradient(circle,#000 62%,transparent 75%); }
.atelier-actions { display:flex; flex-wrap:wrap; justify-content:center; gap:10px; }
