.atelier-box { display:flex; flex-direction:column; align-items:center; gap:6px; text-align:center; padding:22px 12px; border-radius:20px; backdrop-filter:blur(12px); background:linear-gradient(160deg,color-mix(in oklab,var(--tone) 14%,transparent),color-mix(in oklab,var(--card) 80%,transparent)); box-shadow:0 0 18px color-mix(in oklab,var(--tone) 30%,transparent), inset 0 0 12px color-mix(in oklab,var(--tone) 12%,transparent); color:var(--tone); }
.atelier-box span { font-size:12px; }
.site-header .header-tools { justify-self:end; max-width:100%; }

/* Subtle micro-inertia motion layer (presentation only) */
@media (prefers-reduced-motion: no-preference) {
  .hero-ribbon { animation: lux-float 7s ease-in-out infinite; }
  .atelier-emblem { animation: lux-float 9s ease-in-out infinite; }
  .atelier-box, .presale-lux-card, .shop-item, .boutique-card {
    transition: transform .5s cubic-bezier(.2,.8,.2,1), border-color .4s ease;
    will-change: transform;
  }
  .atelier-box:hover, .presale-lux-card:hover, .shop-item:hover, .boutique-card:hover { transform: translateY(-4px) scale(1.01); }
  .atelier-box { position: relative; overflow: hidden; }
  .atelier-box::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(115deg, transparent 35%, color-mix(in oklab, var(--foreground) 14%, transparent) 50%, transparent 65%); transform: translateX(-120%); transition: transform .9s ease; }
  .atelier-box:hover::after { transform: translateX(120%); }
  @supports (animation-timeline: view()) {
    .atelier-box, .presale-lux-card, .shop-item, .boutique-card, .shop-section-title {
      animation: lux-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 60%;
    }
  }
}
@keyframes lux-float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
@keyframes lux-reveal { from { opacity: 0; transform: translateY(24px) scale(.98); } to { opacity: 1; transform: none; } }

/* Language menu: fixed so header scroll rail never clips it; 11 flags */
.site-header .language-menu { position: fixed; top: 62px; right: 12px; z-index: 80; width: 160px; grid-template-columns: repeat(3, 1fr); }
.flag-in { background: linear-gradient(oklch(0.72 0.17 55) 0 33%, var(--foreground) 33% 67%, oklch(0.55 0.15 150) 67%); }
.flag-in::after { content: ""; position: absolute; top: 5px; left: 9px; width: 4px; height: 4px; border-radius: 50%; border: 1px solid oklch(0.34 0.16 264); }
.flag-es { background: linear-gradient(var(--destructive) 0 25%, var(--chart-3) 25% 75%, var(--destructive) 75%); }
.flag-br { background: oklch(0.55 0.15 150); }
.flag-br::before { content: ""; position: absolute; inset: 2px 3px; background: var(--chart-3); clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%); }
.flag-br::after { content: ""; position: absolute; top: 4px; left: 8px; width: 7px; height: 7px; border-radius: 50%; background: oklch(0.34 0.16 264); }

/* Language menu portal (escapes header blur/scroll on phones) */
.language-menu--portal { position: fixed !important; top: 62px; right: 12px; z-index: 90; width: 160px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; border: 1px solid var(--border); border-radius: 12px; padding: 7px; background: var(--popover); box-shadow: 0 12px 32px color-mix(in oklab, var(--background) 60%, transparent); }
