.sovereign-card { border: 1px solid color-mix(in oklab, var(--primary) 55%, transparent) !important; box-shadow: inset 0 1px 0 color-mix(in oklab, var(--primary) 40%, transparent), inset 0 0 0 4px color-mix(in oklab, var(--background) 80%, transparent), inset 0 0 0 5px color-mix(in oklab, var(--primary) 25%, transparent), 0 18px 40px -24px oklch(0 0 0 / 70%) !important; }
