/* ===== Final polish: zoom lock, medium announcement, compact clean wallet, clean reactor ===== */
html, body { touch-action: pan-x pan-y; -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }

.site-popup { width: min(500px, calc(100vw - 28px)) !important; border-radius: 18px; }
.site-popup__art { aspect-ratio: 16/9; }
.site-popup__body { padding: 18px 20px 20px; }

.reactor-apy-pill { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 8px; margin: 12px auto 0; width: fit-content; max-width: 100%; padding: 6px 14px; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--chart-3) 45%, var(--border)); background: var(--card); color: var(--foreground); box-shadow: none; }
