.wallet-summary > p { margin-top: 6px !important; }
.wallet-summary .mt-5.grid { margin-top: 12px !important; }
.wallet-summary .vault-btn-primary, .wallet-summary .vault-btn-ghost { height: 38px; }

/* 5 bright solid skins, no glow */
.wallet-summary[data-wallet-skin="auric"], .wallet-swatch[data-skin="auric"] { --skin-a: oklch(0.84 0.15 85); --skin-b: oklch(0.76 0.15 75); }
.wallet-summary[data-wallet-skin="violet"], .wallet-swatch[data-skin="violet"] { --skin-a: oklch(0.6 0.2 300); --skin-b: oklch(0.54 0.21 295); }
.wallet-summary[data-wallet-skin="emerald"], .wallet-swatch[data-skin="emerald"] { --skin-a: oklch(0.66 0.15 160); --skin-b: oklch(0.58 0.14 165); }
.wallet-summary[data-wallet-skin="sapphire"], .wallet-swatch[data-skin="sapphire"] { --skin-a: oklch(0.6 0.17 255); --skin-b: oklch(0.52 0.18 260); }
.wallet-summary[data-wallet-skin="ruby"], .wallet-swatch[data-skin="ruby"] { --skin-a: oklch(0.6 0.2 25); --skin-b: oklch(0.53 0.2 22); }
.wallet-summary[data-wallet-skin] { --wallet-on: oklch(0.99 0 0); }
.wallet-summary[data-wallet-skin="auric"] { --wallet-on: oklch(0.22 0.03 70); }
html .site-shell .wallet-summary[data-wallet-skin], html .wallet-summary[data-wallet-skin] { background: linear-gradient(135deg, var(--skin-a), var(--skin-b)) !important; box-shadow: inset 0 1px 0 oklch(1 0 0 / 25%) !important; border: 1px solid oklch(1 0 0 / 22%) !important; animation: none !important; backdrop-filter: none !important; }
.wallet-summary[data-wallet-skin]::after, .wallet-summary[data-wallet-skin]::before { display: none !important; }
