.wallet-summary[data-wallet-skin="auric"] .wallet-fx-grid > div, .wallet-summary[data-wallet-skin="auric"] .vault-pill { background: oklch(0.2 0.03 70 / 10%) !important; border-color: oklch(0.2 0.03 70 / 22%) !important; }

/* Compact internal swap */
.vault-swap { padding: 16px 18px !important; margin-top: 20px !important; box-shadow: none !important; }
