.vault-swap > .mt-4.grid .form-input { margin-top: 4px; height: 38px; }
.vault-swap > .mt-4.grid > button { margin-bottom: 0 !important; margin-top: 14px; }
.vault-swap > p { margin-top: 10px !important; font-size: 10px !important; }
.vault-swap > button { margin-top: 10px !important; height: 40px; }

.splash-emblem { display: grid; justify-items: center; gap: 14px; background: none; border: 0; color: var(--splash-gold); font-family: var(--font-display); font-weight: 800; letter-spacing: .3em; font-size: 12px; }
.splash-emblem img { border-radius: 50%; animation: splash-pulse 900ms var(--ease) infinite alternate; }
@keyframes splash-pulse { from { transform: scale(.94); opacity: .75; } to { transform: scale(1.02); opacity: 1; } }
.route-progress { position: fixed; top: 0; left: 0; height: 2px; width: 100%; z-index: 120; background: linear-gradient(90deg, transparent, #EAB308, #FEF08A); transform-origin: left; animation: route-progress 1.2s ease-out forwards; pointer-events: none; }
@keyframes route-progress { from { transform: scaleX(0); } to { transform: scaleX(.9); } }
@media (max-width: 480px) { .view-switch { display: none; } }
@media (prefers-reduced-motion: reduce) { .splash-emblem img, .route-progress { animation: none; } }

/* Luxury gold bullion frame */
.nft-lux-frame { position: relative; padding: 6px; border-radius: 18px; background: linear-gradient(145deg, oklch(0.86 0.11 85), oklch(0.55 0.09 70) 35%, oklch(0.2 0.01 60) 50%, oklch(0.62 0.1 75) 65%, oklch(0.9 0.09 88)); box-shadow: inset 0 0 0 1px oklch(0.95 0.06 90 / .55), 0 14px 30px -18px oklch(0.15 0.02 60 / .8); }
.nft-lux-frame > * { position: relative; }
.nft-lux-frame .nft-catalog-art { border-radius: 12px; box-shadow: inset 0 0 0 1px oklch(0.85 0.1 85 / .6); }
.nft-lux-frame .nft-card-top, .nft-lux-frame .nft-card-foot { letter-spacing: .14em; }
.nft-lux-frame .nft-card-foot span { color: oklch(0.82 0.11 85); font-size: 9px; font-weight: 800; }
.nft-lux-corner { position: absolute; inset: 10px; pointer-events: none; z-index: 2; border-radius: 12px; background: linear-gradient(oklch(0.88 0.1 86),oklch(0.88 0.1 86)) top left/14px 1.5px, linear-gradient(oklch(0.88 0.1 86),oklch(0.88 0.1 86)) top left/1.5px 14px, linear-gradient(oklch(0.88 0.1 86),oklch(0.88 0.1 86)) bottom right/14px 1.5px, linear-gradient(oklch(0.88 0.1 86),oklch(0.88 0.1 86)) bottom right/1.5px 14px; background-repeat: no-repeat; }

/* Deposit flight scanner */
.dep-flight { margin-top: .75rem; border: 1px solid var(--border); border-radius: 1rem; padding: .75rem; background: color-mix(in oklab, var(--card) 85%, transparent); }
.dep-flight-sky { position: relative; height: 84px; overflow: hidden; border-radius: .75rem; background: radial-gradient(circle at 50% 50%, color-mix(in oklab, var(--chart-3) 18%, transparent), transparent 70%); }
.dep-flight-radar { position: absolute; left: 50%; top: 50%; width: 70px; height: 70px; margin: -35px 0 0 -35px; border-radius: 9999px; border: 1px solid color-mix(in oklab, var(--chart-3) 60%, transparent); animation: dep-radar 1.8s ease-out infinite; }
.dep-flight-plane { position: absolute; top: 50%; left: -40px; color: var(--chart-3); transform: translateY(-50%) rotate(45deg); animation: dep-fly 2.6s ease-in-out infinite; filter: drop-shadow(0 0 6px color-mix(in oklab, var(--chart-3) 60%, transparent)); }
.dep-flight-trail { position: absolute; top: 50%; left: 0; height: 2px; width: 0; background: linear-gradient(90deg, transparent, var(--chart-3)); animation: dep-trail 2.6s ease-in-out infinite; }
.dep-flight-text { margin-top: .5rem; text-align: center; font-size: .75rem; font-weight: 700; color: var(--chart-3); }
.dep-flight.is-done .dep-flight-plane { animation: dep-warp .8s ease-in forwards; }
.dep-flight.is-done .dep-flight-text { color: var(--chart-2); }
@keyframes dep-fly { 0% { left: -40px; } 100% { left: calc(100% + 40px); } }
@keyframes dep-trail { 0% { width: 0; } 100% { width: 100%; opacity: 0; } }
@keyframes dep-radar { 0% { transform: scale(.4); opacity: 1; } 100% { transform: scale(2.2); opacity: 0; } }
@keyframes dep-warp { 0% { left: 40%; } 100% { left: 130%; transform: translateY(-50%) rotate(45deg) scale(1.6); } }
@media (prefers-reduced-motion: reduce) { .dep-flight-plane, .dep-flight-trail, .dep-flight-radar { animation: none; left: 45%; } }

/* Deposit panel — compact luxury, centered, no horizontal shift */
.deposit-panel { width: min(100%, 400px); padding: 18px 16px !important; border-radius: 20px; border-color: color-mix(in oklab, var(--chart-3) 40%, transparent) !important; background: linear-gradient(170deg, color-mix(in oklab, var(--card) 96%, var(--chart-3)), var(--card)) !important; overflow-x: hidden; }
.deposit-panel h3 { font-size: 1.15rem; letter-spacing: .14em; text-transform: uppercase; }
.deposit-panel > * { min-width: 0; max-width: 100%; }
.deposit-panel .grid { min-width: 0; }
.dep-chip { display: flex; min-width: 0; flex-direction: column; align-items: center; justify-content: center; gap: 2px; padding: 7px 6px; border-radius: 12px; border: 1px solid var(--border); background: color-mix(in oklab, var(--background) 60%, transparent); text-align: center; transition: border-color .2s, background .2s; }
.dep-chip b { font: 700 11px/1.2 ui-monospace, monospace; letter-spacing: .08em; color: var(--chart-3); }
.dep-chip span { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 9px; letter-spacing: .06em; color: var(--muted-foreground); }
