/* ===== Landing hero clarity & luxury pass (both modes) ===== */
:root { --hero-gold-hi: oklch(0.93 0.11 92); --hero-gold: oklch(0.8 0.15 82); --hero-gold-deep: oklch(0.58 0.13 70); }
.landing-hero-compact .hero-title { background: linear-gradient(180deg, var(--hero-gold-hi) 0%, var(--hero-gold) 48%, var(--hero-gold-deep) 100%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 4px 14px color-mix(in oklch, var(--hero-gold-deep) 45%, transparent)); background-size: 100% 200%; animation: hero-sheen 6s ease-in-out infinite alternate; }
@keyframes hero-sheen { to { background-position: 0 100%; } }
.landing-hero-compact .hero-tagline { color: var(--foreground); text-shadow: 0 1px 10px color-mix(in oklch, var(--background) 70%, transparent); }
.landing-hero-compact .hero-chip { border: 1px solid color-mix(in oklch, var(--hero-gold) 55%, transparent); background: color-mix(in oklch, var(--background) 55%, transparent); color: var(--hero-gold); backdrop-filter: blur(10px); }
.landing-hero-compact .landing-hero-metrics > div { background: color-mix(in oklch, var(--card) 78%, transparent) !important; transition: transform .25s ease; }
