html[data-color-mode="light"] .landing-hero-compact .hero-title { background-image: linear-gradient(180deg, oklch(0.62 0.13 78) 0%, oklch(0.5 0.12 70) 55%, oklch(0.36 0.08 60) 100%); filter: drop-shadow(0 3px 8px oklch(0.6 0.12 75 / 30%)); }
html[data-color-mode="light"] .landing-hero-compact .hero-chip { color: oklch(0.48 0.12 70); background: color-mix(in oklch, var(--background) 85%, transparent); }
