/* Cart drawer: solid obsidian panel */
.cart-drawer { position: relative; display: flex; flex-direction: column; width: min(460px, 100%); max-height: min(88dvh, 820px); padding: 16px; border-radius: 22px; background: var(--card); color: var(--card-foreground); border: 1px solid color-mix(in oklab, var(--chart-3) 35%, var(--border)); box-shadow: 0 24px 60px -20px oklch(0 0 0 / 70%); overflow: hidden; }
