/* Fox Arena game HUD */
.arena-title { letter-spacing: .08em; background: linear-gradient(90deg, var(--chart-3), var(--primary), var(--chart-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.arena-hud { position: relative; display: flex; align-items: center; gap: 16px; padding: 18px; border-radius: 22px; overflow: hidden; border: 1px solid color-mix(in oklab, var(--chart-3) 45%, var(--border)); background: radial-gradient(circle at 15% 50%, color-mix(in oklab, var(--primary) 30%, transparent), transparent 60%), linear-gradient(135deg, var(--card), color-mix(in oklab, var(--chart-3) 10%, var(--card))); }
.arena-hud::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent 0 3px, color-mix(in oklab, var(--foreground) 3%, transparent) 3px 4px); pointer-events: none; }
.arena-hud-avatar { position: relative; flex-shrink: 0; }
.arena-lvl { position: absolute; bottom: -6px; left: 50%; transform: translateX(-50%); padding: 1px 8px; border-radius: 999px; font-size: 10px; font-weight: 900; background: var(--chart-3); color: var(--background); white-space: nowrap; }
