.arena-quest { position: relative; border: 1px solid color-mix(in oklab, var(--primary) 35%, var(--border)); border-radius: 18px; padding: 14px; background: linear-gradient(160deg, color-mix(in oklab, var(--primary) 12%, var(--card)), var(--card)); transition: transform .2s; }
.arena-quest:hover { transform: translateY(-2px); }
.arena-quest.is-done { opacity: .7; border-color: color-mix(in oklab, var(--chart-2) 40%, var(--border)); }
.arena-quest-icon { display: grid; place-items: center; flex-shrink: 0; width: 42px; height: 42px; border-radius: 12px; color: var(--chart-3); background: color-mix(in oklab, var(--chart-3) 15%, transparent); border: 1px solid color-mix(in oklab, var(--chart-3) 40%, transparent); }
.arena-reward { display: grid; justify-items: center; flex-shrink: 0; font-weight: 900; font-size: 16px; color: var(--chart-3); line-height: 1; }
.arena-reward small { font-size: 8px; letter-spacing: .15em; margin-top: 2px; }
.arena-option { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 12px; border: 1px solid var(--border); text-align: left; font-size: 12px; background: var(--muted); }
