@keyframes arena-pulse { 50% { box-shadow: 0 0 0 6px color-mix(in oklab, var(--primary) 0%, transparent), 0 0 18px color-mix(in oklab, var(--primary) 55%, transparent); } }
.arena-podium { display: grid; grid-template-columns: repeat(3, 1fr); align-items: end; gap: 8px; }
.arena-step { position: relative; display: grid; justify-items: center; gap: 4px; padding: 12px 6px 28px; border-radius: 16px 16px 6px 6px; border: 1px solid var(--border); background: var(--card); min-width: 0; }
.arena-step i { position: absolute; bottom: 6px; font-style: normal; font-weight: 900; font-size: 13px; }
