/* Home/Wallet/Stake polish */
.stake-metric{border-color:color-mix(in oklab,var(--chart-3) 28%,var(--border));background:linear-gradient(160deg,color-mix(in oklab,var(--card) 92%,transparent),color-mix(in oklab,var(--chart-3) 6%,var(--card)));transition:transform .2s ease}
.duration-package-card,.wallet-action-tile,.terminal-action{transition:transform .15s ease,box-shadow .2s ease}
.duration-package-card:active,.wallet-action-tile:active,.terminal-action:active{transform:scale(.98)}
