@keyframes bix-beacon{0%,100%{opacity:1}50%{opacity:.35}}
@media (prefers-reduced-motion:reduce){.terminal-live i{animation:none}}

/* Stake package layouts */
.stake-pills { display: flex; gap: .5rem; overflow-x: auto; padding-bottom: .25rem; scrollbar-width: none; }
.stake-pills::-webkit-scrollbar { display: none; }
.stake-pill { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; min-width: 4.25rem; padding: .45rem .7rem; border-radius: 999px; border: 1px solid var(--border); background: color-mix(in oklab, var(--card) 70%, transparent); font-size: .65rem; color: var(--muted-foreground); transition: all .2s; }
.stake-pill b { font-size: .8rem; color: var(--foreground); }
.stake-pill[aria-selected="true"] { border-color: var(--chart-3); background: color-mix(in oklab, var(--chart-3) 14%, var(--card)); color: var(--chart-3); }
.stake-capsules { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .5rem; }
@media (min-width: 768px) { .stake-capsules { grid-template-columns: repeat(8, minmax(0, 1fr)); } }
.stake-capsule { position: relative; display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 0; padding: .55rem .25rem; border-radius: 999px; border: 1px solid var(--border); background: linear-gradient(160deg, color-mix(in oklab, var(--card) 92%, transparent), color-mix(in oklab, var(--background) 85%, transparent)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 6%); font-size: .58rem; letter-spacing: .1em; color: var(--muted-foreground); transition: border-color .2s, transform .2s, background .2s; }
.stake-capsule b { font-size: .82rem; letter-spacing: 0; color: var(--foreground); white-space: nowrap; }
.stake-capsule:active { transform: scale(.96); }
.stake-capsule[aria-selected="true"] { border-color: var(--chart-3); background: linear-gradient(160deg, color-mix(in oklab, var(--chart-3) 18%, var(--card)), var(--card)); color: var(--chart-3); box-shadow: inset 0 1px 0 oklch(1 0 0 / 10%), 0 0 0 1px color-mix(in oklab, var(--chart-3) 30%, transparent); }
.stake-capsule[aria-selected="true"]::after { content: ""; position: absolute; bottom: 4px; width: 4px; height: 4px; border-radius: 50%; background: var(--chart-3); }
.stake-row { border: 1px solid var(--border); border-radius: 1rem; background: color-mix(in oklab, var(--card) 80%, transparent); overflow: hidden; }
.stake-row-head { display: flex; width: 100%; align-items: center; gap: .75rem; min-height: 3.4rem; padding: 0 1rem; }
.stake-row:has([aria-expanded="true"]) { border-color: color-mix(in oklab, var(--chart-3) 60%, var(--border)); }

/* Tier-1 minimal splash + dock */
.splash-emblem { gap: 18px; animation: splash-rise 520ms var(--ease) both; }
.splash-emblem img { box-shadow: 0 0 0 1px color-mix(in srgb, var(--splash-gold) 35%, transparent), 0 0 40px color-mix(in srgb, var(--splash-gold) 18%, transparent); }
.splash-word { font-size: 26px; font-weight: 800; letter-spacing: .42em; padding-left: .42em; background: linear-gradient(180deg, var(--splash-highlight), var(--splash-gold)); background-clip: text; color: transparent; }
.splash-sub { font-size: 9px; font-weight: 600; letter-spacing: .36em; padding-left: .36em; color: color-mix(in srgb, var(--splash-foreground) 55%, transparent); }
.app-splash--leaving .splash-emblem { transform: scale(1.04); transition: transform 180ms var(--ease); }
@keyframes splash-rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
.glass-dock { background: color-mix(in srgb, var(--card) 88%, transparent) !important; }
.glass-dock .mobile-nav-on { text-shadow: none !important; }
.glass-dock .mobile-nav-on::before { left: 32%; right: 32%; box-shadow: none; }
@media (prefers-reduced-motion: reduce) { .splash-emblem { animation: none; } }
.coin-stage { position: relative; margin: 1rem auto 0; display: grid; place-items: center; padding: 2rem 1rem 1.25rem; border-radius: 1.5rem; border: 1px solid color-mix(in oklab, var(--primary) 30%, transparent); background: radial-gradient(ellipse at 50% 35%, color-mix(in oklab, var(--primary) 14%, transparent), transparent 65%), linear-gradient(180deg, var(--card), var(--background)); overflow: hidden; perspective: 900px; }
.coin-halo { position: absolute; top: 18%; width: 260px; height: 260px; border-radius: 50%; background: radial-gradient(circle, color-mix(in oklab, var(--primary) 22%, transparent), transparent 70%); }
.coin-spin { position: relative; width: min(220px, 58vw); height: auto; animation: coin-rotate 7s linear infinite; transform-style: preserve-3d; filter: drop-shadow(0 18px 24px color-mix(in oklab, var(--background) 80%, transparent)); }
.coin-pedestal { width: min(260px, 70vw); height: 22px; margin-top: 1rem; border-radius: 50%; background: radial-gradient(ellipse, color-mix(in oklab, var(--primary) 35%, transparent), transparent 70%); border-top: 1px solid color-mix(in oklab, var(--primary) 45%, transparent); }
.coin-caption { margin-top: 1rem; display: grid; gap: .25rem; font-size: 10px; letter-spacing: .18em; text-transform: uppercase; }
.coin-caption span { color: var(--muted-foreground); }
.coin-caption strong { color: var(--primary); }
@keyframes coin-rotate { from { transform: rotateY(0deg); } to { transform: rotateY(360deg); } }
@media (prefers-reduced-motion: reduce) { .coin-spin { animation: none; } }
/* Official 3D coin showcase */
.coin-stage--lux { padding: 1.5rem 1rem 1.25rem; border-color: color-mix(in oklab, var(--chart-3) 35%, transparent); background: radial-gradient(ellipse at 50% 40%, color-mix(in oklab, var(--chart-3) 16%, transparent), transparent 62%), oklch(0.08 0.005 80); }
.coin-stage--lux .coin-halo { top: 14%; background: radial-gradient(circle, color-mix(in oklab, var(--chart-3) 30%, transparent), transparent 68%); animation: coin-halo-pulse 4.5s ease-in-out infinite; }
.coin-beam { position: absolute; top: -10%; left: 50%; width: 70%; height: 80%; transform: translateX(-50%); background: linear-gradient(180deg, color-mix(in oklab, var(--chart-3) 22%, transparent), transparent 80%); clip-path: polygon(40% 0, 60% 0, 100% 100%, 0 100%); filter: blur(14px); pointer-events: none; }
.coin-dust { position: absolute; inset: 0; pointer-events: none; }
.coin-dust i { position: absolute; bottom: 18%; width: 3px; height: 3px; border-radius: 50%; background: var(--chart-3); opacity: 0; animation: coin-dust-rise 7s linear infinite; }
.coin-float { position: relative; width: min(240px, 62vw); aspect-ratio: 1; border-radius: 50%; animation: coin-levitate 6s ease-in-out infinite; perspective: 900px; }
.coin-3d { width: 100%; height: 100%; object-fit: contain; mix-blend-mode: lighten; filter: drop-shadow(0 20px 30px oklch(0 0 0 / 60%)) saturate(1.08); }
.coin-sheen { position: absolute; inset: 8% 18%; border-radius: 50%; overflow: hidden; pointer-events: none; mix-blend-mode: screen; }
.coin-sheen::after { content: ''; position: absolute; top: -20%; left: -60%; width: 40%; height: 140%; transform: rotate(18deg); background: linear-gradient(90deg, transparent, oklch(1 0.05 90 / 55%), transparent); animation: coin-sheen-sweep 5s ease-in-out infinite; }
.coin-stage--lux .coin-pedestal { position: relative; margin-top: .25rem; background: radial-gradient(ellipse, color-mix(in oklab, var(--chart-3) 40%, transparent), transparent 70%); border-top-color: color-mix(in oklab, var(--chart-3) 55%, transparent); animation: coin-shadow 6s ease-in-out infinite; }
.coin-pedestal span { position: absolute; inset: -6px 15%; border-radius: 50%; border: 1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); animation: coin-ring 3s ease-out infinite; }
.coin-stage--lux .coin-caption strong { color: var(--chart-3); }
@keyframes coin-levitate { 0%,100% { transform: translateY(0) rotateY(-8deg) rotateZ(-1deg); } 50% { transform: translateY(-12px) rotateY(10deg) rotateZ(1deg); } }
@keyframes coin-shadow { 0%,100% { transform: scaleX(1); opacity: .9; } 50% { transform: scaleX(.82); opacity: .55; } }
@keyframes coin-sheen-sweep { 0%,55% { left: -60%; } 85%,100% { left: 130%; } }
@keyframes coin-halo-pulse { 0%,100% { opacity: .7; transform: scale(1); } 50% { opacity: 1; transform: scale(1.08); } }
@keyframes coin-ring { from { transform: scale(.7); opacity: .9; } to { transform: scale(1.25); opacity: 0; } }
@keyframes coin-dust-rise { 0% { transform: translateY(0); opacity: 0; } 15% { opacity: .8; } 100% { transform: translateY(-220px); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .coin-float, .coin-sheen::after, .coin-dust i, .coin-pedestal span, .coin-stage--lux .coin-halo, .coin-stage--lux .coin-pedestal { animation: none; } }

/* Member pass cards ($10–$10,000 packages): bank-card ratio, never cropped. */
.pass-mini { display:grid; grid-template-columns:112px minmax(0,1fr); align-items:center; gap:12px; width:100%; margin-top:12px; padding:8px; border:1px solid var(--border); border-radius:10px; background:color-mix(in oklab,var(--card) 80%,transparent); text-align:left; }
