.studio-lion { --zoom-hi: oklch(0.96 0.06 92); --zoom-mid: oklch(0.82 0.14 82); --zoom-lo: oklch(0.58 0.11 68); filter: drop-shadow(0 0 14px color-mix(in oklab, var(--zoom-mid) 55%, transparent)); }

/* Rail dots + ecosystem rail */
.rail-dots { display:flex; justify-content:center; gap:6px; margin-top:10px; }
