.eco-card { --tone: var(--chart-3); position:relative; flex:0 0 min(62%, 220px); scroll-snap-align:start; display:flex; flex-direction:column; gap:4px; padding:16px 14px 14px; border-radius:18px; border:1px solid color-mix(in oklab, var(--tone) 40%, transparent); background: radial-gradient(120% 90% at 0% 0%, color-mix(in oklab, var(--tone) 22%, transparent), transparent 60%), linear-gradient(160deg, color-mix(in oklab, var(--card) 92%, transparent), color-mix(in oklab, var(--background) 96%, transparent)); box-shadow: inset 0 1px 0 color-mix(in oklab, var(--tone) 30%, transparent), 0 10px 24px -14px color-mix(in oklab, var(--tone) 60%, transparent); overflow:hidden; transition: transform .3s ease; }
.eco-card::after { content:""; position:absolute; inset:auto -30% -60% auto; width:120px; height:120px; border-radius:50%; border:1px solid color-mix(in oklab, var(--tone) 30%, transparent); }
.eco-card:active { transform: scale(.97); }
.eco-card b { font-family:"Cinzel", var(--font-display); font-size:14px; letter-spacing:.06em; color: var(--foreground); }
.eco-card em { font-style:normal; font-size:11px; color: var(--muted-foreground); }
.eco-icon { display:grid; place-items:center; width:38px; height:38px; border-radius:12px; color: var(--tone); background: color-mix(in oklab, var(--tone) 14%, transparent); border:1px solid color-mix(in oklab, var(--tone) 35%, transparent); margin-bottom:6px; }
.eco-badge { align-self:flex-start; margin-top:8px; font-style:normal; font-size:9px; font-weight:800; letter-spacing:.14em; padding:3px 8px; border-radius:999px; color: var(--muted-foreground); border:1px dashed color-mix(in oklab, var(--tone) 50%, transparent); }
.eco-badge.is-live { color: var(--chart-2); border-style:solid; border-color: color-mix(in oklab, var(--chart-2) 45%, transparent); }
.eco-card.is-soon { opacity:.88; }
.eco-gold { --tone: var(--chart-3); } .eco-emerald { --tone: var(--chart-2); } .eco-violet { --tone: oklch(0.68 0.2 305); } .eco-cyan { --tone: oklch(0.78 0.13 210); } .eco-crimson { --tone: oklch(0.65 0.2 20); }
/* Hero: lower BIXLINK so fox head stays visible */
