@keyframes coin-sovereign-glow { 0%,100% { filter:drop-shadow(0 0 16px color-mix(in oklab,var(--chart-3) 45%,transparent)) saturate(1.1) contrast(1.05) brightness(1); } 50% { filter:drop-shadow(0 0 30px color-mix(in oklab,var(--chart-3) 70%,transparent)) saturate(1.18) contrast(1.08) brightness(1.07); } }
.coin-stage--vault .coin-float::before { content:""; position:absolute; left:50%; bottom:-6%; width:70%; height:14%; translate:-50% 0; border-radius:50%; background:radial-gradient(ellipse,color-mix(in oklab,var(--chart-3) 55%,transparent),transparent 70%); filter:blur(6px); animation:coin-gasing-shadow 6s ease-in-out infinite; pointer-events:none; }
