.q-orbit { border: 1px solid color-mix(in oklab, var(--q-violet) 50%, transparent); color: var(--q-gold); }
.q-seat { background: linear-gradient(90deg, var(--q-gold), var(--q-violet)); color: var(--primary-foreground); }
