:root {
  --loan-surface: oklch(1 0 0);
  --loan-ink: oklch(.16 .02 270);
  --loan-muted: oklch(.42 .02 270);
  --loan-gold: oklch(.62 .14 75);
  --loan-violet: oklch(.62 .22 300);
  --loan-edge: oklch(.85 .05 85);
  --loan-scrim: oklch(.08 .02 270 / 80%);
  --loan-shadow: 0 0 0 1px oklch(.84 .14 85 / 60%), 0 0 40px oklch(.62 .22 300 / 35%), 0 28px 80px oklch(0 0 0 / 60%);
}
.loan-dialog-overlay { position:fixed; inset:0; z-index:400; background:var(--loan-scrim); backdrop-filter:blur(12px); }
.loan-dialog-content {
  --background:var(--loan-surface); --card:var(--loan-surface);
  --foreground:var(--loan-ink); --muted-foreground:var(--loan-muted);
  --chart-3:var(--loan-gold); --border:var(--loan-edge);
  --accent:var(--loan-edge); --accent-foreground:var(--loan-ink);
  position:fixed; left:50%; top:50%; transform:translate(-50%,-50%);
  z-index:401; isolation:isolate; box-sizing:border-box;
  width:min(400px,calc(100vw - 24px)); max-height:calc(100dvh - 24px);
  margin:0; padding:24px 18px 22px; overflow-y:auto; overscroll-behavior:contain;
  background:var(--loan-surface); color:var(--loan-ink); opacity:1;
  border:1px solid var(--loan-edge); border-radius:14px;
  background-image:linear-gradient(160deg,oklch(.99 .02 85) 0%,var(--loan-surface) 40%,oklch(.98 .015 300) 100%);
  box-shadow:var(--loan-shadow),inset 0 1px 0 var(--loan-gold);
  font-size:12px; line-height:1.6; letter-spacing:0;
}
.loan-dialog-content :is(h3,p,li,span,b) { overflow-wrap:break-word; letter-spacing:0; }
