.install-pop-backdrop{position:fixed;inset:0;z-index:80;display:grid;place-items:center;padding:20px;background:radial-gradient(120% 80% at 50% -10%,rgba(168,85,247,.18),transparent 58%),radial-gradient(110% 80% at 50% 110%,rgba(45,212,191,.16),transparent 60%),rgba(2,4,7,.82);backdrop-filter:blur(12px) saturate(125%);animation:ip-fade .3s ease}
.install-pop{position:relative;overflow:hidden;width:100%;max-width:344px;padding:28px 22px 22px;border-radius:26px;text-align:center;color:#f8fafc;background:linear-gradient(165deg,#0b1017 0%,#05070b 46%,#061010 100%);border:1px solid rgba(255,215,0,.30);box-shadow:0 0 0 1px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.07),0 0 38px -8px rgba(255,215,0,.28),0 0 60px -22px rgba(168,85,247,.5),0 28px 64px -20px rgba(0,0,0,.9);animation:ip-up .45s cubic-bezier(.2,.9,.3,1.2)}
.install-pop::before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;background:radial-gradient(330px 210px at 92% -10%,rgba(255,215,0,.22),transparent 62%),radial-gradient(300px 230px at -14% 110%,rgba(45,212,191,.2),transparent 60%),radial-gradient(250px 190px at 4% 34%,rgba(168,85,247,.18),transparent 64%)}
.install-pop::after{content:"";position:absolute;top:0;left:-60%;z-index:0;width:45%;height:100%;pointer-events:none;background:linear-gradient(100deg,transparent,rgba(255,255,255,.1),transparent);transform:skewX(-18deg);animation:ip-sheen 5s ease-in-out infinite}
.install-pop > :not(.install-pop-close){position:relative;z-index:1}
.install-pop-close{position:absolute;right:14px;top:14px;z-index:2;display:grid;place-items:center;width:36px;height:36px;border-radius:50%;color:#e8eef7;border:1px solid rgba(255,215,0,.4);background:rgba(0,0,0,.5);backdrop-filter:blur(4px);transition:color .2s,border-color .2s,box-shadow .2s}
.install-pop-close:hover{color:#fff;border-color:rgba(45,212,191,.55);box-shadow:0 0 16px -4px rgba(45,212,191,.6)}
.install-pop-avatar{position:relative;width:92px;height:92px;margin:0 auto;border-radius:50%;padding:5px;background:#05070b;box-shadow:0 0 0 1px rgba(255,215,0,.35),0 0 28px -4px rgba(255,215,0,.4),0 0 46px -14px rgba(168,85,247,.6),0 0 42px -16px rgba(45,212,191,.5)}
.install-pop-avatar::before{content:"";position:absolute;inset:-1px;z-index:0;border-radius:50%;background:conic-gradient(from 0deg,#FFD700,#A855F7 34%,#2DD4BF 68%,#FFD700);animation:ip-spin 9s linear infinite}
.install-pop-avatar img{position:relative;z-index:1;width:100%;height:100%;border-radius:50%;object-fit:cover;border:2px solid #05070b}
.install-pop h2{margin-top:16px;font-size:24px;line-height:1.2;font-weight:900;letter-spacing:.01em;color:#fff;text-shadow:0 0 24px rgba(255,215,0,.22)}
.install-pop h2 em{font-style:normal;color:#FFD700;text-shadow:0 0 20px rgba(255,215,0,.5)}
.install-pop p{margin-top:10px;font-size:14px;line-height:1.55;color:#dbe3ee}
.install-pop p b{color:#FFD700;font-weight:800;text-shadow:0 0 14px rgba(255,215,0,.35)}
