.install-pop-cta{margin-top:20px;width:100%;min-height:52px;border:0;border-radius:999px;font-weight:900;letter-spacing:.06em;color:#100a02;background:linear-gradient(135deg,#fff6c2 0%,#FFD700 36%,#d99a12 68%,#FFD700 100%);box-shadow:0 10px 30px -8px rgba(255,215,0,.62),0 0 0 1px rgba(255,215,0,.5),0 0 28px -6px rgba(168,85,247,.45),0 0 28px -8px rgba(45,212,191,.42);transition:filter .2s,transform .12s}
.install-pop-cta:hover{filter:brightness(1.07)}
.install-pop-cta:active{transform:scale(.97)}
.install-pop-line{display:block;width:52%;height:3px;margin:16px auto 0;border-radius:3px;background:linear-gradient(90deg,transparent,#A855F7 22%,#FFD700 50%,#2DD4BF 78%,transparent);box-shadow:0 0 14px -2px rgba(255,215,0,.55)}
@keyframes ip-fade{from{opacity:0}}
@keyframes ip-up{from{opacity:0;transform:translateY(24px) scale(.94)}}
@keyframes ip-spin{to{transform:rotate(360deg)}}
@keyframes ip-sheen{0%,62%{left:-60%}100%{left:120%}}
@media (prefers-reduced-motion:reduce){.install-pop,.install-pop-backdrop,.install-pop::after,.install-pop-avatar::before{animation:none}}

