/* BIXTOK — full-screen vertical video + LIVE, obsidian/matcha/orange */
.bixtok { position: fixed; inset: 0; z-index: 60; background: var(--background); color: var(--foreground); overflow: hidden; }
.bixtok-skeleton { position: absolute; inset: 0; background: var(--muted); animation: pulse 1.6s infinite; }
.bixtok-top { position: absolute; inset: 0 0 auto; z-index: 5; display: flex; align-items: center; justify-content: space-between; gap: .5rem; padding: max(.6rem, env(safe-area-inset-top)) .75rem .6rem; background: linear-gradient(to bottom, color-mix(in oklab, var(--background) 80%, transparent), transparent); }
.bixtok-icon { display: grid; place-items: center; width: 2.25rem; height: 2.25rem; border-radius: 999px; background: color-mix(in oklab, var(--background) 55%, transparent); border: 1px solid color-mix(in oklab, var(--foreground) 14%, transparent); }
.bixtok-tabs { display: flex; gap: 1rem; overflow-x: auto; scrollbar-width: none; }
.bixtok-tabs button { position: relative; display: flex; align-items: center; gap: .3rem; font-size: .9rem; font-weight: 700; color: color-mix(in oklab, var(--foreground) 60%, transparent); padding-bottom: .3rem; white-space: nowrap; }
.bixtok-tabs button.on { color: var(--foreground); }
.bixtok-tabs button.on::after { content: ''; position: absolute; left: 25%; right: 25%; bottom: 0; height: 2px; border-radius: 2px; background: var(--matcha-gloss, var(--primary)); }
.bixtok-dot { width: .45rem; height: .45rem; border-radius: 999px; background: var(--orange-gloss, var(--destructive)); }
.bixtok-feed { height: 100%; overflow-y: auto; scroll-snap-type: y mandatory; scrollbar-width: none; }
.bixtok-slide { position: relative; height: 100dvh; scroll-snap-align: start; scroll-snap-stop: always; background: var(--card); }
.bixtok-video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.bixtok-video.mirror { transform: scaleX(-1); }
.bixtok-meta { position: absolute; left: 1rem; right: 5rem; bottom: calc(1.5rem + env(safe-area-inset-bottom)); z-index: 2; text-shadow: 0 1px 6px color-mix(in oklab, var(--background) 80%, transparent); }
.bixtok-meta p { font-size: .85rem; margin-top: .25rem; }
.bixtok-rail { position: absolute; right: .75rem; bottom: calc(2rem + env(safe-area-inset-bottom)); z-index: 2; display: flex; flex-direction: column; gap: 1.1rem; }
.bixtok-rail button { display: flex; flex-direction: column; align-items: center; gap: .2rem; }
.bixtok-rail button svg { width: 2.6rem; height: 2.6rem; padding: .6rem; border-radius: 999px; background: color-mix(in oklab, var(--background) 50%, transparent); border: 1px solid color-mix(in oklab, var(--foreground) 15%, transparent); }
.bixtok-rail button.on svg { color: var(--orange-gloss, var(--destructive)); fill: currentColor; }
.bixtok-rail button.gift svg { color: var(--background); background: var(--matcha-gloss, var(--primary)); border-color: transparent; }
.bixtok-rail small { font-size: .65rem; font-weight: 700; }
.bixtok-lobby { height: 100%; overflow-y: auto; padding: 4.5rem 1rem 2rem; }
.bixtok-golive { border: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent); border-radius: 1rem; padding: 1rem; background: var(--card); }
.bixtok-golive h2 { display: flex; align-items: center; gap: .4rem; font-weight: 800; margin-bottom: .6rem; }
.bixtok-golive form { display: grid; gap: .6rem; }
.bixtok-cta { border-radius: 999px; padding: .65rem 1.2rem; font-weight: 800; font-size: .85rem; text-align: center; color: var(--background); background: var(--matcha-gloss, var(--primary)); }
.bixtok-cta:disabled { opacity: .6; }
.bixtok-live-grid { display: grid; grid-template-columns: 1fr 1fr; gap: .6rem; margin-top: .6rem; }
.bixtok-live-grid button { display: flex; flex-direction: column; align-items: flex-start; gap: .3rem; text-align: left; aspect-ratio: 3/4; padding: .7rem; border-radius: .9rem; background: linear-gradient(160deg, var(--card), var(--muted)); border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent); }
.bixtok-live-grid b { margin-top: auto; font-size: .85rem; }
.bixtok-live-grid small { font-size: .7rem; color: var(--muted-foreground); }
.bixtok-badge { font-size: .6rem; font-weight: 900; letter-spacing: .08em; padding: .15rem .45rem; border-radius: .3rem; color: var(--background); background: var(--orange-gloss, var(--destructive)); }
.bixtok-room { position: fixed; inset: 0; z-index: 70; background: var(--background); }
.bixtok-room-bg { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: .5rem; color: var(--muted-foreground); background: radial-gradient(circle at 50% 35%, color-mix(in oklab, var(--primary) 18%, var(--background)), var(--background)); }
.bixtok-room-top { position: absolute; inset: 0 0 auto; z-index: 3; display: flex; align-items: center; gap: .5rem; padding: max(.7rem, env(safe-area-inset-top)) .75rem .6rem; }
.bixtok-room-top b { flex: 1; min-width: 0; font-size: .9rem; }
.bixtok-end { border-radius: 999px; padding: .3rem .8rem; font-size: .75rem; font-weight: 800; background: var(--destructive); color: var(--destructive-foreground); }
.bixtok-ended { position: absolute; top: 40%; inset-inline: 0; text-align: center; font-weight: 800; z-index: 3; }
.bixtok-chat { position: absolute; left: .75rem; right: 4rem; bottom: calc(4.5rem + env(safe-area-inset-bottom)); z-index: 3; max-height: 40%; overflow-y: auto; display: flex; flex-direction: column; gap: .3rem; mask-image: linear-gradient(to bottom, transparent, #000 25%); }
.bixtok-chat p { align-self: flex-start; font-size: .8rem; padding: .3rem .6rem; border-radius: .8rem; background: color-mix(in oklab, var(--background) 55%, transparent); }
.bixtok-chat p b { color: var(--matcha-gloss, var(--primary)); margin-right: .25rem; }
.bixtok-chat p.gift { background: color-mix(in oklab, var(--orange-gloss, var(--accent)) 30%, var(--background)); }
.bixtok-room-bar { position: absolute; inset: auto 0 0; z-index: 3; display: flex; gap: .5rem; padding: .6rem .75rem calc(.7rem + env(safe-area-inset-bottom)); }
.bixtok-input { display: flex; align-items: center; gap: .4rem; border-radius: 999px; padding: .45rem .8rem; background: color-mix(in oklab, var(--background) 60%, transparent); border: 1px solid color-mix(in oklab, var(--foreground) 14%, transparent); }
.bixtok-input input { flex: 1; min-width: 0; background: transparent; outline: none; font-size: .85rem; }
.bixtok-giftbtn { display: grid; place-items: center; width: 2.6rem; height: 2.6rem; border-radius: 999px; color: var(--background); background: var(--matcha-gloss, var(--primary)); }
.bixtok-hint { position: absolute; top: 3.6rem; inset-inline: 1rem; z-index: 3; font-size: .65rem; color: var(--muted-foreground); text-align: center; }
.bixtok-sheet-wrap { position: fixed; inset: 0; z-index: 100; display: flex; align-items: flex-end; background: color-mix(in oklab, var(--background) 50%, transparent); }
.bixtok-sheet { position: relative; width: 100%; max-width: 32rem; margin: 0 auto; padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom)); border-radius: 1.2rem 1.2rem 0 0; background: var(--card); border-top: 1px solid color-mix(in oklab, var(--foreground) 12%, transparent); }
.bixtok-gifts { display: grid; grid-template-columns: repeat(4, 1fr); gap: .5rem; margin-top: .8rem; }
.bixtok-gifts button { display: flex; flex-direction: column; align-items: center; gap: .15rem; padding: .6rem .2rem; border-radius: .8rem; border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent); background: var(--background); }
.bixtok-gifts button:disabled { opacity: .5; }
.bixtok-gifts span { font-size: 1.7rem; }
.bixtok-gifts b { font-size: .65rem; text-align: center; }
.bixtok-gifts small { font-size: .6rem; color: var(--matcha-gloss, var(--primary)); font-weight: 700; }
.bixtok-burst { position: absolute; left: 50%; top: -3rem; font-size: 4rem; transform: translateX(-50%); animation: bixtok-burst 1.4s ease-out forwards; pointer-events: none; }
@keyframes bixtok-burst { 0% { opacity: 0; transform: translate(-50%, 1rem) scale(.6); } 30% { opacity: 1; transform: translate(-50%, -2rem) scale(1.3); } 100% { opacity: 0; transform: translate(-50%, -8rem) scale(1); } }
.bixtok-toast { position: fixed; left: 50%; bottom: 6rem; z-index: 90; transform: translateX(-50%); padding: .5rem 1rem; border-radius: 999px; font-size: .8rem; font-weight: 700; background: var(--card); border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent); max-width: 90vw; text-align: center; }
.bxl-camerr { position: absolute; left: 50%; top: 42%; z-index: 25; transform: translate(-50%, -50%); width: min(20rem, 80vw); display: grid; gap: .5rem; padding: 1rem; border-radius: 1rem; text-align: center; background: var(--card); color: var(--card-foreground); border: 1px solid color-mix(in oklab, var(--primary) 45%, transparent); box-shadow: 0 12px 40px color-mix(in oklab, var(--background) 70%, transparent); }
.bxl-camerr strong { font-size: .95rem; }
.bxl-camerr p { margin: 0; font-size: .78rem; line-height: 1.4; color: var(--muted-foreground); }
.bxl-camerr button { justify-self: center; padding: .5rem 1.25rem; border-radius: 999px; font-weight: 700; font-size: .85rem; background: var(--primary); color: var(--primary-foreground); }
@media (prefers-reduced-motion: reduce) { .bixtok-burst { animation: none; opacity: 0; } }

/* BIXTOK Studio */
.bixtok-create { position: fixed; right: 1rem; bottom: 6.5rem; z-index: 60; width: 3.4rem; height: 3.4rem; border-radius: 1.1rem; display: grid; place-items: center; color: var(--primary-foreground); background: linear-gradient(135deg, var(--primary), color-mix(in oklab, var(--primary) 55%, #f97316)); box-shadow: 0 8px 24px -8px var(--primary); }
.bixtok-studio { position: fixed; inset: 0; z-index: 95; background: #000; color: #fff; display: flex; flex-direction: column; overflow-y: auto; }
.studio-stage { position: absolute; inset: 0; }
.studio-stage video, .studio-preview video, .studio-preview img { width: 100%; height: 100%; object-fit: cover; }
.studio-stage video.mirror { transform: scaleX(-1); }
.studio-camerr { display: grid; place-items: center; height: 100%; padding: 2rem; text-align: center; font-size: .85rem; opacity: .8; }
.studio-overlay { position: absolute; left: 50%; top: 30%; transform: translateX(-50%); z-index: 3; font-weight: 900; font-size: 1.5rem; text-align: center; color: #fff; text-shadow: 0 2px 8px rgba(0,0,0,.7); pointer-events: none; max-width: 90%; }
.studio-count { position: absolute; inset: 0; display: grid; place-items: center; font-size: 6rem; font-weight: 900; z-index: 4; }
.studio-rec { position: absolute; top: 1rem; left: 50%; transform: translateX(-50%); z-index: 4; background: #e11d48; padding: .2rem .7rem; border-radius: 999px; font-size: .75rem; font-weight: 800; }
.studio-top { position: relative; z-index: 5; display: flex; justify-content: space-between; align-items: center; padding: .9rem; }
.studio-top button { width: 2.4rem; height: 2.4rem; display: grid; place-items: center; border-radius: 999px; background: rgba(0,0,0,.45); }
.studio-tools { position: absolute; right: .7rem; top: 4rem; z-index: 5; display: flex; flex-direction: column; gap: .9rem; }
.studio-tools button, .studio-side { display: flex; flex-direction: column; align-items: center; gap: .15rem; font-size: .62rem; text-shadow: 0 1px 4px #000; }
.studio-bottom { position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; padding: .8rem .8rem 1.4rem; background: linear-gradient(transparent, rgba(0,0,0,.85)); display: grid; gap: .6rem; }
.studio-beauty { display: flex; align-items: center; gap: .5rem; font-size: .72rem; font-weight: 700; }
.studio-beauty input { flex: 1; accent-color: var(--primary); }
.studio-filters { display: flex; gap: .55rem; overflow-x: auto; scrollbar-width: none; padding: .1rem; }
.studio-filters button { flex: none; display: flex; flex-direction: column; align-items: center; gap: .2rem; font-size: .6rem; opacity: .75; }
.studio-filters button.on { opacity: 1; color: var(--primary); }
.studio-filters i { width: 2.6rem; height: 2.6rem; border-radius: .7rem; background: linear-gradient(135deg, #f3c9a8, #8a5a3c 55%, #2b3a2f); border: 2px solid transparent; }
.studio-filters button.on i { border-color: var(--primary); }
.studio-durs { display: flex; justify-content: center; gap: .4rem; }
.studio-durs button { padding: .2rem .8rem; border-radius: 999px; font-size: .72rem; font-weight: 700; background: rgba(255,255,255,.12); }
.studio-durs button.on { background: #fff; color: #000; }
.studio-shutter { display: flex; justify-content: space-around; align-items: center; }
.studio-rec-btn { width: 4.4rem; height: 4.4rem; border-radius: 999px; border: 5px solid #fff; background: #e11d48; transition: border-radius .2s, transform .2s; }
.studio-rec-btn.on { border-radius: 1rem; transform: scale(.85); }
.studio-rec-btn:disabled { opacity: .4; }
.studio-err { color: #fda4af; font-size: .75rem; text-align: center; }
.studio-edit { display: grid; gap: .7rem; padding: 0 1rem 2rem; }
.studio-edit .studio-top { padding: .9rem 0; }
.studio-preview { position: relative; height: 52vh; border-radius: 1rem; overflow: hidden; background: #111; }
.studio-edit .form-input { width: 100%; }
.studio-tags { display: flex; flex-wrap: wrap; gap: .35rem; }
.studio-tags button { font-size: .7rem; padding: .2rem .6rem; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--primary) 50%, transparent); color: var(--primary); }
.studio-switch { display: flex; gap: .5rem; align-items: center; font-size: .8rem; }
.bixtok-slide { position: relative; }
.bixtok-create { right: auto !important; left: 50%; transform: translateX(-50%); bottom: calc(1rem + env(safe-area-inset-bottom)) !important; width: 3.6rem !important; height: 2.4rem !important; border-radius: .8rem !important; background: var(--foreground) !important; color: var(--background) !important; box-shadow: -4px 0 0 var(--matcha-gloss, var(--primary)), 4px 0 0 var(--orange-gloss, var(--accent)) !important; }
.bixtok-meta { bottom: calc(4.5rem + env(safe-area-inset-bottom)) !important; }
.bixtok-rail { bottom: calc(4.5rem + env(safe-area-inset-bottom)) !important; }
.bixtok-brand { position: absolute; top: calc(max(.6rem, env(safe-area-inset-top)) + 2.9rem); left: .9rem; z-index: 5; display: flex; align-items: center; gap: .35rem; pointer-events: none; }
.bixtok-brand b { font-weight: 900; letter-spacing: .04em; font-size: .95rem; }
.bixtok-brand b span { color: var(--orange-gloss, var(--accent)); }

/* BIXTOK TikTok-style shell */
.bixtok-create{display:none!important}
.bxt-nav{position:absolute;inset:auto 0 0;z-index:20;display:grid;grid-template-columns:repeat(5,1fr);align-items:center;padding:.4rem .4rem calc(.4rem + env(safe-area-inset-bottom));background:color-mix(in oklab,var(--background) 92%,transparent);border-top:1px solid var(--border);backdrop-filter:blur(12px)}
.bxt-nav>*{position:relative;display:flex;flex-direction:column;align-items:center;gap:.1rem;color:var(--muted-foreground);font-size:.62rem;font-weight:700}
.bxt-nav>* svg{width:22px;height:22px}.bxt-nav .on{color:var(--foreground)}
.bxt-plus{justify-self:center;width:3.2rem;height:2.1rem;border-radius:.7rem;display:grid!important;place-items:center;background:var(--foreground);color:var(--background)!important;box-shadow:-4px 0 0 var(--matcha-gloss,var(--primary)),4px 0 0 var(--orange-gloss,var(--accent))}
.bxt-badge{position:absolute;top:-4px;right:22%;min-width:16px;height:16px;border-radius:9px;background:var(--orange-gloss,var(--accent));color:var(--background);font-size:.6rem;font-style:normal;display:grid;place-items:center;padding:0 3px}
.bxt-page{height:100%;overflow-y:auto;padding:max(.6rem,env(safe-area-inset-top)) 1rem 6rem}
.bxt-head{display:grid;grid-template-columns:2.5rem 1fr 2.5rem;align-items:center;min-height:2.8rem}.bxt-head h1{text-align:center;font-weight:900;font-size:1.1rem;display:flex;justify-content:center;align-items:center;gap:.4rem}
.bxt-head>:last-child{justify-self:end}.bxt-online{width:8px;height:8px;border-radius:50%;background:var(--matcha-gloss,var(--primary))}
.bxt-stories{display:flex;gap:1rem;overflow-x:auto;padding:1rem 0;scrollbar-width:none}.bxt-stories button{display:flex;flex-direction:column;align-items:center;gap:.35rem;font-size:.72rem;font-weight:700;min-width:4.4rem}
.bxt-av{position:relative;width:4.2rem;height:4.2rem;border-radius:50%;display:grid;place-items:center;background:var(--muted);font-weight:900;font-size:1.3rem}
.bxt-av.ring{box-shadow:0 0 0 2px var(--background),0 0 0 4px var(--matcha-gloss,var(--primary))}.bxt-av em{position:absolute;bottom:-6px;font-size:.55rem;font-style:normal;background:var(--orange-gloss,var(--accent));color:var(--background);padding:0 .35rem;border-radius:4px}
.bxt-list li,.bxt-list li>a{display:flex;align-items:center;gap:.8rem;padding:.65rem 0}.bxt-list div{flex:1;min-width:0}.bxt-list b{font-size:.92rem}.bxt-list p{font-size:.78rem;color:var(--muted-foreground);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bxt-ic{width:3.2rem;height:3.2rem;border-radius:50%;display:grid;place-items:center;flex:none}.bxt-ic.pink{background:#ec4899;color:#fff}.bxt-ic.dark{background:var(--muted)}.bxt-ic.orange{background:var(--orange-gloss,var(--accent));color:var(--background)}.bxt-ic.matcha{background:var(--matcha-gloss,var(--primary));color:var(--background)}
.bxt-count{background:#ef4444;color:#fff;font-style:normal;font-size:.7rem;font-weight:800;border-radius:9px;padding:0 .4rem}
.bxt-prof{display:flex;justify-content:space-between;gap:1rem;padding-top:.5rem}.bxt-prof h1{font-size:1.6rem;font-weight:900;line-height:1.1}.bxt-prof small{color:var(--muted-foreground)}
.bxt-stats{display:flex;gap:1.2rem;margin-top:.8rem}.bxt-stats p{font-size:.72rem;color:var(--muted-foreground);display:flex;flex-direction:column}.bxt-stats b{font-size:1.1rem;color:var(--foreground)}
.bxt-bigav{position:relative;flex:none;width:5.6rem;height:5.6rem;border-radius:50%;background:var(--muted);font-size:2rem;font-weight:900;border:2px solid var(--matcha-gloss,var(--primary))}.bxt-bigav em{position:absolute;right:0;bottom:0;width:1.6rem;height:1.6rem;border-radius:50%;display:grid;place-items:center;background:var(--orange-gloss,var(--accent));color:var(--background)}
.bxt-bio{margin:.8rem 0 .5rem;font-size:.85rem}.bxt-pill{display:inline-flex;gap:.4rem;align-items:center;border:1px solid var(--border);border-radius:999px;padding:.35rem .8rem;font-size:.8rem;font-weight:700}
.bxt-ptabs{display:grid;grid-template-columns:repeat(5,1fr);margin:1rem -1rem 0;border-bottom:1px solid var(--border)}.bxt-ptabs button{display:grid;place-items:center;padding:.6rem;color:var(--muted-foreground)}.bxt-ptabs .on{color:var(--foreground);box-shadow:inset 0 -2px 0 var(--foreground)}
.bxt-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;margin:0 -1rem}.bxt-grid button{position:relative;aspect-ratio:3/4;background:var(--muted);overflow:hidden}.bxt-grid img,.bxt-grid video{width:100%;height:100%;object-fit:cover}.bxt-grid small{position:absolute;left:.3rem;bottom:.2rem;display:flex;gap:.2rem;align-items:center;font-weight:800;font-size:.72rem;color:#fff;text-shadow:0 1px 3px #000}
.bxt-drawer-wrap{position:absolute;inset:0;z-index:40;background:color-mix(in oklab,var(--background) 40%,transparent)}.bxt-drawer{position:absolute;inset:0 0 0 18%;background:var(--card);padding:max(1rem,env(safe-area-inset-top)) 1.2rem;overflow-y:auto;animation:bxtIn .22s ease-out}
@keyframes bxtIn{from{transform:translateX(100%)}}
.bxt-drawer h4{font-size:.75rem;color:var(--muted-foreground);font-weight:700;margin:1rem 0 .3rem}.bxt-drawer>button,.bxt-drawer>a{display:flex;width:100%;align-items:center;gap:.8rem;padding:.75rem 0;font-weight:800}.bxt-drawer>*>svg:last-child{margin-left:auto;width:16px;color:var(--muted-foreground)}.bxt-drawer hr{border-color:var(--border);margin:.5rem 0}
.bxt-bal{background:radial-gradient(ellipse at top,color-mix(in oklab,var(--matcha-gloss,var(--primary)) 18%,transparent),transparent 60%)}.bxt-safe{display:flex;justify-content:center;gap:.2rem;align-items:center;color:var(--matcha-gloss,var(--primary))}
.bxt-est{margin-top:1.5rem;text-align:center;color:var(--muted-foreground);display:flex;justify-content:center;gap:.4rem;align-items:center}.bxt-amt{text-align:center;font-size:2.6rem;font-weight:900}
.bxt-coins{display:grid;grid-template-columns:1.6fr 1fr;gap:.6rem;margin:1rem 0}.bxt-coins a{border:1px solid var(--border);background:var(--card);border-radius:1rem;padding:.8rem;display:flex;flex-direction:column;gap:.2rem}.bxt-coins span{display:flex;gap:.3rem;align-items:center;font-size:.8rem;color:var(--muted-foreground)}.bxt-coins em{font-style:normal;font-size:.75rem;color:var(--orange-gloss,var(--accent));font-weight:800}
.bxt-card{display:flex;justify-content:space-between;align-items:center;background:var(--card);border:1px solid var(--border);border-radius:1rem;padding:1rem;margin-bottom:.6rem}.bxt-card p,.bxt-card span{font-size:.78rem;color:var(--muted-foreground);display:flex;align-items:center}.bxt-gifticon{width:2.6rem;height:2.6rem;color:var(--orange-gloss,var(--accent))}
.bxt-tools{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem .5rem;background:var(--card);border:1px solid var(--border);border-radius:1rem;padding:1.1rem .5rem}.bxt-tools>*{display:flex;flex-direction:column;align-items:center;gap:.4rem;font-size:.78rem;font-weight:700;text-align:center}.bxt-tools span{width:2.7rem;height:2.7rem;border-radius:.8rem;display:grid;place-items:center;background:var(--muted)}
.bxt-disc{margin-top:1.2rem;text-align:center;font-size:.68rem;color:var(--muted-foreground)}

/* BIXTOK links studio */
.bixtok-studio { height: 100dvh; }
.studio-stage { position: fixed; inset: 0; height: 100dvh; width: 100vw; }
.studio-stage video, .studio-stage img { width: 100%; height: 100%; object-fit: cover; }
.studio-overlay.drag { pointer-events: auto; cursor: grab; touch-action: none; outline: 1px dashed rgba(255,255,255,.5); outline-offset: 4px; }
.studio-overlay { transform: translate(-50%, -50%); white-space: pre-wrap; }
.studio-music-pill { display: inline-flex; align-items: center; gap: .35rem; padding: .35rem .8rem; border-radius: 999px; background: rgba(0,0,0,.5); font-size: .72rem; font-weight: 700; border: 1px solid rgba(255,255,255,.18); }
.studio-links { display: grid; gap: .45rem; }
.studio-link-row { display: flex; align-items: center; gap: .45rem; }
.studio-link-row > span { width: 1.5rem; height: 1.5rem; flex: none; display: grid; place-items: center; border-radius: 999px; font-size: .7rem; font-weight: 800; background: color-mix(in oklab, var(--primary) 30%, transparent); }
.studio-link-row button:disabled { opacity: .3; }
.studio-ghost { padding: .5rem .9rem; border-radius: .7rem; border: 1px solid rgba(255,255,255,.2); font-size: .78rem; font-weight: 700; text-align: center; }
.studio-ghost:disabled { opacity: .4; }
.studio-preview-mini { position: relative; height: 34vh; border-radius: 1rem; overflow: hidden; }
.studio-mini-bg { position: absolute; inset: 0; background: linear-gradient(160deg, #2b3a2f, #0b0b0b 60%, #4a2a10); }
.studio-preview-mini > small { position: absolute; bottom: .5rem; left: 0; right: 0; text-align: center; font-size: .65rem; opacity: .6; }
.studio-filters i { position: relative; overflow: hidden; }
.studio-filters i.face::after { content: ''; position: absolute; inset: 20% 28%; border-radius: 50% 50% 45% 45%; background: radial-gradient(circle at 50% 40%, #ffe3cf, #e6a985); }
.studio-filters i em { position: absolute; inset: -40%; background: conic-gradient(from 0deg, transparent, rgba(255,255,255,.55), transparent 30%); animation: studio-shine 3s linear infinite; z-index: 1; mix-blend-mode: overlay; }
.studio-filters button.on i { box-shadow: 0 0 0 2px var(--primary), 0 0 18px color-mix(in oklab, var(--primary) 70%, transparent); animation: studio-pulse 1.6s ease-in-out infinite; }
.studio-spark { animation: studio-pulse 1.8s ease-in-out infinite; color: var(--primary); }
@keyframes studio-shine { to { transform: rotate(360deg); } }
@keyframes studio-pulse { 50% { transform: scale(1.08); } }
.studio-shot-actions { display: grid; gap: .5rem; text-align: center; }
.studio-sheet { position: fixed; left: 0; right: 0; bottom: 0; z-index: 99; display: grid; gap: .65rem; padding: 1rem 1rem calc(1rem + env(safe-area-inset-bottom)); background: #0d0f0c; border-top: 1px solid rgba(255,255,255,.12); border-radius: 1.2rem 1.2rem 0 0; max-height: 70dvh; overflow-y: auto; }
.studio-sheet.tall { max-height: 82dvh; }
.studio-sheet-head { display: flex; justify-content: space-between; align-items: center; }
.studio-colors { display: flex; gap: .45rem; flex-wrap: wrap; }
.studio-colors button { width: 1.8rem; height: 1.8rem; border-radius: 999px; border: 2px solid rgba(255,255,255,.3); }
.studio-colors button.on { border-color: var(--primary); transform: scale(1.15); }
.studio-fonts { display: flex; gap: .4rem; overflow-x: auto; scrollbar-width: none; }
.studio-fonts button, .studio-chip { flex: none; padding: .3rem .75rem; border-radius: 999px; background: rgba(255,255,255,.08); font-size: .75rem; }
.studio-fonts button.on, .studio-chip.on { background: var(--primary); color: var(--primary-foreground); }
.studio-sounds { display: grid; gap: .5rem; }
.studio-sound { display: flex; align-items: center; gap: .6rem; font-size: .8rem; }
.studio-disc { width: 2.6rem; height: 2.6rem; flex: none; display: grid; place-items: center; border-radius: 999px; background: radial-gradient(circle, #333 20%, #111 22%, #222 60%); background-size: cover; }
.studio-disc.spin { animation: studio-shine 2.5s linear infinite; }
.studio-wave { display: inline-flex; gap: 2px; margin-left: .4rem; }
.studio-wave i { width: 2px; height: 10px; background: var(--primary); animation: studio-wave .8s ease-in-out infinite; }
.studio-wave i:nth-child(2) { animation-delay: .1s } .studio-wave i:nth-child(3) { animation-delay: .2s } .studio-wave i:nth-child(4) { animation-delay: .3s } .studio-wave i:nth-child(5) { animation-delay: .4s }
@keyframes studio-wave { 50% { transform: scaleY(.3); } }
.bixtok-media { position: absolute; inset: 0; }
.bixtok-embed { width: 100%; height: 100%; border: 0; background: #000; }
.bixtok-src { position: absolute; top: 4.2rem; left: .8rem; z-index: 3; font-size: .6rem; text-transform: uppercase; letter-spacing: .1em; padding: .15rem .5rem; border-radius: 999px; background: rgba(0,0,0,.55); }
.bixtok-music { display: block; margin-top: .25rem; font-size: .72rem; opacity: .9; }
.bxt-plus-logo { position: relative; display: grid; place-items: center; background: linear-gradient(135deg, #9BE15D, #FF8A00) !important; box-shadow: 0 0 18px rgba(155,225,93,.45); animation: studio-glow 2.4s ease-in-out infinite; }
.bxt-plus-logo img { border-radius: 999px; }
.bxt-plus-mini { position: absolute; right: -4px; bottom: -4px; width: 16px !important; height: 16px !important; border-radius: 999px; background: #000; color: #fff; padding: 2px; }
@keyframes studio-glow { 50% { box-shadow: 0 0 28px rgba(255,138,0,.55); } }
@media (prefers-reduced-motion: reduce) { .studio-filters i em, .studio-filters button.on i, .studio-spark, .studio-disc.spin, .studio-wave i, .bxt-plus-logo { animation: none; } }

