/* Toggle switches: plain flat look everywhere (no stretched "bubble" from mobile tap-size rules) */
[role="switch"] { min-height: 0 !important; height: 24px !important; width: 44px !important; padding: 0 !important; box-shadow: none !important; animation: none !important; transform: none !important; flex: 0 0 auto; }
[role="switch"] > span { width: 18px !important; height: 18px !important; box-shadow: none !important; top: 2px; }
[role="switch"][aria-checked="true"] > span.absolute, [role="switch"][data-state="checked"] > span.absolute { left: 22px !important; }
[role="switch"][aria-checked="false"] > span.absolute, [role="switch"][data-state="unchecked"] > span.absolute { left: 2px !important; }
[role="switch"][data-state="checked"] > span:not(.absolute) { transform: translateX(20px) !important; }
[role="switch"][data-state="unchecked"] > span:not(.absolute) { transform: translateX(1px) !important; }

