/* HUB lux carried into WALLET / STAKING / NETWORK / PROFILE (tone from .hub-tone-*) */
.lux-page{position:relative;background:radial-gradient(110% 40% at 50% 0%,color-mix(in oklab,var(--tone) 12%,transparent),transparent 65%)}
.lux-page :is(.rounded-\[20px\],.rounded-3xl,.rounded-2xl).border{border-color:color-mix(in oklab,var(--tone) 26%,transparent)!important;background:linear-gradient(165deg,color-mix(in oklab,var(--tone) 9%,var(--card)),color-mix(in oklab,var(--background) 92%,var(--tone)))!important;box-shadow:inset 0 1px 0 color-mix(in oklab,var(--tone) 22%,transparent),0 10px 24px -18px var(--tone)}
.lux-page :is(h1,h2).section-title span,.lux-page .eyebrow{color:var(--tone)}
.lux-page :is(button,a):active{transform:scale(.97)}
.lux-page :is(button,a){transition:transform .15s}
.lux-page .text-primary{color:var(--tone)}
.lux-page .bg-primary\/15{background:color-mix(in oklab,var(--tone) 16%,transparent)}

/* HUB lux for BIXTRADE / BIXGO / BIXTOK: micro-tile sheen on cards */
.lux-page :is(.rounded-xl,.rounded-lg).border{border-color:color-mix(in oklab,var(--tone) 20%,transparent)!important;box-shadow:inset 0 1px 0 color-mix(in oklab,var(--tone) 16%,transparent)}
.lux-page :is(.rounded-\[20px\],.rounded-3xl,.rounded-2xl).border{position:relative;overflow:hidden}
.lux-page :is(.rounded-\[20px\],.rounded-3xl,.rounded-2xl).border::after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;background:linear-gradient(115deg,transparent 42%,color-mix(in oklab,var(--tone) 12%,transparent) 50%,transparent 58%);transform:translateX(-120%);animation:hub-sheen 9s ease-in-out infinite}
.lux-media{background:none}
.lux-media :is(.rounded-\[20px\],.rounded-3xl,.rounded-2xl).border::after{display:none}
@media (prefers-reduced-motion:reduce){.lux-page :is(.rounded-\[20px\],.rounded-3xl,.rounded-2xl).border::after{display:none}}
/* BIXTOK violet HUB glass */
.bixtok-lobby{--tone:oklch(0.7 0.2 305)}
.bixtok-lobby :is(article,.bxt-live-card,li){border:1px solid color-mix(in oklab,var(--tone) 24%,transparent);border-radius:1rem;background:linear-gradient(165deg,color-mix(in oklab,var(--tone) 10%,var(--card)),color-mix(in oklab,var(--background) 94%,var(--tone)));box-shadow:inset 0 1px 0 color-mix(in oklab,oklch(0.83 0.14 85) 22%,transparent),0 10px 24px -18px var(--tone)}
.bixtok-sheet{--tone:oklch(0.7 0.2 305);border-top:1px solid color-mix(in oklab,oklch(0.83 0.14 85) 35%,transparent)!important;background:linear-gradient(180deg,color-mix(in oklab,var(--tone) 12%,var(--background)),var(--background))!important}
.bixtok-sheet button:active,.bixtok-lobby button:active{transform:scale(.97)}

/* WALLET: compact HUB micro-tiles for BIX PAY / TRANSFER */
.site-shell .wallet-tile.wallet-tile--square{aspect-ratio:auto;flex-direction:row;align-items:center;justify-content:flex-start;gap:.6rem;padding:.65rem .7rem;border-radius:.95rem;min-height:0;box-shadow:inset 0 1px 0 color-mix(in oklab,var(--tile) 25%,transparent),0 10px 22px -18px var(--tile)}
.site-shell .wallet-tile--square .wallet-tile-icon{width:2.1rem;height:2.1rem;margin:0;border-radius:.7rem;flex-shrink:0;box-shadow:0 0 12px -4px var(--tile)}
.site-shell .wallet-tile--square .wallet-tile-icon svg{width:17px;height:17px}
.site-shell .wallet-tile--square .wallet-tile-title{font-size:12px}
.site-shell .wallet-tile--square .wallet-tile-sub{font-size:9.5px}
.site-shell .wallet-tile--square .wallet-tile-status{top:.45rem;right:.55rem;font-size:8px}
.site-shell .wallet-tile--square:active{transform:scale(.97)}

/* HUB glass for all pop ups (Radix dialogs + legacy modal panels) */
:where(.lux-pop,.modal-panel){--tone:oklch(0.76 0.15 160);border:1px solid color-mix(in oklab,var(--tone) 30%,transparent);border-radius:1.1rem;background:radial-gradient(120% 60% at 0% 0%,color-mix(in oklab,var(--tone) 11%,transparent),transparent 60%),linear-gradient(170deg,color-mix(in oklab,var(--tone) 6%,var(--card)),var(--background));box-shadow:inset 0 1px 0 color-mix(in oklab,oklch(0.83 0.14 85) 28%,transparent),0 24px 60px -24px color-mix(in oklab,var(--tone) 45%,transparent)}
.modal-panel{border-color:color-mix(in oklab,oklch(0.76 0.15 160) 32%,transparent)}
.modal-panel .form-input,.lux-pop .form-input,.lux-page .form-input{border-color:color-mix(in oklab,var(--tone,var(--border)) 26%,var(--border));background:color-mix(in oklab,var(--background) 88%,var(--tone,var(--card)))}
.modal-panel .form-input:focus,.lux-pop .form-input:focus,.lux-page .form-input:focus{border-color:var(--tone,var(--primary));box-shadow:0 0 0 3px color-mix(in oklab,var(--tone,var(--primary)) 18%,transparent)}
.modal-panel :is(.rounded-xl,.rounded-2xl).border,.lux-pop :is(.rounded-xl,.rounded-2xl).border{border-color:color-mix(in oklab,oklch(0.76 0.15 160) 22%,transparent)!important;background:color-mix(in oklab,oklch(0.76 0.15 160) 6%,var(--card))}
.modal-panel :is(button,a):active,.lux-pop :is(button,a):active{transform:scale(.97)}
.site-shell .wallet-tile.wallet-tile--square{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto auto;column-gap:.6rem;row-gap:.1rem;align-items:center}
.site-shell .wallet-tile--square .wallet-tile-icon{grid-row:1/3}
.site-shell .wallet-tile--square .wallet-tile-title{white-space:nowrap;align-self:end;padding-right:2.6rem}
.site-shell .wallet-tile--square .wallet-tile-sub{grid-column:2;align-self:start}

/* Wallet: compact Internal Swap + colour-coded transaction history */
.swap-compact .swap-balrow{display:flex;align-items:center;gap:.6rem;padding:.5rem .75rem;border-radius:.85rem;border:1px solid color-mix(in oklab,var(--chart-2) 28%,transparent);background:linear-gradient(180deg,color-mix(in oklab,var(--chart-2) 9%,transparent),transparent)}
.swap-compact .swap-balrow>div{flex:1;display:flex;flex-direction:column}
.swap-compact .swap-balrow span{font-size:9px;font-weight:800;letter-spacing:.14em;color:var(--muted-foreground)}
.swap-compact .swap-balrow b{font-size:.95rem;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.swap-compact .swap-balrow i{width:1px;align-self:stretch;background:color-mix(in oklab,var(--foreground) 14%,transparent)}
.tx-row{--tx:var(--chart-2);border-color:color-mix(in oklab,var(--tx) 26%,transparent)!important;background:linear-gradient(90deg,color-mix(in oklab,var(--tx) 8%,transparent),transparent 60%),var(--card)!important}
.tx-row.tx-out{--tx:var(--destructive)}
.tx-row.tx-bonus{--tx:var(--chart-3)}
.tx-row .tx-chip{display:grid;place-items:center;flex-shrink:0;width:2.1rem;height:2.1rem;border-radius:.7rem;color:var(--tx);border:1px solid color-mix(in oklab,var(--tx) 45%,transparent);background:color-mix(in oklab,var(--tx) 14%,transparent);box-shadow:0 0 12px -4px var(--tx)}
.tx-row .tx-amt{color:var(--tx)}

/* Presale: minimalist lux hero + HUB tone */
.presale-hero-min{border-color:color-mix(in oklab,var(--tone,var(--chart-3)) 32%,transparent)!important;background:radial-gradient(120% 90% at 100% 0%,color-mix(in oklab,var(--tone,var(--chart-3)) 16%,transparent),transparent 60%),linear-gradient(165deg,color-mix(in oklab,var(--card) 92%,var(--tone,var(--chart-3))),var(--background))!important;box-shadow:inset 0 1px 0 color-mix(in oklab,var(--tone,var(--chart-3)) 30%,transparent),0 18px 40px -26px var(--tone,var(--chart-3))!important}
.presale-hero-art{position:absolute;right:-12%;top:-8%;width:62%;max-width:22rem;height:auto;aspect-ratio:5/3;object-fit:cover;opacity:.32;border-radius:50%;-webkit-mask-image:radial-gradient(closest-side,#000 40%,transparent);mask-image:radial-gradient(closest-side,#000 40%,transparent);pointer-events:none}
.presale-hero-chip{font-size:9px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;padding:.2rem .55rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--tone,var(--chart-3)) 40%,transparent);color:var(--tone,var(--chart-3));background:color-mix(in oklab,var(--tone,var(--chart-3)) 10%,transparent)}
.presale-hero-min .presale-cd-cell{padding:.3rem 0;border-radius:.6rem;border:1px solid color-mix(in oklab,var(--tone,var(--chart-3)) 26%,transparent);background:color-mix(in oklab,var(--background) 70%,transparent);display:flex;flex-direction:column;align-items:center}
.presale-hero-min .presale-stage-step{padding:.45rem .3rem}
.lux-page .presale-stat-card,.lux-page .presale-lux-card{border:1px solid color-mix(in oklab,var(--tone) 28%,transparent)!important;background:linear-gradient(165deg,color-mix(in oklab,var(--tone) 9%,var(--card)),color-mix(in oklab,var(--background) 92%,var(--tone)))!important;box-shadow:inset 0 1px 0 color-mix(in oklab,var(--tone) 24%,transparent),0 10px 24px -18px var(--tone)!important}
.lux-page .presale-stat-card{border-radius:.9rem;padding:.55rem .3rem}
.lux-page .presale-lux-card{border-radius:1rem}
.lux-page .presale-lux-inner{padding:12px!important;border-radius:.95rem}
.lux-page .presale-lux-price{font-size:clamp(1.1rem,5vw,1.6rem)}
.lux-page .presale-tabs{border-color:color-mix(in oklab,var(--tone) 32%,transparent);background:color-mix(in oklab,var(--card) 80%,transparent)}
.lux-page .presale-tabs button{padding:.4rem .75rem;font-size:.7rem}
.lux-page .presale-tabs .is-active{background:linear-gradient(135deg,var(--tone),color-mix(in oklab,var(--tone) 60%,var(--background)))!important}
.lux-page section[aria-label="Presale pool availability"]{border-color:color-mix(in oklab,var(--tone) 22%,transparent)}

/* ===== Futuristic core: holo reactor, HUD scanner, odometer, glow ===== */
.holo-wrap{position:relative;display:flex;flex-direction:column;align-items:center;gap:.6rem;margin:0 auto;perspective:700px}
.holo-stage{--rx:0deg;--ry:0deg;position:relative;width:var(--hs);height:var(--hs);transform-style:preserve-3d;transform:rotateX(var(--rx)) rotateY(var(--ry));transition:transform .25s ease-out}
.holo-md{--hs:170px}.holo-sm{--hs:120px}
.holo-sphere{position:absolute;inset:14%;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 35% 30%,color-mix(in oklab,#A855F7 35%,transparent),transparent 55%),radial-gradient(circle at 60% 70%,color-mix(in oklab,#FFD700 22%,transparent),transparent 60%),color-mix(in oklab,var(--background) 80%,transparent);border:1px solid color-mix(in oklab,#FFD700 35%,transparent);box-shadow:inset 0 0 30px color-mix(in oklab,#A855F7 40%,transparent),0 0 40px color-mix(in oklab,#FFD700 18%,transparent)}
.holo-scan{position:absolute;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#FFD700,#A855F7,transparent);box-shadow:0 0 10px #FFD700;animation:holo-scan 3.6s ease-in-out infinite}
@keyframes holo-scan{0%,100%{top:8%;opacity:0}15%,85%{opacity:.9}50%{top:92%}}
.holo-ring{position:absolute;inset:0;border-radius:50%;border:1px solid color-mix(in oklab,#FFD700 55%,transparent);box-shadow:0 0 12px color-mix(in oklab,#FFD700 25%,transparent)}
.holo-ring.r1{transform:rotateX(72deg);animation:holo-spin 14s linear infinite}
.holo-ring.r2{inset:6%;border-color:color-mix(in oklab,#A855F7 60%,transparent);transform:rotateY(70deg);animation:holo-spin-r 18s linear infinite}
.holo-ring.r3{inset:-6%;border-style:dashed;border-color:color-mix(in oklab,#C0C0C0 35%,transparent);animation:holo-flat 26s linear infinite}
@keyframes holo-spin{to{transform:rotateX(72deg) rotateZ(360deg)}}
@keyframes holo-spin-r{to{transform:rotateY(70deg) rotateZ(-360deg)}}
@keyframes holo-flat{to{transform:rotateZ(360deg)}}
.holo-emblem{position:absolute;left:50%;top:50%;width:46%;height:46%;object-fit:contain;transform:translate(-50%,-50%) translateZ(30px);filter:drop-shadow(0 0 14px color-mix(in oklab,#FFD700 55%,transparent));animation:holo-float 5s ease-in-out infinite}
@keyframes holo-float{50%{transform:translate(-50%,-56%) translateZ(30px)}}
.holo-radar{position:absolute;top:calc(var(--hs)/2);left:50%;width:0;height:0}
.holo-radar i{position:absolute;left:0;top:0;width:calc(var(--hs)*1.1);height:calc(var(--hs)*1.1);margin:calc(var(--hs)*-.55);border-radius:50%;border:1px solid color-mix(in oklab,#A855F7 45%,transparent);animation:holo-pulse 4.5s ease-out infinite;opacity:0}
.holo-radar i:nth-child(2){animation-delay:1.5s}.holo-radar i:nth-child(3){animation-delay:3s}
@keyframes holo-pulse{0%{transform:scale(.6);opacity:.7}100%{transform:scale(1.7);opacity:0}}
.holo-telemetry{display:flex;flex-wrap:wrap;justify-content:center;gap:.35rem;font-size:9px;letter-spacing:.12em;color:var(--muted-foreground)}
.holo-telemetry span{padding:.2rem .55rem;border-radius:999px;border:1px solid color-mix(in oklab,#FFD700 22%,transparent);background:color-mix(in oklab,var(--background) 70%,transparent)}
.holo-telemetry i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#10B981;box-shadow:0 0 6px #10B981;margin-right:4px;animation:holo-blink 1.6s ease-in-out infinite}
@keyframes holo-blink{50%{opacity:.25}}
.holo-wrap.is-eco *{animation:none!important}.holo-wrap.is-eco .holo-scan{display:none}
.hud-scan{position:relative;overflow:hidden}
.hud-scan::after{content:"";position:absolute;inset:0 auto 0 -30%;width:30%;pointer-events:none;background:linear-gradient(90deg,transparent,color-mix(in oklab,#FFD700 14%,transparent),color-mix(in oklab,#A855F7 12%,transparent),transparent);animation:hud-sweep 7s ease-in-out infinite}
@keyframes hud-sweep{0%,70%{left:-30%}100%{left:130%}}
.odo{display:inline-flex;align-items:baseline}
.odo-col{display:inline-block;height:1.15em;line-height:1.15em;overflow:hidden;vertical-align:bottom}
.odo-col>span{display:flex;flex-direction:column;transition:transform 1.1s cubic-bezier(.2,.8,.2,1)}
.odo-col b{height:1.15em;font-weight:inherit}
.fx-glow{position:relative;isolation:isolate}
.fx-glow::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;z-index:1;opacity:0;transition:opacity .4s;background:radial-gradient(160px circle at var(--mx,50%) var(--my,50%),color-mix(in oklab,#FFD700 16%,transparent),transparent 70%)}
.fx-glow:hover::before,.fx-glow:active::before{opacity:1}
@media (prefers-reduced-motion:reduce){.holo-wrap *,.hud-scan::after{animation:none!important}.odo-col>span{transition:none}}

/* HUB hero for BIX PAY / TRANSFER */
.hubx-hero { position:relative; overflow:hidden; border-radius:18px; padding:14px 16px; border:1px solid color-mix(in oklab, var(--chart-2) 35%, transparent); background:radial-gradient(120% 80% at 0% 0%, color-mix(in oklab, var(--chart-2) 14%, transparent), transparent 60%), color-mix(in oklab, var(--background) 82%, var(--card)); box-shadow:inset 0 1px 0 color-mix(in oklab, var(--chart-3) 30%, transparent), 0 10px 30px -18px color-mix(in oklab, var(--chart-2) 60%, transparent); }
.hubx-hero::before { content:""; position:absolute; inset:0 20% auto; height:1px; background:linear-gradient(90deg, transparent, var(--chart-3), transparent); opacity:.7; }
.hubx-hero__label { font-size:9.5px; font-weight:800; letter-spacing:.16em; color:var(--muted-foreground); }
.hubx-hero__num { margin-top:4px; display:flex; flex-wrap:wrap; align-items:baseline; gap:2px 6px; line-height:1.1; min-width:0; }
.hubx-hero__num b { font-size:clamp(22px, 7vw, 30px); font-weight:900; color:var(--chart-3); word-break:break-all; }
.hubx-hero__num small { font-size:clamp(12px, 3.6vw, 15px); font-weight:700; color:color-mix(in oklab, var(--chart-3) 65%, var(--muted-foreground)); margin-left:-6px; }
.hubx-hero__num em { font-style:normal; font-size:10px; font-weight:800; letter-spacing:.1em; padding:2px 8px; border-radius:999px; border:1px solid color-mix(in oklab, var(--chart-2) 45%, transparent); color:var(--chart-2); }
.hubx-chip { margin-top:10px; display:inline-flex; align-items:center; gap:6px; padding:4px 10px; border-radius:999px; font-size:11px; font-weight:800; border:1px solid color-mix(in oklab, var(--chart-3) 40%, transparent); background:color-mix(in oklab, var(--card) 70%, transparent); color:var(--foreground); }
.hubx-tabs { display:grid; grid-template-columns:1fr 1fr; gap:4px; padding:3px; border-radius:999px; border:1px solid color-mix(in oklab, var(--chart-2) 25%, var(--border)); background:color-mix(in oklab, var(--background) 85%, var(--card)); }
.hubx-tabs button { display:inline-flex; align-items:center; justify-content:center; gap:5px; padding:7px 0; border-radius:999px; font-size:12.5px; font-weight:800; color:var(--muted-foreground); transition:transform .15s; }
.hubx-tabs button:active { transform:scale(.97); }
.hubx-tabs button.is-on { color:var(--foreground); background:linear-gradient(180deg, color-mix(in oklab, var(--chart-2) 28%, var(--card)), color-mix(in oklab, var(--chart-2) 10%, var(--card))); box-shadow:inset 0 0 0 1px color-mix(in oklab, var(--chart-2) 55%, transparent), 0 0 14px -4px var(--chart-2); }
.lux-page .pay-qr-card { width:min(100%, 250px); padding:12px; background:color-mix(in oklab, var(--background) 82%, var(--card)); }
.lux-page .pay-qr-plate { padding:10px; }

/* Full-screen BIX PAY QR scanner */
.qr-full { position:fixed; inset:0; z-index:200; background:var(--background); overflow:hidden; }
.qr-full__cam { position:absolute; inset:0; }
.qr-full__cam video { width:100% !important; height:100% !important; object-fit:cover; }
.qr-full__cam #qr-shaded-region, .qr-full__cam canvas { display:none !important; }
.qr-full__mask { position:absolute; inset:0; display:grid; place-items:center; pointer-events:none; }
.qr-full__frame { position:relative; width:min(70vw, 70vh, 320px); aspect-ratio:1; border-radius:22px; box-shadow:0 0 0 200vmax color-mix(in oklab, var(--background) 58%, transparent); }
.qr-full__frame i { position:absolute; width:34px; height:34px; border:3px solid var(--chart-3); filter:drop-shadow(0 0 6px var(--chart-3)); }
.qr-full__frame i:nth-child(1) { top:0; left:0; border-right:0; border-bottom:0; border-top-left-radius:22px; }
.qr-full__frame i:nth-child(2) { top:0; right:0; border-left:0; border-bottom:0; border-top-right-radius:22px; }
.qr-full__frame i:nth-child(3) { bottom:0; left:0; border-right:0; border-top:0; border-bottom-left-radius:22px; }
.qr-full__frame i:nth-child(4) { bottom:0; right:0; border-left:0; border-top:0; border-bottom-right-radius:22px; }
.qr-full__laser { position:absolute; left:8%; right:8%; top:10%; height:2px; border-radius:2px; background:linear-gradient(90deg, transparent, var(--chart-2), transparent); box-shadow:0 0 12px var(--chart-2); animation:qrLaser 2.2s ease-in-out infinite alternate; }
@keyframes qrLaser { to { top:88%; } }
@media (prefers-reduced-motion:reduce) { .qr-full__laser { animation:none; top:50%; } }
.qr-full__top { position:absolute; top:0; left:0; right:0; display:flex; align-items:center; justify-content:space-between; padding:calc(env(safe-area-inset-top) + 14px) 16px 14px; background:linear-gradient(180deg, color-mix(in oklab, var(--background) 80%, transparent), transparent); }
.qr-full__x { display:grid; place-items:center; width:38px; height:38px; border-radius:999px; border:1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); background:color-mix(in oklab, var(--card) 70%, transparent); color:var(--foreground); }
.qr-full__bottom { position:absolute; left:0; right:0; bottom:0; display:flex; flex-direction:column; align-items:center; gap:12px; padding:20px 16px calc(env(safe-area-inset-bottom) + 24px); background:linear-gradient(0deg, color-mix(in oklab, var(--background) 85%, transparent), transparent); }
.qr-full__hint { font-size:12px; text-align:center; color:var(--foreground); }
.qr-full__gallery { display:inline-flex; align-items:center; gap:8px; cursor:pointer; padding:10px 18px; border-radius:999px; font-size:12px; font-weight:800; letter-spacing:.06em; color:var(--chart-3); border:1px solid color-mix(in oklab, var(--chart-3) 55%, transparent); background:color-mix(in oklab, var(--card) 70%, transparent); backdrop-filter:blur(8px); }

/* HUB Partnership panel (wallet + landing) */
.hub-partners{max-width:64rem;margin:14px auto 0;padding:0 16px}
.hub-partners--landing{max-width:48rem;margin:6px auto 18px}
.hub-partners-panel{position:relative;overflow:hidden;padding:14px 12px 10px;border-radius:22px;background:linear-gradient(160deg,oklch(0.17 0.02 160/.92),oklch(0.12 0.01 260/.96));border:1px solid color-mix(in oklab,var(--chart-3) 30%,transparent);box-shadow:inset 0 1px 0 oklch(1 0 0/.08),0 18px 40px -22px oklch(0 0 0/.8)}
.hub-partners-panel::before{content:"";position:absolute;left:12%;right:12%;top:0;height:1px;background:linear-gradient(90deg,transparent,var(--chart-3),transparent)}
.hub-partners-bg{position:absolute;inset:0;pointer-events:none;opacity:.13;filter:blur(1px)}
.hub-partners-ghost{position:absolute;transform:scale(2.6);animation:hp-drift 9s ease-in-out infinite}
.hub-partners-ghost .wp-mark{animation:none}
@keyframes hp-drift{0%,100%{translate:0 0}50%{translate:6px -8px}}
.hub-partners-head{position:relative;text-align:center;margin-bottom:10px}
.hub-partners-head small{display:block;font-size:8px;font-weight:800;letter-spacing:.32em;color:var(--muted-foreground)}
.hub-partners-head h3{font-size:13px;font-weight:900;letter-spacing:.3em;background:linear-gradient(90deg,var(--chart-3),oklch(0.75 0.2 305));-webkit-background-clip:text;background-clip:text;color:transparent}
.hub-partners-grid{position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.hub-partner{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:68px;padding:8px 4px;border-radius:14px;background:linear-gradient(180deg,color-mix(in oklab,var(--c1) 16%,oklch(0.14 0.01 260/.9)),oklch(0.11 0.01 260/.92));border:1px solid color-mix(in oklab,var(--c1) 38%,transparent);box-shadow:inset 0 1px 0 oklch(1 0 0/.07);text-align:center;transition:transform .2s}
.hub-partner::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 35%,oklch(1 0 0/.1) 50%,transparent 65%);transform:translateX(-120%);animation:hp-sheen 6s ease-in-out infinite;animation-delay:inherit}
@keyframes hp-sheen{0%,70%{transform:translateX(-120%)}100%{transform:translateX(120%)}}
.hub-partner:active{transform:scale(.97)}
.hub-partner .wp-mark{width:24px;height:24px;font-size:12px;margin-bottom:4px}
.hub-partner .wp-rings i{width:18px;height:18px}
.hub-partner .wp-word{height:20px;font-size:10px;padding:0 6px}
.hub-partner b{font-size:10px;font-weight:900;color:var(--foreground);line-height:1.1}
.hub-partner span:not(.wp-mark){font-size:7.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:color-mix(in oklab,var(--c1) 55%,var(--muted-foreground));margin-top:2px}
.hub-partners-note{position:relative;margin-top:8px;text-align:center;font-size:8.5px;color:var(--muted-foreground)}
@media (prefers-reduced-motion:reduce){.hub-partners-ghost,.hub-partner::after{animation:none}}

/* BIX CALL */
.bixcall{position:fixed;inset:0;z-index:9999;display:flex;flex-direction:column;align-items:center;background:radial-gradient(120% 70% at 50% 20%,color-mix(in oklab,#A855F7 30%,transparent),transparent 60%),radial-gradient(90% 50% at 50% 100%,color-mix(in oklab,#FFD700 14%,transparent),transparent 70%),#05040a;color:#f5f3ff;overflow:hidden}
.bixcall-remote{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:radial-gradient(80% 60% at 50% 50%,rgba(168,85,247,.18),#05040a);opacity:0}
.bixcall-remote.on{opacity:1}
.bixcall-head{position:relative;z-index:2;margin-top:max(14px,env(safe-area-inset-top));display:flex;align-items:center;gap:8px;padding:6px 12px 6px 6px;border-radius:999px;background:rgba(8,6,14,.72);border:1px solid rgba(255,215,0,.45);backdrop-filter:blur(10px);box-shadow:0 0 18px rgba(168,85,247,.35);max-width:94vw}
.bixcall-head span{font-size:9px;font-weight:800;letter-spacing:.08em;color:#FFD700;line-height:1.3}
.bixcall-fox{width:30px;height:30px;border-radius:50%;filter:drop-shadow(0 0 6px #FFD700)}
.bixcall-center{position:relative;z-index:2;margin-top:12vh;text-align:center}
.bixcall-av{width:128px;height:128px;margin:0 auto;border-radius:50%;display:grid;place-items:center;border:3px solid #FFD700;background:linear-gradient(145deg,#1a1028,#0a0710);box-shadow:0 0 0 6px rgba(168,85,247,.18),0 0 40px rgba(255,215,0,.25)}
.bixcall-av b{font-size:52px;color:#FFD700}
.bixcall-av.ringing,.bixcall-av.talking{animation:bixcallPulse 1.4s ease-out infinite}
@keyframes bixcallPulse{0%{box-shadow:0 0 0 0 rgba(168,85,247,.6),0 0 40px rgba(255,215,0,.25)}100%{box-shadow:0 0 0 28px rgba(168,85,247,0),0 0 40px rgba(255,215,0,.25)}}
.bixcall-center h2{margin-top:18px;font-size:22px;font-weight:900}
.bixcall-center p{font-size:12px;opacity:.7}
.bixcall-status{position:relative;z-index:2;margin-top:14px;display:flex;align-items:center;gap:6px;font-size:13px;font-weight:700;padding:4px 12px;border-radius:999px;background:rgba(0,0,0,.45)}
.bixcall-status i{width:7px;height:7px;border-radius:50%;background:#a3a3a3}
.bixcall-status i.ok{background:#10b981;box-shadow:0 0 8px #10b981}
.bixcall-pip{position:absolute;z-index:3;top:80px;right:14px;width:96px;height:150px;object-fit:cover;border-radius:16px;border:2px solid #FFD700;touch-action:none;background:#000}
.bixcall-ctl{position:absolute;z-index:3;bottom:max(28px,env(safe-area-inset-bottom));display:flex;gap:14px;padding:12px 16px;border-radius:28px;background:rgba(8,6,14,.7);border:1px solid rgba(168,85,247,.4);backdrop-filter:blur(12px)}
.bixcall-ctl>*{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);color:#fff}
.bixcall-ctl .off{background:rgba(255,255,255,.85);color:#111}
.bixcall-ctl .end{background:linear-gradient(145deg,#ef4444,#991b1b);border:2px solid #FFD700}
.bixcall-ctl .accept{background:linear-gradient(145deg,#10b981,#047857);border:2px solid #FFD700;animation:bixcallPulse 1.4s infinite}
.bixcall-ctl .wa{background:#16a34a}
.bixcall-toast{position:fixed;z-index:9999;left:50%;top:16px;transform:translateX(-50%);padding:8px 14px;border-radius:12px;background:#120a1d;border:1px solid #A855F7;color:#fff;font-size:12px;max-width:90vw}
.bixcall-btns{display:inline-flex;gap:6px}
.bixcall-btns button{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(255,215,0,.5);background:linear-gradient(145deg,rgba(168,85,247,.35),rgba(10,7,16,.9));color:#FFD700}

/* BIX CALL & CHAT — HUB violet/gold comm terminal */
.comm-head{display:flex;align-items:center;gap:.7rem;margin-bottom:.8rem}
.comm-status{display:flex;align-items:center;gap:.35rem;font-size:9px;letter-spacing:.18em;color:color-mix(in oklab,var(--primary) 70%,var(--foreground))}
.comm-status i{width:6px;height:6px;border-radius:50%;background:oklch(0.75 0.17 155);box-shadow:0 0 8px oklch(0.75 0.17 155);animation:comm-blink 2s infinite}
@keyframes comm-blink{50%{opacity:.35}}
.comm-tier{font-size:9px;font-weight:800;letter-spacing:.08em;padding:.3rem .55rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--foreground) 25%,transparent);white-space:nowrap}
.comm-tier.is-vip{border-color:oklch(0.82 0.15 85);color:oklch(0.85 0.14 85);box-shadow:0 0 12px oklch(0.82 0.15 85 / .35)}
.comm-tier.is-video,.comm-tier.is-voice{border-color:oklch(0.65 0.2 300);color:oklch(0.8 0.13 300)}
.comm-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:.3rem;padding:.25rem;border-radius:999px;background:color-mix(in oklab,var(--background) 70%,black);border:1px solid color-mix(in oklab,oklch(0.65 0.2 300) 35%,transparent);margin-bottom:.8rem}
.comm-tabs button{display:flex;align-items:center;justify-content:center;gap:.35rem;font-size:12px;font-weight:700;padding:.5rem;border-radius:999px;color:var(--muted-foreground)}
.comm-tabs button.is-on{color:var(--foreground);background:linear-gradient(135deg,oklch(0.45 0.2 300 / .55),oklch(0.6 0.12 85 / .35));box-shadow:inset 0 0 0 1px oklch(0.82 0.15 85 / .45)}
.comm-card{position:relative;margin-bottom:.7rem;padding:.8rem;border-radius:1rem;background:linear-gradient(180deg,oklch(0.2 0.04 300 / .55),color-mix(in oklab,var(--background) 85%,black));border:1px solid oklch(0.65 0.2 300 / .3);overflow:hidden}
.comm-card::before{content:"";position:absolute;inset:0 12% auto;height:1px;background:linear-gradient(90deg,transparent,oklch(0.82 0.15 85 / .7),transparent)}
.comm-h{font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:oklch(0.8 0.13 300);margin-bottom:.55rem}
.comm-search{display:flex;align-items:center;gap:.45rem;padding:.3rem .3rem .3rem .75rem;border-radius:999px;background:color-mix(in oklab,var(--background) 60%,black);border:1px solid oklch(0.65 0.2 300 / .35)}
.comm-search input{min-width:0;flex:1;background:transparent;font-size:13px;outline:none}
.comm-search button{font-size:11px;font-weight:800;padding:.4rem .8rem;border-radius:999px;background:linear-gradient(135deg,oklch(0.82 0.15 85),oklch(0.65 0.2 300));color:var(--background)}
.comm-peer,.comm-row,.comm-list li>button{display:flex;align-items:center;gap:.6rem;width:100%}
.comm-peer{margin-top:.6rem;padding:.5rem;border-radius:.8rem;border:1px solid oklch(0.65 0.2 300 / .25);flex-wrap:wrap}
.comm-list{display:flex;flex-direction:column;gap:.15rem}
.comm-list li{padding:.45rem 0;border-bottom:1px solid color-mix(in oklab,var(--foreground) 8%,transparent);flex-wrap:wrap}
.comm-list li:last-child{border-bottom:0}
.comm-ava{display:grid;place-items:center;width:2.2rem;height:2.2rem;flex-shrink:0;border-radius:50%;font-weight:900;font-size:13px;background:radial-gradient(circle at 30% 30%,oklch(0.5 0.2 300),oklch(0.2 0.05 300));box-shadow:0 0 0 1.5px oklch(0.82 0.15 85 / .7)}
.comm-badge{display:inline-grid;place-items:center;min-width:1.1rem;height:1.1rem;margin-top:.2rem;padding:0 .3rem;border-radius:999px;font-size:10px;font-style:normal;font-weight:800;background:oklch(0.82 0.15 85);color:var(--background)}
.comm-dir{width:1.6rem;text-align:center;font-weight:900;color:oklch(0.75 0.17 155)}.comm-dir.is-miss{color:var(--destructive)}
.comm-actions{position:relative;display:inline-flex;gap:.3rem;flex-wrap:wrap;justify-content:flex-end}
.comm-actions>button{display:grid;place-items:center;width:2rem;height:2rem;border-radius:50%;border:1px solid oklch(0.65 0.2 300 / .5);background:oklch(0.25 0.06 300 / .6);color:oklch(0.88 0.1 300)}
.comm-actions>button:active{transform:scale(.92)}
.comm-actions>button.is-locked{opacity:.55;border-style:dashed}
.comm-hint{position:absolute;right:0;top:110%;z-index:5;width:max-content;max-width:14rem;font-size:10px;font-style:normal;padding:.35rem .55rem;border-radius:.5rem;background:color-mix(in oklab,var(--background) 90%,black);border:1px solid oklch(0.82 0.15 85 / .5)}
.comm-hint a{color:oklch(0.85 0.14 85);font-weight:800}
.comm-lock{display:flex;align-items:center;gap:.4rem;margin-bottom:.6rem;font-size:11px;padding:.5rem .7rem;border-radius:.7rem;border:1px dashed oklch(0.82 0.15 85 / .5)}
.comm-ladder{display:grid;grid-template-columns:repeat(4,1fr);gap:.35rem}
.comm-ladder>div{position:relative;display:flex;flex-direction:column;align-items:center;gap:.15rem;padding:.55rem .2rem;border-radius:.7rem;border:1px solid color-mix(in oklab,var(--foreground) 12%,transparent);opacity:.5;font-size:11px}
.comm-ladder>div small{font-size:9px;color:var(--muted-foreground)}
.comm-ladder>div.is-on{opacity:1;border-color:oklch(0.82 0.15 85 / .55);background:oklch(0.82 0.15 85 / .08);color:oklch(0.88 0.12 85)}
.comm-ladder-lock{position:absolute;top:.3rem;right:.3rem}
.comm-upgrade{display:block;margin-top:.55rem;font-size:11px;font-weight:700;color:oklch(0.85 0.14 85)}
.comm-perms{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}
.comm-perms button{font-size:12px;padding:.5rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--foreground) 15%,transparent)}
.comm-perms button.is-on{font-weight:800;border-color:oklch(0.65 0.2 300);background:oklch(0.45 0.2 300 / .3);box-shadow:0 0 10px oklch(0.65 0.2 300 / .3)}
.comm-input{width:100%;padding:.55rem .8rem;border-radius:999px;font-size:13px;background:color-mix(in oklab,var(--background) 60%,black);border:1px solid oklch(0.65 0.2 300 / .35);outline:none}
.comm-input:focus{border-color:oklch(0.82 0.15 85)}
.comm-check{display:flex;align-items:center;gap:.5rem;margin-top:.6rem;font-size:12px}
.comm-save{width:100%;margin-top:.8rem;padding:.6rem;border-radius:999px;font-weight:800;font-size:13px;background:linear-gradient(135deg,oklch(0.82 0.15 85),oklch(0.6 0.2 300));color:var(--background)}
.comm-save:active{transform:scale(.97)}
.comm-room{display:flex;flex-direction:column;height:calc(100dvh - 9rem);padding:.6rem .8rem}
.comm-room-head{display:flex;align-items:center;gap:.55rem;padding:.55rem;border-radius:1rem;border:1px solid oklch(0.65 0.2 300 / .35);background:color-mix(in oklab,var(--background) 75%,black)}
.comm-msgs{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:.4rem;padding:.8rem .1rem}
.comm-msgs>p{max-width:78%;align-self:flex-start;padding:.5rem .7rem;border-radius:1rem 1rem 1rem .25rem;font-size:13px;line-height:1.35;word-break:break-word;background:oklch(0.25 0.04 300 / .75);border:1px solid oklch(0.65 0.2 300 / .25)}
.comm-msgs>p.is-me{align-self:flex-end;border-radius:1rem 1rem .25rem 1rem;background:linear-gradient(135deg,oklch(0.42 0.18 300 / .8),oklch(0.45 0.1 85 / .55));border-color:oklch(0.82 0.15 85 / .35)}
.comm-msgs>p small{display:block;margin-top:.15rem;font-size:9px;opacity:.65;text-align:right}
.comm-err{font-size:11px;color:var(--destructive);text-align:center;padding:.2rem}
.comm-compose{display:flex;align-items:center;gap:.4rem;padding:.35rem;border-radius:999px;border:1px solid oklch(0.65 0.2 300 / .4);background:color-mix(in oklab,var(--background) 70%,black)}
.comm-compose input{flex:1;min-width:0;background:transparent;font-size:14px;outline:none;padding:0 .3rem}
.comm-compose button,.comm-pay{display:grid;place-items:center;width:2.3rem;height:2.3rem;flex-shrink:0;border-radius:50%}
.comm-compose button{background:linear-gradient(135deg,oklch(0.82 0.15 85),oklch(0.6 0.2 300));color:var(--background)}
.comm-compose button:disabled{opacity:.4}
.comm-pay{border:1px solid oklch(0.82 0.15 85 / .5)}
@media (prefers-reduced-motion:reduce){.comm-status i{animation:none}}
.comm-clear{background:transparent!important;color:var(--muted-foreground)!important;padding:.3rem!important}
.comm-chips{display:flex;flex-wrap:wrap;gap:.3rem;margin-top:.5rem}
.comm-chips>*{font-size:9px;font-weight:700;letter-spacing:.06em;padding:.18rem .5rem;border-radius:999px;border:1px solid oklch(0.65 0.2 300 / .3);color:oklch(0.8 0.1 300)}
.comm-chips>button{border-color:oklch(0.82 0.15 85 / .4);color:oklch(0.86 0.12 85)}
.comm-meta{display:flex;flex-wrap:wrap;align-items:center;gap:.3rem;margin-top:.15rem}
.comm-meta button{font-size:10px;font-weight:800;padding:.1rem .45rem;border-radius:999px;border:1px solid oklch(0.82 0.15 85 / .55);color:oklch(0.86 0.13 85)}
.comm-meta i{font-size:9px;font-style:normal;font-weight:700;padding:.1rem .45rem;border-radius:999px;color:oklch(0.8 0.15 155);border:1px solid oklch(0.75 0.17 155 / .5)}
.comm-meta small{font-size:9px;color:var(--muted-foreground)}

/* BIX CALL full-screen page: no shell, only a back arrow */
.bixcall-page{position:relative;padding:10px 0 110px}
.bixcall-back{position:absolute;top:18px;left:18px;z-index:3;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;color:#FFD700;background:rgba(8,6,14,.78);border:1px solid rgba(255,215,0,.45);backdrop-filter:blur(10px);box-shadow:0 0 14px rgba(168,85,247,.35)}
.bixcall-hero{position:relative;margin:0 auto 12px;max-width:36rem;width:calc(100% - 24px);height:150px;border-radius:22px;overflow:hidden;border:1px solid rgba(255,215,0,.28);box-shadow:0 0 28px rgba(168,85,247,.25),inset 0 1px 0 rgba(255,215,0,.35)}
.bixcall-hero img{width:100%;height:100%;object-fit:cover;animation:bixcall-float 7s ease-in-out infinite}
.bixcall-hero div{position:absolute;left:0;right:0;bottom:0;padding:12px 16px;background:linear-gradient(transparent,rgba(5,4,10,.9))}
.bixcall-hero b{display:block;font-size:20px;letter-spacing:.2em;background:linear-gradient(90deg,#FFD700,#A855F7);-webkit-background-clip:text;background-clip:text;color:transparent}
.bixcall-hero small{font-size:10px;color:rgba(255,255,255,.7)}
@keyframes bixcall-float{50%{transform:scale(1.05) translateY(-3px)}}
@media (prefers-reduced-motion:reduce){.bixcall-hero img{animation:none}}
.bixcall-back:active{transform:scale(.94)}
.bixcall-notify{display:block;margin:0 auto 12px;padding:8px 14px;border-radius:999px;font-size:11px;font-weight:700;color:#FFD700;background:rgba(8,6,14,.7);border:1px solid rgba(255,215,0,.35)}
.site-header[hidden],footer[hidden]{display:none!important}
.comm-msgs p.is-media{padding:6px}
.comm-img{display:block;max-width:220px;max-height:280px;border-radius:12px;object-fit:cover}
.comm-audio{max-width:230px;height:36px}
.comm-media-wait{font-size:11px;opacity:.7}
.comm-paycard{display:flex;flex-direction:column;gap:2px;padding:10px 14px;border-radius:12px;background:linear-gradient(135deg,color-mix(in oklab,#FFD700 22%,transparent),color-mix(in oklab,#A855F7 18%,transparent));border:1px solid color-mix(in oklab,#FFD700 50%,transparent)}
.comm-paycard b{color:#FFD700;font-size:15px}.comm-paycard small{font-size:10px;opacity:.8}
.comm-rec{flex:1;display:flex;align-items:center;gap:8px;font-size:12px;color:#f87171}
.comm-rec i{width:9px;height:9px;border-radius:50%;background:#ef4444;animation:pulse 1s infinite}
.comm-compose button.is-rec{background:#ef4444!important;color:#fff}
.comm-busy{text-align:center;font-size:11px;opacity:.7}
.comm-payform{margin:0 12px 8px;padding:12px;border-radius:16px;display:grid;gap:8px;background:color-mix(in oklab,var(--card) 90%,transparent);border:1px solid color-mix(in oklab,#FFD700 40%,transparent)}
.comm-payform>div{display:flex;gap:8px;justify-content:flex-end}.comm-payform small{font-size:10px;opacity:.7}

/* BIX CALL dialpad, quick replies, ringtone */
.comm-dial-num{display:flex;align-items:center;gap:.4rem;border-bottom:1px solid color-mix(in oklab,var(--primary) 30%,transparent);padding-bottom:.4rem}
.comm-dial-num input{flex:1;min-width:0;background:transparent;border:0;outline:0;text-align:center;font-size:1.35rem;letter-spacing:.12em;font-weight:700;color:var(--foreground)}
.comm-dial-num button{color:var(--muted-foreground);font-size:1.1rem;padding:0 .3rem}
.comm-dial-pad{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem;margin:.75rem auto 0;max-width:16rem}
.comm-dial-pad button{aspect-ratio:1.35;border-radius:999px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:color-mix(in oklab,var(--card) 80%,transparent);border:1px solid color-mix(in oklab,var(--primary) 22%,transparent);transition:transform .1s,background .15s}
.comm-dial-pad button:active{transform:scale(.92);background:color-mix(in oklab,var(--primary) 22%,var(--card))}
.comm-dial-pad b{font-size:1.25rem;line-height:1}.comm-dial-pad small{font-size:.5rem;letter-spacing:.14em;color:var(--muted-foreground);min-height:.6rem}
.comm-dial-go{margin:.75rem auto 0;display:flex;align-items:center;justify-content:center;gap:.4rem;width:100%;max-width:16rem;padding:.65rem;border-radius:999px;font-weight:800;font-size:.8rem;background:linear-gradient(135deg,var(--primary),color-mix(in oklab,var(--primary) 60%,var(--accent)));color:var(--primary-foreground)}
.comm-dial-go:disabled{opacity:.45}
.comm-quick{display:flex;gap:.35rem;overflow-x:auto;padding:.35rem .75rem;scrollbar-width:none}
.comm-quick::-webkit-scrollbar{display:none}
.comm-quick button{flex:none;font-size:.7rem;padding:.3rem .65rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--primary) 30%,transparent);background:color-mix(in oklab,var(--card) 85%,transparent)}
.comm-ring{display:flex;align-items:center;gap:.5rem}.comm-ring input{flex:1;accent-color:var(--primary)}
.comm-ring span{font-size:.7rem;min-width:2.6rem;text-align:right}.comm-ring button{font-size:.7rem;padding:.25rem .6rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--primary) 35%,transparent)}

/* BIX CHAT — presence, reply, forward, delete */
.comm-ava.is-online{position:relative}
.comm-ava.is-online::after{content:"";position:absolute;right:-1px;bottom:-1px;width:.6rem;height:.6rem;border-radius:50%;background:oklch(0.75 0.17 155);border:2px solid oklch(0.14 0.02 300)}
.comm-status{letter-spacing:.04em;text-transform:none;font-size:10px}
.comm-status.is-off i{background:oklch(0.6 0 0);box-shadow:none;animation:none}
.comm-status.is-typing{color:oklch(0.85 0.15 85)}
.comm-status.is-typing i{background:oklch(0.85 0.15 85);box-shadow:0 0 8px oklch(0.85 0.15 85)}
.comm-msgs>p{position:relative;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
.comm-msgs>p.is-deleted{font-style:italic;opacity:.6;background:transparent;border-style:dashed}
.comm-more{position:absolute;top:2px;right:4px;font-size:12px;line-height:1;padding:0 4px;opacity:0;color:inherit;transition:opacity .15s}
.comm-msgs>p:hover .comm-more,.comm-more:focus-visible{opacity:.8}
@media (hover:none){.comm-more{display:none}}
