.bxpad-fab{background:radial-gradient(circle at 32% 22%,#2b2140 0%,#07070b 70%);border:1px solid transparent;background-clip:padding-box;box-shadow:0 0 0 1px rgb(255 215 0 / .7),0 0 0 4px rgb(255 215 0 / .08),0 0 0 5px rgb(255 215 0 / .3),0 10px 28px rgb(0 0 0 / .6),0 0 22px rgb(168 85 247 / .35);transition:transform .15s}
.bxpad-fab:active{transform:scale(.9)}
.bxpad-board{background:linear-gradient(135deg,#FFD700,#b8860b 35%,#A855F7 80%);box-shadow:0 0 24px rgb(168 85 247 / .18)}
.bxpad-board textarea{background:linear-gradient(180deg,#0c0a12,#07070a)}
.bxpad-chip{background:linear-gradient(160deg,rgb(255 255 255 / .05),rgb(255 255 255 / .01));border:1px solid rgb(220 220 230 / .14);backdrop-filter:blur(10px)}
.bxpad-chip.is-on{border-color:rgb(255 215 0 / .6);box-shadow:inset 0 0 12px rgb(255 215 0 / .12)}
.bxpad .is-gold,.comm-dial-go{background:linear-gradient(110deg,#a9781a,#FFD700 30%,#fff3b0 45%,#FFD700 60%,#a9781a);background-size:220% 100%;animation:bxLuxSheen 4.5s linear infinite;color:#1a1204!important;font-weight:800;border:0;box-shadow:0 6px 18px rgb(255 215 0 / .25)}
/* Bubbles */
.comm-msgs>p{background:linear-gradient(160deg,rgb(30 30 38 / .85),rgb(14 14 20 / .85));border:1px solid rgb(210 214 226 / .16);backdrop-filter:blur(12px);box-shadow:0 4px 14px rgb(0 0 0 / .3)}
.comm-msgs>p.is-me{background:linear-gradient(140deg,#24153f,#0e0b1a);border:1px solid rgb(168 85 247 / .3);border-right:2px solid rgb(255 215 0 / .7);box-shadow:0 4px 16px rgb(168 85 247 / .16)}
.comm-tick{color:#FFD700;text-shadow:0 0 6px rgb(255 215 0 / .5)}
.comm-quick button{border-radius:999px;background:rgb(255 255 255 / .04);border:1px solid rgb(255 215 0 / .25);backdrop-filter:blur(10px);transition:transform .12s}
