.comm-room-head{background:linear-gradient(180deg,rgb(10 8 16 / .92),rgb(10 8 16 / .7));backdrop-filter:blur(16px);border-bottom:1px solid rgb(255 215 0 / .18)}
.comm-input{background:#09080d;border:1px solid rgb(255 215 0 / .22)}
