.comm-card{background:linear-gradient(160deg,rgb(24 20 34 / .8),rgb(8 8 12 / .9));border:1px solid rgb(255 215 0 / .14);box-shadow:inset 0 1px 0 rgb(255 255 255 / .05)}
.comm-ava{box-shadow:0 0 0 1.5px rgb(255 215 0 / .55),0 0 0 3px rgb(200 200 210 / .15)}
.comm-online,.comm-ava .on,.comm-ava i{animation:bxLuxBreath 2.4s ease-in-out infinite}
.comm-pay,.comm-req{position:relative;overflow:hidden;background:linear-gradient(135deg,#3a2a06,#16110a 55%,#2b1e3f)!important;border:1px solid rgb(255 215 0 / .55)!important}
.comm-pay::after,.comm-req::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 35%,rgb(255 240 180 / .18) 50%,transparent 65%);background-size:250% 100%;animation:bxLuxSheen 5s linear infinite}
