/* BIXTrade AI personas — bright, clear neural-tech look */
:root { --bot-aegis: oklch(0.82 0.14 210); --bot-nexus: oklch(0.86 0.16 88); --bot-vortex: oklch(0.72 0.22 305); }
.bot3d[data-variant="aegis"]:not([data-mood="sleep"]) { --bc: var(--bot-aegis); }
.bot3d[data-variant="nexus"]:not([data-mood="sleep"]) { --bc: var(--bot-nexus); }
.bot3d[data-variant="vortex"]:not([data-mood="sleep"]) { --bc: var(--bot-vortex); }
.bot3d { --metal: color-mix(in oklab, var(--foreground) 34%, var(--card)); }
.bot3d-grid { position:absolute; left:-10%; right:-10%; bottom:-4%; height:42%; transform:perspective(260px) rotateX(64deg); transform-origin:bottom; background-image:linear-gradient(color-mix(in oklab, var(--bc) 55%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in oklab, var(--bc) 55%, transparent) 1px, transparent 1px); background-size:18px 18px; mask-image:radial-gradient(ellipse at 50% 30%, #000 20%, transparent 70%); animation:bot3d-grid 2.4s linear infinite; pointer-events:none; }
.bot3d[data-mood="trade"] .bot3d-grid { animation-duration:.7s; }
.bot3d[data-mood="sleep"] .bot3d-grid { animation:none; opacity:.35; }
.bot3d-orbit.o3 { inset:-2% 18%; border-style:dotted; transform:rotateY(70deg) rotateX(20deg); animation-duration:8s; }
.bot3d-net { position:absolute; inset:0; pointer-events:none; }
.bot3d-net i { position:absolute; left:50%; top:50%; width:5px; height:5px; border-radius:50%; background:var(--bc); box-shadow:0 0 8px var(--bc); transform:rotate(calc(var(--i) * 45deg)) translateX(46%); transform-origin:0 0; animation:bot3d-node 3s ease-in-out infinite; animation-delay:calc(var(--i) * -.37s); }
.bot3d-net i::after { content:""; position:absolute; right:100%; top:2px; width:60px; height:1px; background:linear-gradient(90deg, transparent, var(--bc)); opacity:.6; }
.bot3d[data-mood="sleep"] .bot3d-net { opacity:.25; }
.bot3d-core { backdrop-filter:blur(2px); background:radial-gradient(circle at 35% 30%, color-mix(in oklab, var(--foreground) 70%, transparent), color-mix(in oklab, var(--bc) 60%, transparent) 40%, color-mix(in oklab, var(--background) 60%, transparent)) !important; box-shadow:0 0 16px var(--bc), inset 0 0 10px var(--bc) !important; }
.bot3d[data-variant="aegis"] .bot3d-torso { clip-path:polygon(15% 0,85% 0,100% 30%,85% 100%,15% 100%,0 30%); }
.bot3d[data-variant="vortex"] .bot3d-head { border-radius:50% 50% 24% 24% / 60% 60% 40% 40%; }
.bot3d[data-variant="vortex"] .bot3d-orbit { border-width:2px; }
.bot3d.is-mini { width:100%; max-width:92px; margin:0 auto; cursor:default; }
.bot3d.is-mini .bot3d-ant::after { animation:none; }
@keyframes bot3d-grid { to { background-position:0 18px; } }
@keyframes bot3d-node { 0%,100% { opacity:.25; scale:.7; } 50% { opacity:1; scale:1.2; } }

