/* BIX CALL — 4 core buttons with labels, camera flip overlay, video invite, incoming buzz */
.bixcall-ctl>.bc-ctl4{width:auto;height:auto;border-radius:0;background:none;border:0;box-shadow:none;display:flex;gap:18px;place-items:initial}
.bc-ctl4 label{display:flex;flex-direction:column;align-items:center;gap:5px;cursor:pointer}
.bc-ctl4 button{width:56px;height:56px;border-radius:50%;display:grid;place-items:center;color:#fff;background:linear-gradient(160deg,rgb(48 46 58 / .9),rgb(16 15 22 / .95));border:1px solid rgb(210 214 226 / .2);box-shadow:inset 0 1px 0 rgb(255 255 255 / .1),0 4px 10px rgb(0 0 0 / .4);transition:transform .15s,box-shadow .2s}
.bc-ctl4 button:active{transform:scale(.92)}
.bc-ctl4 button.off{background:linear-gradient(160deg,#f1f5f9,#cbd5e1);color:#0b0812}
.bc-ctl4 button.shield{color:#FFD700;border-color:rgb(255 215 0 / .7);box-shadow:0 0 14px rgb(255 215 0 / .35)}
.bc-ctl4 button.end{background:linear-gradient(145deg,#ef4444,#991b1b);border:2px solid #FFD700}
.bc-ctl4 span{font-size:10.5px;font-weight:700;letter-spacing:.02em;color:rgb(255 255 255 / .78)}
@media (max-width:380px){.bixcall-ctl>.bc-ctl4{gap:12px}.bc-ctl4 button{width:50px;height:50px}}
.bixcall-flip{position:absolute;z-index:4;top:calc(max(14px,env(safe-area-inset-top)) + 60px);right:14px;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;color:#FFD700;background:rgba(8,6,14,.7);border:1px solid rgba(255,215,0,.45);backdrop-filter:blur(10px);transition:opacity .25s}
.bixcall.is-hidden .bixcall-flip,.bixcall.is-hidden .bc-vid-invite{opacity:0;pointer-events:none}
.bc-vid-invite{position:absolute;z-index:5;left:50%;bottom:calc(max(28px,env(safe-area-inset-bottom)) + 104px);transform:translateX(-50%);max-width:92vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;animation:bcInvite .35s ease-out}
@keyframes bcInvite{from{opacity:0;transform:translate(-50%,10px)}to{opacity:1;transform:translate(-50%,0)}}
.bixcall-av.is-buzz{animation:bcBuzz 3.2s infinite}
@keyframes bcBuzz{0%,100%{transform:none}2%,6%,10%,14%,18%{transform:translateX(-3px) rotate(-1.5deg)}4%,8%,12%,16%,20%{transform:translateX(3px) rotate(1.5deg)}22%,31%,40%{transform:translateX(-2px)}26%,35%{transform:translateX(2px)}44%{transform:none}}
@media (prefers-reduced-motion:reduce){.bixcall-av.is-buzz{animation:none}}

/* ===== Power saver + responsive polish (global) ===== */
html[data-app-hidden="1"] *, html[data-app-hidden="1"] *::before, html[data-app-hidden="1"] *::after, .ps-off, .ps-off * { animation-play-state: paused !important; }
html[data-low-power="1"] *, html[data-low-power="1"] *::before, html[data-low-power="1"] *::after { animation-iteration-count: 1 !important; }
html[data-low-power="1"] .site-header, html[data-low-power="1"] .trust-strip div, html[data-low-power="1"] .tokenomics-allocation, html[data-low-power="1"] .tokenomics-purpose > div, html[data-low-power="1"] .reactor-glass-lens, html[data-low-power="1"] .bxt-nav { backdrop-filter: none !important; }
@media (max-width: 640px) {
  .site-header, .trust-strip div, .tokenomics-allocation, .tokenomics-purpose > div, .reactor-landing .hero-section .grid > div { backdrop-filter: blur(6px); }
  img, video, canvas, svg { max-width: 100%; }
  h1 { overflow-wrap: anywhere; }
}
button, a, [role="button"], input, select, textarea, label { touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
[role="dialog"] { max-height: min(92dvh, 100%); overflow-y: auto; overscroll-behavior: contain; }
.network-tree-panel, .settings-section, .content-carousel-track > * { content-visibility: auto; contain-intrinsic-size: auto 320px; }
input, select, textarea { font-size: max(16px, 1em); }

/* Copy feedback + compact phone density */
[data-copied="1"] { background: oklch(0.72 0.17 155) !important; color: oklch(0.15 0 0) !important; transition: background .2s; }
[data-copied="1"] .copy-label { font-size: 0; }
[data-copied="1"] .copy-label::after { content: "Tersalin ✓"; font-size: .8rem; }
@media (max-width: 390px) and (max-height: 760px) {
  main .space-y-6 > * + * { margin-top: 1.1rem !important; }
  main .space-y-5 > * + * { margin-top: 0.95rem !important; }
  main .gap-6 { gap: 1.1rem !important; }
  main .p-6 { padding: 1.1rem !important; }
  main .py-8 { padding-top: 1.4rem !important; padding-bottom: 1.4rem !important; }
}
@media (prefers-reduced-motion: reduce) {
  .bixtrade-bot, [class*="bot3d"] { animation: none !important; transform: none !important; }
}

/* Content protection: lock text/image selection except whitelisted copyable areas */
body { -webkit-user-select: none; user-select: none; -webkit-touch-callout: none; }
img, video, svg { -webkit-user-drag: none; user-drag: none; }
input, textarea, select, [contenteditable="true"], .allow-select, .allow-select *,
code, pre, .numeric.select-all, .select-all, .select-text, [data-copyable], [data-copyable] *,
.chat-bubble, .chat-bubble *, [class*="msg-bubble"], [class*="msg-bubble"] *,
.break-all, .font-mono, [class*="ref-link"], [class*="referral"] [class*="code"], [class*="member-code"] {
  -webkit-user-select: text; user-select: text; -webkit-touch-callout: default;
}

/* ===== P2P live trading desk ===== */
.p2p-panel { border: 1px solid color-mix(in oklab, var(--border) 80%, transparent); background: linear-gradient(160deg, color-mix(in oklab, var(--card) 96%, var(--chart-3) 4%), var(--card)); border-radius: 1.1rem; padding: 1rem; }
.p2p-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .5rem; }
@media (min-width: 768px) { .p2p-stats { grid-template-columns: 1.4fr 1fr 1fr 1fr; } }
.p2p-stat { border: 1px solid color-mix(in oklab, var(--border) 70%, transparent); background: var(--card); border-radius: .9rem; padding: .65rem .8rem; display: grid; gap: .1rem; min-width: 0; }
.p2p-stat span { font-size: .6rem; letter-spacing: .14em; color: var(--muted-foreground); font-weight: 700; }
.p2p-stat b { font-size: 1rem; display: inline-flex; align-items: center; gap: .2rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.p2p-stat small { font-size: .65rem; color: var(--muted-foreground); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.p2p-stat--main { grid-column: span 2; border-color: color-mix(in oklab, var(--chart-3) 45%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--chart-3) 10%, transparent), 0 10px 30px -18px var(--chart-3); }
.p2p-stat--main b { font-size: 1.6rem; }
@media (min-width: 768px) { .p2p-stat--main { grid-column: auto; } }
.p2p-escrow { grid-column: 1 / -1; display: flex; align-items: center; gap: .4rem; font-size: .68rem; color: var(--muted-foreground); padding: .1rem .2rem; }
.p2p-escrow svg { color: var(--chart-2); flex-shrink: 0; }
.p2p-live { margin-left: auto; display: inline-flex; align-items: center; gap: .3rem; font-weight: 800; letter-spacing: .14em; color: var(--chart-2); }
.p2p-live i { width: .45rem; height: .45rem; border-radius: 999px; background: var(--chart-2); animation: p2pPulse 1.6s ease-in-out infinite; }
@keyframes p2pPulse { 0%,100% { opacity: 1; box-shadow: 0 0 0 0 color-mix(in oklab, var(--chart-2) 60%, transparent); } 50% { opacity: .55; box-shadow: 0 0 0 5px transparent; } }
.p2p-ticker { overflow: hidden; border-block: 1px solid color-mix(in oklab, var(--border) 70%, transparent); background: color-mix(in oklab, var(--card) 85%, transparent); border-radius: .7rem; mask-image: linear-gradient(90deg, transparent, #000 6%, #000 94%, transparent); }
.p2p-ticker--empty { display: flex; align-items: center; gap: .4rem; padding: .55rem .8rem; font-size: .72rem; color: var(--muted-foreground); mask-image: none; }
.p2p-ticker-track { display: flex; width: max-content; animation: p2pTicker 40s linear infinite; }
.p2p-ticker:hover .p2p-ticker-track { animation-play-state: paused; }
@keyframes p2pTicker { to { transform: translateX(-50%); } }
.p2p-tick { display: inline-flex; align-items: center; gap: .3rem; padding: .55rem 1rem; font-size: .72rem; white-space: nowrap; border-right: 1px solid color-mix(in oklab, var(--border) 60%, transparent); }
.p2p-tick em { font-style: normal; color: var(--muted-foreground); font-size: .65rem; }
.p2p-tick.is-fresh, .p2p-card.is-fresh { animation: p2pFlash 1.6s ease-out; }
@keyframes p2pFlash { 0% { background-color: color-mix(in oklab, var(--chart-3) 28%, transparent); } 100% { background-color: transparent; } }
.p2p-modes, .p2p-side, .p2p-filter { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: .3rem; padding: .25rem; border-radius: .9rem; background: color-mix(in oklab, var(--muted) 60%, transparent); }
.p2p-modes button, .p2p-side button, .p2p-filter button { min-height: 2.6rem; border-radius: .7rem; font-size: .8rem; font-weight: 700; color: var(--muted-foreground); display: inline-flex; align-items: center; justify-content: center; gap: .35rem; transition: background .2s, color .2s; }
.p2p-modes button.is-on, .p2p-filter button.is-on { background: var(--card); color: var(--chart-3); box-shadow: 0 4px 14px -8px var(--chart-3); }
.p2p-side button.is-on.is-buy { background: var(--chart-2); color: var(--background); }
.p2p-side button.is-on.is-sell { background: var(--destructive); color: var(--destructive-foreground, var(--background)); }
.p2p-express { max-width: 32rem; width: 100%; margin-inline: auto; }
.p2p-amount { display: grid; gap: .3rem; margin-top: .6rem; font-size: .7rem; color: var(--muted-foreground); }
.p2p-amount input { width: 100%; background: transparent; border: 1px solid var(--border); border-radius: .9rem; padding: .7rem .9rem; font-size: 1.6rem; font-weight: 800; color: var(--foreground); font-variant-numeric: tabular-nums; }
.p2p-amount input:focus { outline: none; border-color: var(--chart-3); }
.p2p-quick { display: grid; grid-template-columns: repeat(4, 1fr); gap: .35rem; margin-top: .5rem; }
.p2p-quick button { min-height: 2.3rem; border: 1px solid var(--border); border-radius: .6rem; font-size: .75rem; font-weight: 700; }
.p2p-quick button:disabled { opacity: .4; }
.p2p-quote { margin-top: .8rem; border-radius: .9rem; padding: .7rem .85rem; background: color-mix(in oklab, var(--muted) 45%, transparent); display: grid; gap: .3rem; }
.p2p-quote div { display: flex; justify-content: space-between; font-size: .8rem; }
.p2p-quote span { color: var(--muted-foreground); }
.p2p-quote small { font-size: .65rem; color: var(--muted-foreground); }
.p2p-quote--empty { font-size: .75rem; color: var(--muted-foreground); }
.p2p-go { width: 100%; margin-top: .8rem; min-height: 3rem; font-weight: 800; letter-spacing: .02em; }
.p2p-card-row .p2p-go { width: auto; margin-top: 0; min-height: 2.3rem; padding-inline: 1.2rem; }
.p2p-go.is-buy { background: var(--chart-2); color: var(--background); }
.p2p-go.is-sell { background: var(--destructive); color: var(--destructive-foreground, var(--background)); }
.p2p-card { position: relative; overflow: hidden; border: 1px solid color-mix(in oklab, var(--border) 70%, transparent); border-radius: .9rem; padding: .7rem .8rem; display: grid; gap: .5rem; }
.p2p-depth { position: absolute; inset-block: 0; right: 0; pointer-events: none; opacity: .14; }
.p2p-depth.is-ask { background: var(--destructive); }
.p2p-depth.is-bid { background: var(--chart-2); }
.p2p-merchant { position: relative; display: flex; align-items: center; gap: .55rem; }
.p2p-merchant b { font-size: .8rem; }
.p2p-merchant small, .p2p-card-row small { display: block; font-size: .65rem; color: var(--muted-foreground); }
.p2p-avatar { width: 2rem; height: 2rem; border-radius: 999px; display: grid; place-items: center; font-size: .7rem; font-weight: 800; background: color-mix(in oklab, var(--chart-3) 22%, var(--card)); color: var(--chart-3); flex-shrink: 0; }
.p2p-card-row { position: relative; display: flex; align-items: center; justify-content: space-between; gap: .6rem; }
.p2p-buyback { display: flex; align-items: center; justify-content: space-between; border: 1px solid color-mix(in oklab, var(--chart-3) 55%, transparent); border-radius: 1rem; padding: .75rem 1rem; font-size: .8rem; font-weight: 800; color: var(--chart-3); background: var(--card); }
@media (prefers-reduced-motion: reduce) { .p2p-ticker-track, .p2p-live i, .p2p-tick.is-fresh, .p2p-card.is-fresh { animation: none; } .p2p-ticker { overflow-x: auto; } }

/* P2P box layout + demo pool */
.p2p-pool { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: .5rem; padding: .6rem; border-radius: 1rem; border: 1px dashed color-mix(in oklab, var(--primary) 45%, transparent); background: color-mix(in oklab, var(--primary) 7%, var(--card)); }
@media (min-width: 768px) { .p2p-pool { grid-template-columns: repeat(4, minmax(0,1fr)); } }
.p2p-pool > div { display: grid; gap: .1rem; min-width: 0; }
.p2p-pool span { font-size: .58rem; letter-spacing: .12em; font-weight: 700; color: var(--muted-foreground); }
.p2p-pool b { font-size: .95rem; }
.p2p-pool small { font-size: .62rem; color: var(--muted-foreground); }
.p2p-boxes { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: .55rem; }
.p2p-box { display: grid; justify-items: start; gap: .15rem; padding: .85rem; border-radius: 1rem; border: 1px solid color-mix(in oklab, var(--border) 70%, transparent); background: var(--card); text-align: left; min-height: 88px; transition: transform .15s; }
.p2p-box:active { transform: scale(.97); }
.p2p-box b { font-size: .9rem; letter-spacing: .06em; }
.p2p-box small { font-size: .65rem; color: var(--muted-foreground); }
.p2p-box.is-buy { border-color: color-mix(in oklab, var(--chart-2) 55%, transparent); background: color-mix(in oklab, var(--chart-2) 12%, var(--card)); color: var(--chart-2); }
.p2p-box.is-sell { border-color: color-mix(in oklab, var(--destructive) 55%, transparent); background: color-mix(in oklab, var(--destructive) 12%, var(--card)); color: var(--destructive); }
.p2p-feed ul { display: grid; gap: .3rem; }
.p2p-feed li { display: grid; grid-template-columns: 4.2rem minmax(0,1fr) auto auto 3.4rem; gap: .4rem; align-items: center; font-size: .7rem; padding: .4rem .5rem; border-radius: .6rem; background: color-mix(in oklab, var(--muted) 35%, transparent); }
.p2p-feed li.is-fresh { animation: p2pFeedIn .8s ease-out; }
.p2p-feed em { font-style: normal; font-size: .55rem; font-weight: 800; text-align: center; border-radius: 999px; padding: .1rem .3rem; }
.p2p-feed em.is-demo { color: var(--muted-foreground); border: 1px solid var(--border); }
.p2p-feed em.is-real { color: var(--chart-2); border: 1px solid var(--chart-2); }
@keyframes p2pFeedIn { from { background: color-mix(in oklab, var(--primary) 30%, transparent); transform: translateY(-4px); } }
@media (max-width: 390px) { .p2p-feed li { grid-template-columns: 3.6rem minmax(0,1fr) auto 3rem; } .p2p-feed li > span:nth-child(4) { display: none; } }

/* P2P institutional HUD */
.p2p-hud { display: grid; gap: .6rem; padding: .85rem; border-radius: 1.1rem; border: 1px solid color-mix(in oklab, var(--chart-3) 40%, transparent); background: linear-gradient(160deg, color-mix(in oklab, var(--chart-3) 9%, var(--card)), var(--card) 60%); box-shadow: 0 14px 34px -22px var(--chart-3); }
.p2p-hud header, .p2p-hud footer { display: flex; align-items: center; justify-content: space-between; gap: .4rem; font-size: .6rem; letter-spacing: .14em; font-weight: 800; }
.p2p-hud-brand { display: inline-flex; gap: .3rem; align-items: center; color: var(--chart-3); }
.p2p-hud-price { display: grid; gap: .05rem; padding-bottom: .55rem; border-bottom: 1px solid color-mix(in oklab, var(--chart-3) 22%, transparent); }
.p2p-hud-price span, .p2p-hud-grid span { font-size: .56rem; letter-spacing: .14em; font-weight: 700; color: var(--muted-foreground); }
.p2p-hud-price b { font-size: 1.9rem; display: inline-flex; align-items: center; gap: .2rem; line-height: 1.1; }
.p2p-hud-price small, .p2p-hud-grid small { font-size: .62rem; color: var(--muted-foreground); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.p2p-hud-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: .5rem; }
.p2p-hud-grid > div { display: grid; min-width: 0; }
.p2p-hud-grid > div + div { border-left: 1px solid color-mix(in oklab, var(--border) 70%, transparent); padding-left: .5rem; }
.p2p-hud-grid b { font-size: .92rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.p2p-hud footer { justify-content: flex-start; letter-spacing: .06em; font-weight: 600; color: var(--muted-foreground); padding-top: .1rem; }
.p2p-hud footer svg { color: var(--chart-2); }
/* P2P unified cockpit hero */
.trade-chip { border: 1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); border-radius: 999px; padding: .25rem .55rem; font-size: .55rem; font-weight: 800; letter-spacing: .12em; color: var(--chart-3); background: color-mix(in oklab, var(--chart-3) 8%, transparent); }
.p2p-hud-ref { font-style: normal; font-size: .62rem; color: var(--muted-foreground); display: inline-flex; gap: .35rem; align-items: center; }
.p2p-hud-ref i { font-style: normal; font-weight: 800; color: var(--chart-3); border: 1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); border-radius: 999px; padding: 0 .4rem; }
.p2p-spark { width: 100%; height: 44px; display: block; }
.p2p-hud-engine { display: flex; align-items: center; gap: .35rem; font-size: .56rem; letter-spacing: .1em; font-weight: 800; color: var(--chart-2); margin-top: -.3rem; }
.p2p-hud-engine i { width: 6px; height: 6px; border-radius: 99px; background: var(--chart-2); box-shadow: 0 0 8px var(--chart-2); animation: p2pBlink 1.4s infinite; }
@keyframes p2pBlink { 50% { opacity: .3; } }
.p2p-tape { overflow: hidden; border-block: 1px solid color-mix(in oklab, var(--chart-3) 20%, transparent); padding: .3rem 0; mask-image: linear-gradient(90deg, transparent, #000 8%, #000 92%, transparent); }
.p2p-tape-track { display: flex; width: max-content; gap: 1.2rem; animation: p2pTape 40s linear infinite; }
.p2p-tape-item { display: inline-flex; gap: .3rem; font-size: .62rem; white-space: nowrap; color: var(--muted-foreground); font-variant-numeric: tabular-nums; }
@keyframes p2pTape { to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .p2p-tape-track, .p2p-hud-engine i { animation: none; } }

/* Lux disclosure deed + network tabs */
.lux-deed{margin-top:1rem;border:1px solid color-mix(in oklab,var(--chart-3) 40%,transparent);border-radius:1rem;padding:.9rem 1rem;background:linear-gradient(160deg,color-mix(in oklab,var(--card) 92%,var(--chart-3) 8%),var(--card));box-shadow:inset 0 1px 0 color-mix(in oklab,var(--chart-3) 25%,transparent)}
.lux-deed-head{display:flex;align-items:center;gap:.4rem;font-size:10px;font-weight:800;letter-spacing:.14em;color:var(--chart-3);padding-bottom:.55rem;border-bottom:1px solid color-mix(in oklab,var(--chart-3) 22%,transparent)}
.lux-deed ul{margin:.6rem 0 0;padding:0;list-style:none;display:grid;gap:.55rem}
.lux-deed li{display:grid;gap:.1rem;padding-left:.8rem;border-left:2px solid color-mix(in oklab,var(--chart-2) 60%,transparent)}
.lux-deed li b{font-size:12px;color:var(--foreground)}
.lux-deed li span{font-size:12px;line-height:1.5;color:color-mix(in oklab,var(--foreground) 78%,transparent)}
.nx-tabs{position:sticky;top:0;z-index:20;margin-top:1rem;display:grid;grid-template-columns:repeat(3,1fr);gap:.3rem;padding:.3rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--chart-3) 35%,transparent);background:color-mix(in oklab,var(--card) 88%,transparent);backdrop-filter:blur(10px)}
.nx-tabs button{display:flex;align-items:center;justify-content:center;gap:.35rem;min-height:40px;border-radius:999px;font-size:12px;font-weight:800;letter-spacing:.04em;color:var(--muted-foreground)}
.nx-tabs button[aria-selected="true"]{background:linear-gradient(135deg,var(--chart-3),color-mix(in oklab,var(--chart-3) 70%,var(--chart-2)));color:var(--background)}
.nx-tabs em{font-style:normal;font-size:10px;padding:0 .35rem;border-radius:999px;background:color-mix(in oklab,var(--background) 30%,transparent)}

/* Network interactive team + wallet/stake helpers */
.nx-drill{display:inline-block;margin-top:2px;border:1px solid color-mix(in oklab,var(--chart-3) 60%,transparent);border-radius:999px;padding:1px 8px;font-size:10px;font-weight:800;color:var(--chart-3);background:color-mix(in oklab,var(--chart-3) 10%,transparent)}
.nx-earned{display:grid;grid-template-columns:1fr auto;gap:2px 8px;text-align:left;border:1px solid color-mix(in oklab,var(--chart-2) 50%,transparent);border-radius:12px;padding:8px 10px;background:color-mix(in oklab,var(--chart-2) 8%,transparent)}
.nx-earned span{font-size:11px;color:var(--muted-foreground)}.nx-earned b{font-size:12px;color:var(--chart-2);text-align:right}.nx-earned em{grid-column:1/-1;font-style:normal;font-size:10px;font-weight:800;color:var(--chart-3)}
.nx-hist-filter{display:flex;width:100%;justify-content:space-between;gap:8px;border:1px solid color-mix(in oklab,var(--chart-3) 50%,transparent);border-radius:999px;padding:6px 12px;font-size:11px}
