/* Neural Bot Arsenal — full-screen bot stage */
.fleet-open { font-size:11px; font-weight:700; color:var(--chart-3); border:1px solid color-mix(in oklab, var(--chart-3) 45%, transparent); border-radius:999px; padding:4px 10px; }
