.fleet-head { position:sticky; top:0; z-index:2; display:flex; justify-content:space-between; align-items:center; gap:12px; padding:10px 4px 14px; background:linear-gradient(oklch(0.11 0.01 280), oklch(0.11 0.01 280 / .85)); border-bottom:1px solid color-mix(in oklab, var(--primary) 35%, transparent); }
