.bixgo-hero-grid { opacity: .18; background-image: linear-gradient(rgba(46,230,197,.4) 1px, transparent 1px), linear-gradient(90deg, rgba(46,230,197,.4) 1px, transparent 1px); background-size: 22px 22px; mask-image: radial-gradient(circle at 80% 0%, #000, transparent 70%); }
