/* ===== Ecosystem Portal (signed-out gateway) ===== */
.eco-portal{position:relative;min-height:100dvh;overflow:hidden;display:flex;flex-direction:column;align-items:center;padding:16px 16px 32px;background:radial-gradient(circle at 50% 45%,oklch(0.28 0.06 190/.55),transparent 60%),radial-gradient(circle at 80% 10%,oklch(0.35 0.08 85/.25),transparent 45%),oklch(0.11 0.01 220);color:oklch(0.97 0 0)}
.eco-portal-stars{position:absolute;inset:0;background-image:radial-gradient(1px 1px at 20% 30%,oklch(1 0 0/.6),transparent),radial-gradient(1px 1px at 70% 20%,oklch(1 0 0/.5),transparent),radial-gradient(1.5px 1.5px at 40% 80%,oklch(0.85 0.15 85/.6),transparent),radial-gradient(1px 1px at 85% 65%,oklch(0.8 0.14 180/.6),transparent),radial-gradient(1px 1px at 10% 70%,oklch(1 0 0/.4),transparent);animation:ecoTwinkle 6s ease-in-out infinite alternate;pointer-events:none}
.eco-portal-top{position:relative;z-index:2;width:100%;max-width:640px;display:flex;justify-content:space-between;align-items:center}
.eco-portal-brand{display:flex;gap:8px;align-items:center;font-weight:900;letter-spacing:.2em;font-size:13px}
.eco-portal-login{display:flex;gap:6px;align-items:center;font-size:12px;font-weight:700;padding:8px 14px;border-radius:999px;border:1px solid oklch(0.8 0.14 180/.45);background:oklch(0.2 0.02 200/.6);backdrop-filter:blur(10px)}
.eco-portal-head{position:relative;z-index:2;text-align:center;margin-top:28px;animation:ecoRise .9s ease both}
.eco-portal-eyebrow{font-size:10px;letter-spacing:.35em;font-weight:800;color:oklch(0.82 0.14 180)}
.eco-portal-head h1{margin-top:8px;font-size:clamp(26px,7vw,40px);font-weight:900;line-height:1.05}
.eco-portal-head h1 span{color:oklch(0.85 0.15 85);text-shadow:0 0 24px oklch(0.85 0.15 85/.45)}
.eco-portal-head p{margin-top:8px;font-size:13px;color:oklch(0.8 0.01 220)}
.eco-orbit{position:relative;z-index:2;width:min(92vw,420px);aspect-ratio:1;margin-top:18px}
.eco-ring{position:absolute;inset:12%;border-radius:50%;border:1px dashed oklch(0.8 0.14 180/.3);animation:ecoSpin 40s linear infinite}
.eco-ring-2{inset:2%;border:1px solid oklch(0.85 0.15 85/.18);animation-duration:70s;animation-direction:reverse}
.eco-core,.eco-node{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:50%;backdrop-filter:blur(14px);opacity:0;animation:ecoPop .8s cubic-bezier(.2,.9,.3,1.3) both,ecoFloat 5s ease-in-out 1.2s infinite;transition:transform .25s,box-shadow .25s}
.eco-core{left:50%;top:50%;width:44%;aspect-ratio:1;translate:-50% -50%;gap:4px;background:radial-gradient(circle at 35% 30%,oklch(0.4 0.08 185/.9),oklch(0.16 0.02 210/.95));border:2px solid oklch(0.85 0.15 85/.8);box-shadow:0 0 0 6px oklch(0.8 0.14 180/.12),0 0 50px oklch(0.8 0.14 180/.45),inset 0 0 30px oklch(0.85 0.15 85/.2)}
.eco-core::after{content:"";position:absolute;inset:-10px;border-radius:50%;border:2px solid oklch(0.8 0.14 180/.5);animation:ecoPulse 2.4s ease-out infinite}
.eco-core b{font-size:clamp(15px,4.4vw,20px);font-weight:900;letter-spacing:.12em;color:oklch(0.88 0.15 85)}
.eco-core small{font-size:9px;opacity:.8}
.eco-node{width:27%;aspect-ratio:1;gap:2px;background:radial-gradient(circle at 35% 30%,oklch(0.3 0.03 200/.85),oklch(0.14 0.01 220/.9));border:1px solid oklch(0.8 0.14 180/.5);box-shadow:0 0 22px oklch(0.8 0.14 180/.2)}
.eco-node b{font-size:10px;font-weight:900;letter-spacing:.08em}.eco-node small{font-size:8px;opacity:.7}
.eco-node svg{color:oklch(0.85 0.15 85)}
.eco-tl{left:2%;top:4%}.eco-tr{right:2%;top:4%}.eco-bl{left:2%;bottom:4%}.eco-br{right:2%;bottom:4%}
.eco-core:hover,.eco-node:hover{box-shadow:0 0 40px oklch(0.85 0.15 85/.5)}
.eco-portal-actions{position:relative;z-index:2;display:flex;flex-direction:column;gap:10px;align-items:center;margin-top:18px;width:100%;max-width:320px;animation:ecoRise 1s ease 1.8s both}
.eco-cta{width:100%;text-align:center;padding:14px;border-radius:999px;font-weight:900;letter-spacing:.1em;font-size:13px;background:linear-gradient(135deg,oklch(0.88 0.15 85),oklch(0.72 0.14 70));color:oklch(0.15 0.01 220);box-shadow:0 10px 30px oklch(0.85 0.15 85/.35)}
.eco-landing{width:100%;display:flex;gap:6px;justify-content:center;align-items:center;padding:12px;border-radius:16px;font-size:12px;font-weight:800;letter-spacing:.2em;border:1px solid oklch(0.8 0.14 180/.45);background:oklch(0.18 0.02 210/.7)}
@keyframes ecoPop{from{opacity:0;scale:.3;filter:blur(8px)}to{opacity:1;scale:1;filter:none}}
@keyframes ecoFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes ecoPulse{from{opacity:.8;scale:1}to{opacity:0;scale:1.35}}
@keyframes ecoSpin{to{rotate:360deg}}
@keyframes ecoRise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes ecoTwinkle{from{opacity:.5}to{opacity:1}}
@media (prefers-reduced-motion:reduce){.eco-portal *{animation-duration:.01ms!important;animation-iteration-count:1!important}}

/* ===== Ecosystem Portal v2: cinematic 3D, slow reveal ===== */
.eco-portal{background:radial-gradient(ellipse at 50% 48%,oklch(0.26 0.06 190/.5),transparent 62%),radial-gradient(circle at 85% 8%,oklch(0.4 0.09 85/.18),transparent 45%),oklch(0.08 0.008 220);animation:ecoFadeIn 1.6s ease both}
.eco-portal-nebula{position:absolute;inset:-20%;background:conic-gradient(from 0deg at 50% 50%,transparent,oklch(0.75 0.13 185/.08),transparent 30%,oklch(0.85 0.15 85/.06),transparent 60%);filter:blur(40px);animation:ecoSpin 90s linear infinite;pointer-events:none}
.eco-portal-head{animation:ecoRiseSoft 1.6s cubic-bezier(.22,.8,.2,1) .2s both}
.eco-core,.eco-node{animation:ecoReveal 1.8s cubic-bezier(.22,.8,.2,1) both,ecoDrift 7s ease-in-out infinite;perspective:600px}
.eco-core{gap:2px;background:radial-gradient(circle at 32% 25%,oklch(1 0 0/.18),transparent 30%),radial-gradient(circle at 50% 60%,oklch(0.32 0.07 185/.9),oklch(0.1 0.01 215/.96) 75%);border:1.5px solid oklch(0.85 0.15 85/.7);box-shadow:inset 0 -18px 40px oklch(0 0 0/.55),inset 0 10px 24px oklch(1 0 0/.08),0 0 0 8px oklch(0.8 0.14 180/.07),0 30px 60px oklch(0 0 0/.6),0 0 70px oklch(0.8 0.14 180/.35)}
.eco-core::after{animation:ecoPulse 4s ease-out infinite}
.eco-node{background:radial-gradient(circle at 30% 22%,oklch(1 0 0/.16),transparent 32%),radial-gradient(circle at 50% 65%,oklch(0.24 0.03 200/.9),oklch(0.09 0.01 220/.95) 78%);border:1px solid oklch(0.8 0.14 180/.4);box-shadow:inset 0 -12px 26px oklch(0 0 0/.55),0 18px 34px oklch(0 0 0/.55),0 0 26px oklch(0.8 0.14 180/.18)}
.eco-3d{width:58%;height:auto;margin-bottom:2px;filter:drop-shadow(0 8px 14px oklch(0 0 0/.6)) drop-shadow(0 0 12px oklch(0.8 0.14 180/.35));animation:ecoTilt 6s ease-in-out infinite}
.eco-3d-core{width:52%}
.eco-node b{font-size:9.5px}
.eco-portal-actions{animation:ecoRiseSoft 1.6s cubic-bezier(.22,.8,.2,1) 3.6s both}
@keyframes ecoFadeIn{from{opacity:0}to{opacity:1}}
@keyframes ecoReveal{from{opacity:0;scale:.86;filter:blur(14px)}to{opacity:1;scale:1;filter:none}}
@keyframes ecoRiseSoft{from{opacity:0;transform:translateY(22px);filter:blur(6px)}to{opacity:1;transform:none;filter:none}}
@keyframes ecoDrift{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes ecoTilt{0%,100%{transform:rotateY(-10deg) rotateX(4deg)}50%{transform:rotateY(10deg) rotateX(-4deg) translateY(-2px)}}

/* ===== Ecosystem Portal v3: Sovereign Reactor cinematic ===== */
.eco-v3{background:radial-gradient(ellipse at 50% 52%,oklch(0.22 0.06 190/.45),transparent 60%),oklch(0.04 0 0)}
.eco-v3 .eco-portal-top{animation:ecoRiseSoft 1.4s ease 3.6s both}
.eco-warp{position:absolute;left:50%;top:52%;width:0;height:0;z-index:3;pointer-events:none}
.eco-warp i{position:absolute;left:-40px;top:-40px;width:80px;height:80px;border-radius:50%;border:1.5px solid oklch(0.85 0.15 85/.8);box-shadow:0 0 18px oklch(0.8 0.14 180/.6),inset 0 0 12px oklch(0.85 0.15 85/.4);opacity:0;animation:ecoWarp 1.6s cubic-bezier(.5,0,.8,.4) both}
.eco-warp i:nth-child(even){border-color:oklch(0.82 0.14 180/.8)}
