.eco-v3 .eco-core{background:radial-gradient(circle at 30% 20%,oklch(1 0 0/.28),transparent 26%),radial-gradient(circle at 70% 85%,oklch(0.82 0.14 180/.25),transparent 40%),radial-gradient(circle at 50% 55%,oklch(0.2 0.04 195/.92),oklch(0.05 0 0/.97) 78%);border:1px solid oklch(0.88 0.14 85/.75);box-shadow:inset 0 -22px 44px oklch(0 0 0/.7),inset 0 12px 26px oklch(1 0 0/.1),0 0 0 10px oklch(0.85 0.15 85/.05),0 0 90px oklch(0.82 0.14 180/.4),0 0 40px oklch(0.85 0.15 85/.3)}
