.eco-v3 .eco-landing{border:1px solid oklch(0.85 0.15 85/.4);background:oklch(0.08 0 0/.6);backdrop-filter:blur(14px);letter-spacing:.3em;font-size:11px;color:oklch(0.9 0.05 85)}
@keyframes ecoWarp{0%{opacity:0;scale:.05}25%{opacity:1}100%{opacity:0;scale:14}}
