/* BIX CALL signed-out gate — full-screen cyber obsidian */
.bcg{position:relative;min-height:100dvh;display:grid;place-items:center;padding:72px 18px 40px;overflow:hidden;color:#f0fdfa;background:radial-gradient(90% 55% at 50% 18%,rgb(20 184 166 / .28),transparent 62%),radial-gradient(70% 45% at 85% 100%,rgb(255 215 0 / .1),transparent 65%),radial-gradient(60% 40% at 0% 80%,rgb(168 85 247 / .12),transparent 65%),#030807}
.bcg-stars{position:absolute;inset:0;background-image:radial-gradient(1px 1px at 20% 30%,#ccfbf1 50%,transparent),radial-gradient(1px 1px at 70% 15%,#fff 50%,transparent),radial-gradient(1.5px 1.5px at 85% 60%,#5eead4 50%,transparent),radial-gradient(1px 1px at 35% 80%,#ffd700 50%,transparent),radial-gradient(1px 1px at 55% 45%,#fff 50%,transparent);opacity:.55;animation:bcgTw 6s ease-in-out infinite alternate}
@keyframes bcgTw{to{opacity:.2}}
.bcg-wave{position:absolute;left:0;right:0;bottom:8%;height:90px;display:flex;align-items:center;justify-content:center;gap:5px;opacity:.28;pointer-events:none}
.bcg-wave i{width:3px;border-radius:3px;background:linear-gradient(#5eead4,#ffd700);animation:bcgWave 1.3s ease-in-out infinite alternate}
@keyframes bcgWave{from{transform:scaleY(.3)}to{transform:scaleY(1)}}
.bcg-back{position:absolute;top:18px;left:16px;z-index:3;display:inline-flex;gap:6px;align-items:center;padding:8px 14px;border-radius:999px;font-size:12px;letter-spacing:.08em;color:#ccfbf1;background:rgb(8 22 21 / .6);border:1px solid rgb(45 212 191 / .3);backdrop-filter:blur(12px)}
.bcg-card{position:relative;z-index:2;width:100%;max-width:24rem;text-align:center;padding:28px 22px 24px;border-radius:28px;background:linear-gradient(160deg,rgb(10 26 25 / .72),rgb(3 8 7 / .82));border:1px solid rgb(45 212 191 / .28);box-shadow:inset 0 1px 0 rgb(255 215 0 / .25),0 30px 80px rgb(0 0 0 / .6),0 0 60px rgb(45 212 191 / .12);backdrop-filter:blur(18px);animation:bcgIn 1.2s cubic-bezier(.2,.8,.2,1) both}
@keyframes bcgIn{from{opacity:0;transform:translateY(24px) scale(.96);filter:blur(8px)}to{opacity:1;transform:none;filter:none}}
.bcg-orb{position:relative;width:150px;height:150px;margin:-4px auto 10px;display:grid;place-items:center}
.bcg-orb img{width:128px;height:128px;object-fit:contain;filter:drop-shadow(0 12px 30px rgb(45 212 191 / .45));animation:bcgFloat 5s ease-in-out infinite}
@keyframes bcgFloat{50%{transform:translateY(-8px) rotate(2deg)}}
.bcg-ring{position:absolute;inset:0;border-radius:50%;border:1px solid rgb(94 234 212 / .45);border-top-color:#ffd700;animation:bcgSpin 9s linear infinite}
.bcg-ring-2{inset:14px;border-color:rgb(255 215 0 / .25);border-bottom-color:#5eead4;animation-duration:6s;animation-direction:reverse}
@keyframes bcgSpin{to{transform:rotate(360deg)}}
.bcg-title{font-size:2.4rem;font-weight:800;letter-spacing:.06em;line-height:1;background:linear-gradient(100deg,#99f6e4,#2dd4bf 40%,#ffd700 75%,#fff3b0);-webkit-background-clip:text;background-clip:text;color:transparent}
.bcg-sub{margin:10px auto 0;max-width:19rem;font-size:13.5px;line-height:1.5;color:rgb(204 251 241 / .75)}
.bcg-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin:16px 0 20px}
.bcg-chips span{display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:999px;font-size:11px;color:#ccfbf1;background:rgb(45 212 191 / .08);border:1px solid rgb(45 212 191 / .28)}
.bcg-cta,.bcg-ghost{display:block;width:100%;padding:13px;border-radius:999px;font-weight:700;letter-spacing:.06em;font-size:14px}
.bcg-cta{color:#1a1200;background:linear-gradient(135deg,#fff3b0,#ffd700 45%,#c9a227);box-shadow:0 10px 30px rgb(255 215 0 / .3),inset 0 1px 0 #fff8}
.bcg-ghost{margin-top:10px;color:#ccfbf1;background:rgb(255 255 255 / .03);border:1px solid rgb(45 212 191 / .35)}
.bcg-note{display:block;margin-top:14px;font-size:11px;color:rgb(204 251 241 / .5)}
@media (prefers-reduced-motion:reduce){.bcg *,.bcg{animation:none!important}}

/* === BIX CALL dashboard polish: unified header + modern cards === */
.bixcall-page{min-height:100dvh}
.bixcall-page .bc-head{position:sticky;top:0;z-index:25;margin:-6px -12px 12px;padding:8px 12px 10px;border-radius:0 0 24px 24px;background:linear-gradient(180deg,rgb(3 8 7 / .96),rgb(3 8 7 / .72));backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border-bottom:1px solid rgb(45 212 191 / .18);box-shadow:0 12px 30px -18px rgb(0 0 0 / .8)}
.bixcall-page .bc-head .bc-wrap{position:static;margin:0;padding:0;background:none!important;backdrop-filter:none;border-radius:0}
.bixcall-page .comm-card{border-radius:22px;padding:14px;border:1px solid rgb(45 212 191 / .2);background:linear-gradient(160deg,rgb(12 30 28 / .82),rgb(4 10 9 / .9));box-shadow:inset 0 1px 0 rgb(255 255 255 / .06),0 14px 34px -18px rgb(0 0 0 / .7)}
.bixcall-page .comm-h{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#99f6e4;display:flex;align-items:center;gap:8px}
.bixcall-page .comm-h::before{content:"";width:6px;height:6px;border-radius:50%;background:#2dd4bf;box-shadow:0 0 10px #2dd4bf}
.bixcall-page .comm-list{display:flex;flex-direction:column;gap:8px;margin-top:10px}
.bixcall-page .comm-list>li{border:0!important}
.bixcall-page .comm-list>li>button,.bixcall-page .comm-row,.bixcall-page .comm-peer{display:flex;align-items:center;gap:10px;width:100%;padding:10px 12px;border-radius:18px;background:linear-gradient(135deg,rgb(255 255 255 / .045),rgb(255 255 255 / .01));border:1px solid rgb(94 234 212 / .12);transition:transform .15s,border-color .2s,background .2s}
.bixcall-page .comm-list>li>button:active,.bixcall-page .comm-row:active{transform:scale(.985)}
.bixcall-page .comm-list>li>button:hover,.bixcall-page .comm-row:hover{border-color:rgb(255 215 0 / .35)}
.bixcall-page .comm-dir{display:grid;place-items:center;flex:none;width:38px;height:38px;border-radius:14px;font-weight:900;font-size:18px;border:1px solid currentColor;background:color-mix(in oklab,currentColor 12%,transparent);box-shadow:0 0 14px -4px currentColor}
.bixcall-page .comm-dir.is-in{color:#34d399}.bixcall-page .comm-dir.is-out{color:#fbbf24}.bixcall-page .comm-dir.is-miss{color:#fb7185}
.bixcall-page .comm-hbadge{font-style:normal;font-size:9px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;padding:1px 7px;border-radius:999px;border:1px solid currentColor;margin-right:4px}
.bixcall-page .comm-hbadge.is-in{color:#34d399}.bixcall-page .comm-hbadge.is-out{color:#fbbf24}.bixcall-page .comm-hbadge.is-miss{color:#fb7185}
.bixcall-page .comm-actions{display:inline-flex;gap:4px;padding:3px;border-radius:999px;background:rgb(0 0 0 / .35);border:1px solid rgb(45 212 191 / .22);flex:none}
.bixcall-page .comm-actions>button{display:grid;place-items:center;width:32px;height:32px;border-radius:999px;color:#5eead4;border:0!important;background:rgb(45 212 191 / .08)}
.bixcall-page .comm-actions>button:nth-child(3){color:#FFD700;background:rgb(255 215 0 / .08)}
.bixcall-page .comm-actions>button.is-locked{color:rgb(255 255 255 / .35)}
.bixcall-page .comm-list b{color:#f0fdfa;letter-spacing:.01em}
.bixcall-page .comm-badge{min-width:20px;height:20px;display:inline-grid;place-items:center;border-radius:999px;font-size:10px;font-weight:900;background:linear-gradient(135deg,#FFD700,#2dd4bf)!important;color:#021412!important;box-shadow:0 0 12px rgb(45 212 191 / .45)}
.bixcall-page .comm-subhead{display:flex;align-items:center;justify-content:space-between;margin:4px 2px 10px}
.bixcall-page .comm-subhead b{font-size:13px;letter-spacing:.22em;background:linear-gradient(90deg,#5eead4,#FFD700);-webkit-background-clip:text;background-clip:text;color:transparent}
@media (max-width:380px){.bixcall-page .comm-actions>button{width:28px;height:28px}}

/* === BIX CALL member chat themes (bg / font / wallpaper) === */
.bc-theme-l{margin:12px 0 6px;font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.7}
.bc-theme-row{display:flex;flex-wrap:wrap;gap:6px}
.bc-theme-row>button{display:inline-flex;align-items:center;gap:6px;padding:7px 11px;border-radius:999px;font-size:12px;border:1px solid rgb(94 234 212 / .2);background:rgb(255 255 255 / .03)}
.bc-theme-row>button[aria-pressed=true]{border-color:#FFD700;box-shadow:0 0 12px -3px #FFD700;color:#FFD700}
.bc-theme-row>button>i{width:14px;height:14px;border-radius:50%;border:1px solid rgb(255 255 255 / .3)}
.bc-theme-row.is-wall>button{flex-direction:column;border-radius:14px;padding:6px;width:calc(33% - 4px)}
.bc-wall-prev{display:block;width:100%;height:44px;border-radius:10px;background-color:#05070a}
.bx-grp-leave{display:flex;align-items:center;gap:6px;margin:6px 0;padding:8px 12px;border-radius:12px;font-size:12px;color:#fb7185;border:1px solid rgb(251 113 133 / .35);background:rgb(251 113 133 / .06)}
.bx-grp-add{margin:6px 0}.bx-grp-add .bx-grp-btn{display:inline-flex;align-items:center;gap:4px}
.bx-grp-msg.is-ok{color:#34d399}
/* wallpapers */
.bc-wall-circuit,body[data-bc-chat-wall=circuit] :is(.comm-msgs,.bx-grp-feed){background-image:linear-gradient(rgb(45 212 191 / .07) 1px,transparent 1px),linear-gradient(90deg,rgb(45 212 191 / .07) 1px,transparent 1px),radial-gradient(circle at 20px 20px,rgb(45 212 191 / .35) 2px,transparent 3px);background-size:40px 40px}
.bc-wall-hex,body[data-bc-chat-wall=hex] :is(.comm-msgs,.bx-grp-feed){background-image:radial-gradient(circle,rgb(255 215 0 / .16) 1.5px,transparent 2px),linear-gradient(60deg,transparent 48%,rgb(255 215 0 / .07) 50%,transparent 52%),linear-gradient(-60deg,transparent 48%,rgb(255 215 0 / .07) 50%,transparent 52%);background-size:28px 28px}
.bc-wall-grid,body[data-bc-chat-wall=grid] :is(.comm-msgs,.bx-grp-feed){background-image:linear-gradient(rgb(168 85 247 / .12) 1px,transparent 1px),linear-gradient(90deg,rgb(168 85 247 / .12) 1px,transparent 1px);background-size:22px 22px}
.bc-wall-cosmos,body[data-bc-chat-wall=cosmos] :is(.comm-msgs,.bx-grp-feed){background-image:radial-gradient(1px 1px at 10% 20%,#fff,transparent),radial-gradient(1.5px 1.5px at 70% 40%,#FFD700,transparent),radial-gradient(1px 1px at 40% 80%,#5eead4,transparent),radial-gradient(ellipse at 80% 10%,rgb(168 85 247 / .25),transparent 60%),radial-gradient(ellipse at 10% 90%,rgb(45 212 191 / .2),transparent 60%);background-size:120px 120px,160px 160px,90px 90px,100% 100%,100% 100%}
.bc-wall-waves,body[data-bc-chat-wall=waves] :is(.comm-msgs,.bx-grp-feed){background-image:repeating-radial-gradient(circle at 0 100%,transparent 0 18px,rgb(45 212 191 / .08) 19px 20px)}
body[data-bc-chat-wall]:not([data-bc-chat-wall=none]) :is(.comm-msgs,.bx-grp-feed){border-radius:18px;padding:10px}
/* background colours */
body[data-bc-chat-bg=toska] .bixcall-page{background:radial-gradient(ellipse at top,#0b4a42,#031a17 60%)}
body[data-bc-chat-bg=matcha] .bixcall-page{background:radial-gradient(ellipse at top,#2c4a1a,#0a1406 60%)}
body[data-bc-chat-bg=gold] .bixcall-page{background:radial-gradient(ellipse at top,#4a3608,#120c02 60%)}
body[data-bc-chat-bg=purple] .bixcall-page{background:radial-gradient(ellipse at top,#3b1470,#0b0418 60%)}
body[data-bc-chat-bg=pearl] .bixcall-page{background:linear-gradient(180deg,#f6f8f7,#e3ebe8);color:#0b1513}
body[data-bc-chat-bg=pearl] .bixcall-page :is(.comm-card,.bc-head){background:rgb(255 255 255 / .85);color:#0b1513}
body[data-bc-chat-bg=pearl] .bixcall-page .comm-list b{color:#0b1513}
/* font models */
body[data-bc-chat-font=tech] .bixcall-page{font-family:ui-monospace,'JetBrains Mono',Menlo,monospace;letter-spacing:-.01em}
body[data-bc-chat-font=lux] .bixcall-page{font-family:'Cormorant Garamond',Georgia,serif;letter-spacing:.01em}
body[data-bc-chat-font=grotesk] .bixcall-page{font-family:'Space Grotesk','Arial Narrow',system-ui,sans-serif;letter-spacing:.02em}
.bc-font-tech{font-family:ui-monospace,Menlo,monospace}.bc-font-lux{font-family:Georgia,serif}.bc-font-grotesk{font-family:'Arial Narrow',sans-serif}

/* BIX CALL: call-log bubbles inside the chat timeline */
.comm-calllog{align-self:center;display:flex;align-items:center;gap:.5rem;margin:.35rem auto;padding:.4rem .75rem;border-radius:999px;border:1px solid color-mix(in oklab,var(--primary) 40%,transparent);background:color-mix(in oklab,var(--card) 85%,transparent);font-size:11px;max-width:92%}
.comm-calllog span{display:inline-flex;align-items:center;gap:.35rem;font-weight:600}
.comm-calllog small{opacity:.65}
.comm-calllog button{border-radius:999px;padding:.15rem .55rem;font-size:10px;font-weight:700;background:color-mix(in oklab,var(--primary) 18%,transparent);color:var(--primary)}
.comm-calllog.is-missed{border-color:color-mix(in oklab,var(--destructive) 50%,transparent)}
.comm-calllog.is-missed span{color:var(--destructive)}
.bc-pay-quick{margin-left:.25rem;color:var(--primary)}

/* BIX CALL attachment sheet (no stacked buttons) */
.comm-compose{position:relative}
.bc-attach-bg{position:fixed;inset:0;z-index:40;background:rgb(0 0 0 / .35)}
.bc-attach{position:absolute;left:12px;right:12px;bottom:calc(84px + env(safe-area-inset-bottom));max-width:30rem;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:16px 10px;border-radius:22px;background:rgb(10 8 16 / .97);border:1px solid rgb(255 215 0 / .28);box-shadow:0 14px 40px rgb(0 0 0 / .55)}
.comm-compose .bc-attach button{width:auto;height:auto;border-radius:14px;background:transparent!important;box-shadow:none!important;display:flex;flex-direction:column;align-items:center;gap:6px;font-size:11px;color:rgb(240 230 255 / .9)!important;padding:4px}
.bc-attach i{display:grid;place-items:center;width:50px;height:50px;border-radius:50%;color:#0b0b10}
.bc-attach i.is-gold{background:linear-gradient(145deg,#FFD700,#b8860b)}
.bc-attach i.is-violet{background:linear-gradient(145deg,#c084fc,#7e22ce);color:#fff}
.bc-attach i.is-teal{background:linear-gradient(145deg,#2dd4bf,#0d9488)}
.bc-attach i.is-blue{background:linear-gradient(145deg,#60a5fa,#1d4ed8);color:#fff}

/* BIX CALL studio polish: studio filter, split view, telemetry, voice glow, auto-hide */
.bixcall.is-studio video.bixcall-remote.on,.bixcall.is-studio .bixcall-pip,.bixcall.is-studio .bixcall-split-self{filter:brightness(1.06) contrast(1.06) saturate(1.08)}
.bixcall.is-split .bixcall-remote.on{inset:0 0 50% 0;height:50%;object-fit:cover}
.bixcall-split-self{position:absolute;z-index:1;left:0;right:0;bottom:0;width:100%;height:50%;object-fit:cover;background:#000;border-top:1px solid rgba(255,215,0,.45)}
.bc-self-glow{box-shadow:0 0 calc(4px + var(--me,0)*22px) rgba(45,212,191,calc(.25 + var(--me,0)*.6))}
.bixcall.is-video .bixcall-remote.on:not(.bixcall-self-big){box-shadow:inset 0 0 0 calc(var(--lvl,0)*3px) rgba(255,215,0,.55)}
.bc-telemetry{position:absolute;z-index:4;top:calc(max(14px,env(safe-area-inset-top)) + 50px);left:14px;display:flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.06em;font-variant-numeric:tabular-nums;color:#FFD700;background:rgba(8,6,14,.66);border:1px solid rgba(255,215,0,.35);backdrop-filter:blur(8px)}
.bc-telemetry i{width:6px;height:6px;border-radius:50%;background:#a3a3a3}
.bc-telemetry i.is-excellent,.bc-telemetry i.is-good{background:#10b981;box-shadow:0 0 8px #10b981}
.bc-telemetry i.is-poor{background:#f59e0b;box-shadow:0 0 8px #f59e0b}
.bc-vtools{position:absolute;z-index:4;top:calc(max(14px,env(safe-area-inset-top)) + 50px);right:14px;display:flex;gap:6px}
.bc-vtools button{padding:4px 10px;border-radius:999px;font-size:10px;font-weight:800;color:#e5e7eb;background:rgba(8,6,14,.66);border:1px solid rgba(255,255,255,.2);backdrop-filter:blur(8px)}
.bc-vtools button.on{color:#05040a;background:linear-gradient(135deg,#FFD700,#2dd4bf);border-color:transparent}
