/* Isolated opaque messenger surfaces, including themes with translucent card tokens. */
:root {
  --group-surface: oklch(.18 .018 180);
  --group-ink: oklch(.96 .006 180);
  --group-muted: oklch(.73 .018 180);
  --group-accent: oklch(.78 .14 178);
  --group-edge: oklch(.37 .035 180);
  --group-backdrop: oklch(.06 .006 180 / .8);
  --group-shadow: 0 20px 60px oklch(.03 0 0 / .45);
}
html[data-color-mode="light"] {
  --group-surface: oklch(.98 .004 180);
  --group-ink: oklch(.22 .025 180);
  --group-muted: oklch(.46 .025 180);
  --group-accent: oklch(.48 .1 178);
  --group-edge: oklch(.85 .02 180);
}
.bx-grp-sheet { position:fixed; inset:0; z-index:2147483002; background:var(--group-backdrop); }
