html[data-design="v2"] {
  --ts-void: #080a0e;
  --ts-surface: #111620;
  --ts-surface-2: #1a202c;
  --ts-amber: #fbbf24;
  --ts-amber-deep: #f59e0b;
  --ts-platinum: #f8fafc;
  --ts-titanium: #94a3b8;
  --ts-hairline: rgba(148, 163, 184, 0.12);
  --background: oklch(0.145 0.008 260);
  --foreground: oklch(0.984 0.003 247.858);
  --card: oklch(0.19 0.014 262);
  --card-foreground: oklch(0.984 0.003 247.858);
  --popover: oklch(0.19 0.014 262);
  --popover-foreground: oklch(0.984 0.003 247.858);
  --primary: oklch(0.84 0.16 84);
  --primary-foreground: oklch(0.145 0.008 260);
  --secondary: oklch(0.23 0.02 262);
  --secondary-foreground: oklch(0.984 0.003 247.858);
  --muted: oklch(0.23 0.02 262);
  --muted-foreground: oklch(0.71 0.035 257);
  --accent: oklch(0.84 0.16 84);
  --accent-foreground: oklch(0.145 0.008 260);
  --border: oklch(0.71 0.035 257 / 12%);
  --input: oklch(0.71 0.035 257 / 16%);
  --ring: oklch(0.84 0.16 84 / 60%);
}
