/* RM extension: carbon dominates, quartz frames the account; color marks actions, not surfaces. */
html[data-chrono="on"] {
  --rm-carbon: oklch(0.145 0.008 260);
  --rm-chassis: oklch(0.20 0.012 260);
  --rm-quartz: oklch(0.96 0.004 100);
  --rm-quartz-grain: oklch(0.85 0.006 100);
  --rm-titanium: oklch(0.72 0.025 250);
  --rm-crimson: oklch(0.55 0.20 20);
  --rm-crimson-deep: oklch(0.40 0.15 20);
  --rm-canary: oklch(0.88 0.17 95);
  --rm-kinetic: oklch(0.76 0.15 165);
  --rm-ice: oklch(0.79 0.11 225);
  --rm-line: color-mix(in oklab, var(--rm-quartz) 18%, transparent);
  --rm-surface: linear-gradient(155deg, var(--rm-chassis), var(--rm-carbon) 70%);
