.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package :is(.duration-option,.duration-stake,.form-input,.lux-ledger,button){border-radius:10px!important}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package :is(.duration-package-head,.duration-package-body){border-radius:0!important}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package-head{background:linear-gradient(135deg,color-mix(in oklab,var(--gem,var(--tier-color)) 62%,transparent) 0%,color-mix(in oklab,var(--gem,var(--tier-color)) 30%,transparent) 55%,rgb(10 11 14/.4) 100%)!important;backdrop-filter:blur(14px);border-bottom:1px solid color-mix(in oklab,var(--gem,var(--tier-color)) 40%,transparent)!important}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package-head .duration-price{border-radius:10px!important}
html[data-color-mode="light"] .stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package{background:linear-gradient(180deg,#fff,#f6f4ee)!important;border-color:rgb(15 23 42/.1)!important;box-shadow:0 14px 30px -20px rgb(15 23 42/.35)!important}

/* Stake balance pass: even 4-corner frame, class spacing, pure sheen, vault button */
.stake-compact .duration-package{border-radius:18px!important;isolation:isolate;position:relative;clip-path:inset(0 round 18px)}
.stake-compact .duration-package::after{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;background:linear-gradient(115deg,transparent 40%,rgb(255 255 255/.10) 48%,rgb(255 255 255/.18) 50%,rgb(255 255 255/.10) 52%,transparent 60%);background-size:250% 100%;background-position:150% 0;animation:stake-sheen 8s ease-in-out infinite}
.stake-compact .duration-package:nth-child(2n)::after{animation-delay:2.5s}
.stake-compact .duration-package:nth-child(3n)::after{animation-delay:5s}
@keyframes stake-sheen{0%,78%{background-position:150% 0}100%{background-position:-60% 0}}
.stake-compact :has(>.duration-package){gap:22px!important}
.stake-compact .duration-package-head h3{letter-spacing:.04em;line-height:1.1}
.stake-compact .duration-package-head p{letter-spacing:.18em;text-transform:uppercase;font-size:10px}
.stake-compact .lux-ledger b,.stake-compact .duration-yield dd{font-variant-numeric:tabular-nums;letter-spacing:.01em}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package .duration-stake{position:relative;height:52px;border-radius:12px!important;font-weight:900;letter-spacing:.22em;text-transform:uppercase;color:#f5e6b8!important;background:linear-gradient(180deg,#3a3f48,#16181d 55%,#0b0c10)!important;border:1px solid #d4af37!important;box-shadow:inset 0 1px 0 rgb(255 255 255/.25),inset 0 -2px 0 rgb(0 0 0/.6),0 0 0 3px rgb(212 175 55/.12),0 10px 22px -12px #000!important;transition:transform .12s cubic-bezier(.3,1.6,.5,1),box-shadow .12s}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package .duration-stake::before{content:"";position:absolute;left:12px;top:50%;width:18px;height:18px;margin-top:-9px;border-radius:50%;border:2px solid #d4af37;box-shadow:inset 0 0 0 3px #16181d,inset 0 0 0 5px rgb(212 175 55/.5);transition:transform .5s}
.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact.stake-compact .duration-package .duration-stake:active{transform:translateY(2px) scale(.985);box-shadow:inset 0 3px 8px rgb(0 0 0/.7),0 0 0 3px rgb(212 175 55/.25)!important}
.stake-compact .duration-package .duration-stake:active::before{transform:rotate(180deg)}
@media (prefers-reduced-motion:reduce){.stake-compact .duration-package::after{animation:none}}

/* Wallet back face matches front */
.wallet-face--back .wallet-back-body{position:relative;z-index:1;display:flex;flex-direction:column;justify-content:space-between;height:100%;gap:10px}
.wallet-face--back::before{content:"";position:absolute;left:0;right:0;top:18%;height:36px;background:linear-gradient(180deg,#0b0c10,#22252c 50%,#0b0c10);border-block:1px solid rgb(212 175 55/.35);opacity:.9}
.wallet-face--back::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(115deg,transparent 35%,rgb(255 255 255/.08) 50%,transparent 65%)}
.wallet-back-grid{display:flex;align-items:center;gap:14px;margin-top:34px}
.wallet-back-qr{padding:8px;border-radius:12px;background:#fff;border:2px solid #d4af37;box-shadow:0 0 0 4px rgb(212 175 55/.15),0 8px 20px -8px rgb(212 175 55/.6)}
