/* HUB category press: spring + tone flare */
.hub-midnight .hub-group .hub-tile{position:relative;overflow:hidden;transition:transform .35s cubic-bezier(.3,1.7,.4,1),box-shadow .25s,border-color .25s!important}
.hub-midnight .hub-group .hub-tile::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0;background:radial-gradient(circle at 50% 35%,color-mix(in oklab,var(--tone) 45%,transparent),transparent 65%);transition:opacity .3s}
.hub-midnight .hub-group .hub-tile:active{transform:scale(.9)!important;border-color:var(--tone)!important;box-shadow:0 0 0 1px var(--tone),0 0 22px -4px var(--tone)!important;transition-duration:.08s!important}
.hub-midnight .hub-group .hub-tile:active::after{opacity:1;transition-duration:.05s}
.hub-midnight .hub-group .hub-tile:active .hub-emblem{transform:translateY(-2px) scale(1.12);animation:none}

/* BIX CALL: QR contact card (portal, square QR), save-contact, story save */
.bc-qr-overlay{position:fixed;inset:0;z-index:300;display:grid;place-items:center;padding:16px;background:rgb(4 4 8/.88);backdrop-filter:blur(8px)}
