.bx-sc .bx-sc-save:disabled{opacity:.45}

/* Main dock: larger tap targets + gold rim */
nav.glass-dock{border:1.5px solid rgb(255 215 0 / .55)!important;box-shadow:0 0 0 1px rgb(0 0 0 / .6),inset 0 1px 0 rgb(255 215 0 / .35),0 10px 28px -10px rgb(0 0 0 / .85)!important}
