/* BIXTOK comment sheet above feed + DM shortcut */
.bxt-cmt-wrap{z-index:120}
.bxt-dm{margin-left:auto;margin-right:.6rem;display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:999px;font-size:.72rem;font-weight:800;background:#A855F7;color:#fff}

/* ===== Unified polish batch (all networks) ===== */
html { -webkit-tap-highlight-color: transparent; text-rendering: optimizeLegibility; }
body { padding-top: env(safe-area-inset-top, 0px); }
:where(header.sticky, [class*="sticky"][class*="top-0"]) {
  backdrop-filter: blur(14px) saturate(140%);
}
:where(button, a[role="button"], [role="tab"]):not(:disabled) {
  transition: transform 120ms ease, filter 120ms ease;
}
:where(button, a[role="button"], [role="tab"]):not(:disabled):active {
  transform: scale(0.97);
}
:where(.tabular-nums, .font-mono, [class*="balance"], [class*="amount"]) {
  font-variant-numeric: tabular-nums lining-nums;
  letter-spacing: -0.01em;
}
:where(input[type="number"], input[inputmode="decimal"], input[inputmode="numeric"]) {
  font-variant-numeric: tabular-nums;
}
:where(.divide-y) > :where(* + *) { border-color: color-mix(in oklab, currentColor 8%, transparent); }
@media (prefers-reduced-motion: reduce) {
  :where(button, a[role="button"], [role="tab"]):active { transform: none; }
}

/* Unified glass lux: BIXMALL categories, shop cards, BIXTOK chrome, HUB grid */
.mall-cats{display:flex;gap:.45rem;overflow-x:auto;scrollbar-width:none;padding:.9rem 0 .2rem}
.mall-cats::-webkit-scrollbar{display:none}
.mall-cats button{flex-shrink:0;padding:.42rem .95rem;border-radius:999px;font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--muted-foreground);border:1px solid color-mix(in oklab,var(--chart-3) 28%,transparent);background:color-mix(in oklab,var(--card) 55%,transparent);backdrop-filter:blur(14px);transition:transform .15s}
.mall-cats button:active{transform:scale(.95)}
.mall-cats button[aria-pressed=true]{color:var(--background);background:linear-gradient(135deg,var(--chart-3),color-mix(in oklab,var(--chart-3) 70%,var(--foreground)));border-color:transparent}
.lux-shop .shop-item,.boutique-card{border-radius:16px;border:1px solid color-mix(in oklab,var(--chart-3) 26%,transparent);background:linear-gradient(165deg,color-mix(in oklab,var(--card) 70%,transparent),color-mix(in oklab,var(--background) 85%,transparent));backdrop-filter:blur(18px);box-shadow:inset 0 1px 0 color-mix(in oklab,var(--foreground) 10%,transparent),0 12px 28px -18px color-mix(in oklab,var(--background) 90%,transparent);overflow:hidden}
.lux-shop .shop-item-meta h3,.boutique-body b{line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.lux-shop .numeric,.boutique-body .numeric{font-variant-numeric:tabular-nums;letter-spacing:0}
.bixtok-tabs{padding:.3rem .7rem;border-radius:999px;background:color-mix(in oklab,var(--background) 45%,transparent);border:1px solid color-mix(in oklab,var(--foreground) 12%,transparent);backdrop-filter:blur(14px)}
.bixtok-icon,.bixtok-rail button svg{backdrop-filter:blur(12px);border-color:color-mix(in oklab,var(--chart-3) 30%,transparent)}
.bixtok-meta b{letter-spacing:.01em}.bixtok-meta p{line-height:1.45;text-shadow:0 1px 3px color-mix(in oklab,var(--background) 95%,transparent)}
.bixtok-golive,.bixtok-live-grid button{border-radius:16px;backdrop-filter:blur(16px);border-color:color-mix(in oklab,var(--chart-3) 24%,transparent)}
.hub-midnight .hub-group .hub-tile{border-radius:16px;min-height:7.2rem;justify-content:flex-start;backdrop-filter:blur(14px)}
.hub-midnight .hub-group .hub-tile .text-xs,.hub-photo-name{line-height:1.2;overflow-wrap:anywhere}
.hub-midnight .hub-group .hub-tile .text-\[10px\],.hub-photo-note{line-height:1.25;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.hub-midnight .grid.grid-cols-3,.hub-swipe{gap:.55rem}

/* ===== BIXLINK Exchanger ===== */
.ex-hero{background:radial-gradient(120% 140% at 0% 0%,color-mix(in oklab,var(--primary) 22%,transparent),transparent 55%),linear-gradient(160deg,color-mix(in oklab,var(--card) 92%,transparent),var(--background));border:1px solid color-mix(in oklab,var(--primary) 35%,var(--border))}
.ex-panel,.ex-ticker,.ex-feature{background:color-mix(in oklab,var(--card) 82%,transparent);backdrop-filter:blur(18px);border:1px solid color-mix(in oklab,var(--foreground) 10%,transparent)}
.ex-tick{border:1px solid transparent;min-width:7.5rem;transition:transform .15s,border-color .2s}
.ex-tick.is-on{border-color:color-mix(in oklab,var(--primary) 70%,transparent);background:color-mix(in oklab,var(--primary) 10%,transparent)}
.ex-tick:active{transform:scale(.96)}
.ex-chart{height:min(62vh,520px);min-height:340px;border:0;background:var(--background)}
.ex-tf{border-radius:.5rem;padding:.25rem .55rem;font-size:11px;font-weight:800;color:var(--muted-foreground);border:1px solid var(--border)}
.ex-tf.is-on{color:var(--primary-foreground);background:var(--primary);border-color:var(--primary)}
.ex-row{z-index:0}.ex-bar{position:absolute;right:0;top:0;bottom:0;z-index:-1;opacity:.16}
.ex-bar-ask{background:var(--destructive)}.ex-bar-bid{background:var(--chart-2)}
.ex-btn-gold,.ex-btn-ghost{display:inline-flex;align-items:center;gap:.4rem;border-radius:999px;padding:.6rem 1rem;font-size:11px;font-weight:900;letter-spacing:.08em}
.ex-btn-gold{background:linear-gradient(135deg,var(--primary),color-mix(in oklab,var(--primary) 70%,var(--foreground)));color:var(--primary-foreground)}
.ex-btn-ghost{border:1px solid color-mix(in oklab,var(--primary) 50%,var(--border));color:var(--primary)}
.ex-pulse{animation:exPulse 1.6s ease-in-out infinite}
@keyframes exPulse{50%{opacity:.35}}
@media (prefers-reduced-motion:reduce){.ex-pulse{animation:none}}
.kyc-reward{background:color-mix(in oklab,var(--primary) 14%,transparent);border:1px solid color-mix(in oklab,var(--primary) 45%,transparent);color:var(--primary)}
.kyc-drop{display:flex;align-items:center;gap:.5rem;border:1px dashed color-mix(in oklab,var(--primary) 45%,var(--border));border-radius:.75rem;padding:.65rem .8rem;font-size:12px;cursor:pointer;color:var(--muted-foreground)}

/* Exchanger standalone glass */
.ex-topbar{background:color-mix(in oklab,var(--background) 72%,transparent);backdrop-filter:blur(18px) saturate(150%);border-bottom:1px solid color-mix(in oklab,var(--primary) 28%,var(--border));padding-top:max(.5rem,env(safe-area-inset-top))}
.ex-icon-btn{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;border:1px solid color-mix(in oklab,var(--foreground) 14%,transparent);background:color-mix(in oklab,var(--card) 60%,transparent);transition:transform .12s}
.ex-icon-btn:active,.ex-promo:active,.ex-chip:active,.ex-tabs button:active{transform:scale(.95)}
.ex-chip{display:inline-flex;align-items:center;gap:4px;height:32px;padding:0 10px;border-radius:999px;font-size:11px;font-weight:900;border:1px solid color-mix(in oklab,var(--chart-3) 55%,transparent);color:var(--chart-3);background:color-mix(in oklab,var(--chart-3) 10%,transparent)}
.ex-chip.is-ok{border-color:color-mix(in oklab,var(--chart-2) 55%,transparent);color:var(--chart-2);background:color-mix(in oklab,var(--chart-2) 10%,transparent)}
.ex-promos{scrollbar-width:none}.ex-promos::-webkit-scrollbar{display:none}
.ex-promo{flex:0 0 72%;max-width:260px;display:grid;gap:2px;padding:12px 14px;border-radius:18px;background:linear-gradient(150deg,color-mix(in oklab,var(--card) 75%,transparent),color-mix(in oklab,var(--background) 80%,transparent));border:1px solid color-mix(in oklab,var(--foreground) 12%,transparent);backdrop-filter:blur(14px);transition:transform .12s}
.ex-promo svg{color:var(--primary)}.ex-promo b{font-size:13px;font-weight:900}.ex-promo span{font-size:11px;color:var(--muted-foreground)}
.ex-promo.is-gold{border-color:color-mix(in oklab,var(--chart-3) 60%,transparent);background:linear-gradient(140deg,color-mix(in oklab,var(--chart-3) 22%,var(--card)),var(--background))}.ex-promo.is-gold svg{color:var(--chart-3)}
@media (min-width:768px){.ex-promo{flex:1 1 0;max-width:none}}
.ex-tabs{background:color-mix(in oklab,var(--card) 65%,transparent);border:1px solid color-mix(in oklab,var(--foreground) 12%,transparent);backdrop-filter:blur(14px)}
.ex-tabs button{display:flex;align-items:center;justify-content:center;gap:4px;height:38px;border-radius:999px;font-size:11px;font-weight:900;color:var(--muted-foreground);transition:all .15s}
.ex-tabs button.is-on{background:var(--primary);color:var(--primary-foreground)}
.ex-app .ex-btn-gold,.ex-app .ex-btn-ghost{min-height:44px}

/* BIXGO driver radar */
.bixgo-radar{position:relative;width:150px;height:150px}
.bixgo-radar span{position:absolute;inset:0;border-radius:9999px;border:2px solid hsl(var(--primary)/.6);animation:bixgo-ping 2.4s ease-out infinite}
.bixgo-radar span:nth-child(2){animation-delay:.8s}.bixgo-radar span:nth-child(3){animation-delay:1.6s}
.bixgo-radar i{position:absolute;left:50%;top:50%;width:18px;height:18px;margin:-9px;border-radius:9999px;background:hsl(var(--primary));box-shadow:0 0 18px hsl(var(--primary)/.7)}
@keyframes bixgo-ping{from{transform:scale(.15);opacity:1}to{transform:scale(1);opacity:0}}
@media (prefers-reduced-motion:reduce){.bixgo-radar span{animation:none;opacity:.4}}

/* BIXGO lux vehicles + glass radar */
.bixgo-veh{--veh-hi:hsl(var(--foreground)/.22);--veh-lo:hsl(var(--foreground)/.04);--veh-line:hsl(var(--foreground)/.85);--veh-accent:hsl(var(--primary));--veh-glass:hsl(var(--primary)/.35);--veh-tyre:hsl(var(--background));filter:drop-shadow(0 4px 8px hsl(var(--primary)/.25))}
.bixgo-veh.is-vip{--veh-hi:hsl(44 30% 30%);--veh-lo:hsl(220 20% 6%);--veh-line:hsl(45 90% 62%);--veh-accent:hsl(48 100% 55%);--veh-glass:hsl(45 90% 60%/.3);filter:drop-shadow(0 4px 10px hsl(45 100% 50%/.35))}
.bixgo-veh-tile{background:linear-gradient(160deg,hsl(var(--foreground)/.07),hsl(var(--foreground)/.015));border:1px solid hsl(var(--foreground)/.1);box-shadow:inset 0 1px 0 hsl(var(--foreground)/.08)}
.bixgo-veh-tile.is-vip{border-color:hsl(45 90% 60%/.45);background:linear-gradient(160deg,hsl(45 80% 50%/.14),hsl(var(--foreground)/.02))}
.bixgo-sheet{background:hsl(var(--background)/.72);backdrop-filter:blur(22px) saturate(140%);border-top:1px solid hsl(var(--foreground)/.1);box-shadow:0 -20px 40px hsl(var(--background)/.6)}
.bixgo-radar-card{background:radial-gradient(120% 80% at 50% 0%,hsl(var(--primary)/.12),transparent 60%),linear-gradient(180deg,hsl(var(--card)/.65),hsl(var(--card)/.35));border:1px solid hsl(var(--foreground)/.1);backdrop-filter:blur(16px)}
.bixgo-sonar{position:relative;width:190px;height:190px;border-radius:9999px;background:repeating-radial-gradient(circle,transparent 0 22px,hsl(var(--primary)/.18) 22px 23px);border:1px solid hsl(var(--primary)/.35)}
.bixgo-sonar::before{content:"";position:absolute;inset:0;border-radius:inherit;background:conic-gradient(from 0deg,hsl(var(--primary)/.45),transparent 22%);animation:bixgo-spin 2.6s linear infinite}
.bixgo-sonar .blip{position:absolute;width:7px;height:7px;border-radius:9999px;background:hsl(var(--primary));box-shadow:0 0 10px hsl(var(--primary));animation:bixgo-blip 2.6s ease-in-out infinite}
.bixgo-sonar .core{position:absolute;left:50%;top:50%;width:76px;height:52px;transform:translate(-50%,-50%);display:grid;place-items:center;border-radius:18px;background:hsl(var(--background)/.75);border:1px solid hsl(var(--primary)/.4);animation:bixgo-breathe 2.4s ease-in-out infinite}
@keyframes bixgo-spin{to{transform:rotate(360deg)}}
@keyframes bixgo-blip{0%,100%{opacity:.15;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}
@keyframes bixgo-breathe{0%,100%{box-shadow:0 0 0 0 hsl(var(--primary)/.35)}50%{box-shadow:0 0 0 10px hsl(var(--primary)/0)}}
@media (prefers-reduced-motion:reduce){.bixgo-sonar::before,.bixgo-sonar .blip,.bixgo-sonar .core{animation:none}}
